  public function editar_fecha_receta(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $modelFarma = new Farmacia;
    $farmacia = $modelFarma->GetFarmaByIdfarma($request->id_farmacia);
    //var_dump($farmacia); exit;
    $receta = Receta_vale::where('id', '=', $request->id_receta)->first();
    $receta->fecha_expedicion = $request->fecha_atencion;
    $receta->fecha_registro = $request->fecha_atencion;
    $receta->save();

    $kardexs = Kardexe::where('numero_movimiento', '=', $request->nro_receta)
      ->where('tipo_movimiento', '=', 'RC')
      ->where('id_tipo_movimiento', '=', 4)
      ->where('nombre_farmacia', '=', $farmacia->nombre)->get();
    foreach ($kardexs as $k) {
      $k->fecha_movimiento = $request->fecha_atencion;
      $k->save();
    }
    Session::flash('flash_message', 'Actualización exitosa');
    return redirect('/ver_receta_atendida/' . $request->id_user . '/' . $request->nro_receta);
  }

  public function editar_fecha_salida_centro_quirurgico(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $quirurgico = \App\Models\Centro_quirurgico::where('id', '=', $request->id_centro_quirurgico)->first();
    $quirurgico->fecha_salida = $request->fecha_salida;
    $quirurgico->save();

    Session::flash('flash_message', 'Actualización exitosa');
    return redirect('/ver_centro_quirurgico/' . $request->id_user . '/' . $request->nro_quirurgico);
  }

  public function editar_medico_receta(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $receta = Receta_vale::where('id', '=', $request->id_receta)->first();
    $receta->id_medico = $request->id_medico;
    $receta->save();
    Session::flash('flash_message', 'Actualización exitosa');
    return redirect('/ver_receta_atendida/' . $request->id_user . '/' . $request->nro_receta);
  }

  public function editar_consultorio_receta(Request $request)
  {

    if (!Auth::check()) :
