  public function cambiar_estado_hospitalizado(Request $request)
  {
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $id_user = Auth::user()->id;
    $id_user_consultorio = Auth::user()->id_consultorio;

    $model_farma = new Farmacia();
    $farmacia = $model_farma->GetFarmaByUser($id_user);
    $id_farmacia = $farmacia->id;
    $id_establecimiento = $farmacia->id_establecimiento;

    if ($id_user_consultorio != 17) {
      $hospitalizacion = new \App\Models\Hospitalizacione;
      $cama_ocupada = $hospitalizacion->GetCamaById($farmacia->id_establecimiento, $request->id_hospitalizacion);
      $id_cama = $cama_ocupada->id_cama;

      $estado_cama = DB::table('camas')
        ->where('id', $id_cama)
        ->first();

      if ($estado_cama->estado == 0) {
        $db_update = DB::table('hospitalizaciones')
          ->where('id', $request->id_hospitalizacion)
          ->update(['estado' => 1, 'motivo' => $request->motivo, 'fecha_salida' => NULL, 'id_diagnostico_final' => NULL, 'condicion' => NULL]);

        $db_update = DB::table('camas')
          ->where('id', $id_cama)
          ->update(['estado' => 1]);
        //==================== 
        $cad = "select hospitalizaciones.*, camas.nombre as nombre_cama, cuartos.nombre as nombre_cuarto, medicos.nombre as nombre_medico, medicos.paterno as paterno_medico, medicos.materno as materno_medico
                from hospitalizaciones
                inner join farmacias on hospitalizaciones.id_farmacia=farmacias.id
                inner join cuartos on cuartos.id = hospitalizaciones.id_cuarto
                inner join camas on camas.id = hospitalizaciones.id_cama
                inner join medicos on medicos.id = hospitalizaciones.id_medico_alta
                where hospitalizaciones.estado=2 and farmacias.id_establecimiento =" . $id_establecimiento .
          "order by hospitalizaciones.fecha_salida DESC";
        $hospitalizado = DB::select($cad);
        $id_user_consultorio = 0;

        return view('frontend.receta_vales.all_hospitalizacion_alta_by_farmacia', compact('hospitalizado', 'farmacia', 'id_farmacia', 'id_user_consultorio'));
      } else {
        return redirect('/all_hospitalizado_alta_by_farmacia/')->withInput()->withErrors(array('No se puede invalidar su alta porque la cama del paciente esta ocupada por otro paciente ..!'));
      }
    } else {
      $db_update = DB::table('hospitalizaciones')
        ->where('id', $request->id_hospitalizacion)
        ->update(['estado' => 1, 'motivo' => $request->motivo, 'fecha_salida' => NULL, 'id_diagnostico_final' => NULL, 'condicion' => NULL]);

      $cad = "select hospitalizaciones.*,  medicos.nombre as nombre_medico, medicos.paterno as paterno_medico, medicos.materno as materno_medico
            from hospitalizaciones
            inner join farmacias on hospitalizaciones.id_farmacia=farmacias.id
            inner join medicos on medicos.id = hospitalizaciones.id_medico_alta
            where hospitalizaciones.estado=2 and tipo_hospitalizacion='HE' and farmacias.id_establecimiento =" . $id_establecimiento .
        "order by hospitalizaciones.fecha_salida DESC";
      $hospitalizado = DB::select($cad);

      return view('frontend.receta_vales.all_hospitalizacion_alta_by_farmacia', compact('hospitalizado', 'farmacia', 'id_farmacia', 'id_user_consultorio'));
    }
  }
