  public function actualizar_receta_datosbasicos(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $recetas = Receta_vale::where('id', '=', $request->id_receta)->where('id_farmacia', '=', $request->id_farmacia)->first();
    $recetas->fecha_registro = $request->fecha_registro;
    $recetas->fecha_expedicion = $request->fecha_registro;
    $recetas->save();
    Session::flash('flash_message', 'Actualización exitosa');
    return redirect('/recetas_atendidas/' . $request->id_user);
  }

  public function editar_datos_basico_receta($id_farmacia, $nro_receta)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $model_receta = new Receta_vale;
