    //--------------------------------------------
    $dispensado = Producto_receta::where('id_receta_vale', $id_receta_vale)->where('saldo', '<', 1)->get();
    $verdispensado = count($dispensado);
    //--------------------------------------
    $roles = $model_receta->GetRolesByIdUser($id_user);
    $rol_responsable = 0;
    foreach ($roles as $r) {
      if ($r->id == 3) {
        $rol_responsable = 1;
      }
    }

    $rol_dispensador = 0;
    foreach ($roles as $r) {
      if ($r->id == 5) {
        $rol_dispensador = 1;
      }
    }
    //---------------------------------------------------------------------
    $stocks = array();
    foreach ($medicamentos as $med) {
      $actual = $model_stock_farmacias->GetStockMedicamento($id_farmacia, $med->codigo);
      $stocks[] = $actual;
    }
    //---------------------------------------------------------------------            
    //return view('frontend.receta_vales.dispensar_productos', compact('cirujanos', 'medicamentos', 'recetas', 'stocks', 'fecha_actual', 'receta_devuelta', 'roles', 'rol_responsable', 'rol_dispensador', 'farmacia', 'consultorios', 'medicos', 'diagnosticos', 'procedimientos'));
    return view('frontend.receta_vales.dispensar_productos_cirugia', compact('verdispensado', 'cirujanos', 'medicamentos', 'recetas', 'stocks', 'fecha_actual', 'receta_devuelta', 'roles', 'rol_responsable', 'rol_dispensador', 'farmacia', 'consultorios', 'medicos', 'diagnosticos', 'procedimientos'));
