                      $dato_adicional = $model_hospitalizacion->GetObtenerDatos($prestacion->id_ext);
                      $recetas[0]->cama = $dato_adicional->cama;
                  endif;
                endif;
              endif;
          endif;
      else:
          $recetas[0]->talla = null;
          $recetas[0]->peso = null;
          $recetas[0]->cama = null; 
      endif;
    /**************************************************************************************************************/

    $id_receta_vale = $receta->id;
    $medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($id_receta_vale);
    $receta_devuelta = $model_receta->GetRecetaInvalidada($nro_receta, $id_farmacia, $id_receta_vale);
