    $diagnosticos_egreso = $model_receta_diagnostico->DiagnosticosByIdRecetaEgreso($id_receta_vale);
    $model_receta_medicos = new Receta_medico();
    //$cirujanos = $model_receta_medicos->CirujanonByIdReceta($id_receta_vale);
    //$anestesiologo = $model_receta_medicos->AnestesiologoByIdReceta($id_receta_vale);

    //$model_receta_procedimientos = new Receta_procedimiento();
    //$procedimientos = $model_receta_procedimientos->ProcedimietosByIdReceta($id_receta_vale);
    //--------------------------------------------
    $roles = $model_receta->GetRolesByIdUser($id_user);
    $rol_responsable = 0;
    foreach ($roles as $r) {
      if ($r->id == 3) {
        $rol_responsable = 1;
      }
    }

    $rol_dispensador = 0;
    foreach ($roles as $r) {
      if ($r->id == 5) {
        $rol_dispensador = 1;
      }
    }
    //exit(print_r($recetas));
    //---------------------------------------------------------------------
    /*
          $stocks = array();
          foreach ($medicamentos as $med) {
          $actual = $model_stock_farmacias->GetStockMedicamento($id_farmacia, $med->codigo);
          $stocks[] = $actual;
          }
         */
    //---------------------------------------------------------------------            
    //return view('frontend.receta_vales.dispensar_productos', compact('cirujanos', 'medicamentos', 'recetas', 'stocks', 'fecha_actual', 'receta_devuelta', 'roles', 'rol_responsable', 'rol_dispensador', 'farmacia', 'consultorios', 'medicos', 'diagnosticos', 'procedimientos'));
    $modo_registro = $farmacia->modo_registro;

    $farma = $modelfarma->GetFarmaByIdfarma($recetas[0]->id_farmacia);
    $establecimiento = $modelfarma->GetEstablecimientoPNP($farma->id);
    if ($tipo_repor == "1") {
      return view('frontend.receta_vales.dispensar_productos', compact('verdispensado', 'cirujanos', 'medicamentos', 'recetas', 'stocks', 'fecha_actual', 'receta_devuelta', 'roles', 'rol_responsable', 'rol_dispensador', 'farmacia', 'consultorios', 'medicos', 'diagnosticos', 'diagnosticos_egreso','procedimientos', 'flag_receta_dias', 'modo_registro', 'farma', 'establecimiento'));
    } else {
