        $id_user_consultorio = 0;
      }
    
      if($id_farmacia==12):
        return view('frontend.receta_vales.ver_hospitalizacion', compact('admision', 'fecha_actual', 'farmacia', 'consultorios', 'medicos', 'diagnosticos', 'nivel', 'id_user_consultorio', 'id_user'));
      else:
