  public function dispensar_receta(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    //----declaraciones de modelos------------------------------------------
    $stockfarmacia = new Stock_farmacia;
    $modelFarmacia = new Farmacia();
    //----Obtener el nombre de la farmacia ---------------------------------
    $farmacia = $modelFarmacia->GetFarmaByUser($request->id_user);
    $nombrefarmacia = $farmacia->nombre;
    $id_farmacia = $farmacia->id;
    //----Verifico si el producto se encuentra en stock---------------------
    $codigo_producto = $request->codigo_producto;
    $existe = $stockfarmacia->ExisteStockFarmacia($codigo_producto, $nombrefarmacia);
    //------------------------Obtener datos del formulario------------------
    $nueva_cantidad = $request->nueva_cantidad;
    $saldo = $request->saldo;
    //var_dump($saldo); exit;
    $id = $request->id_producto_receta;
    //----------------------------------------------------------------------
    //----------------------------------------------------------------------
    if ($nueva_cantidad > $request->cantidad_prescrita) {
      Session::flash('flash_message', 'La Cantidad entregada no puede ser mayor a la cantidad prescrita');
    } else {
      if ($existe) {
        //Session::flash('flash_message', 'Si contamos con este medicamento');
        $updateStock = Stock_farmacia::where('codigo_producto', $codigo_producto)->where('nombre_farmacia', $nombrefarmacia)->first();
        $nombre_producto = $updateStock->nombre_producto;
        $cantidad_actual = $updateStock->cantidad;
        if ($cantidad_actual == 0) {
          Session::flash('flash_message', 'Actualmente se encuentra sin stock este medicamento');
        } else {
          if ($cantidad_actual >= $nueva_cantidad) {
            $producto_receta = Producto_receta::where('id', $id)->first();
            $producto_receta->cantidad_dispensada = $request->cantidad_dispensada + $nueva_cantidad;
            $cantidad_dispensada = $request->cantidad_dispensada + $request->nueva_cantidad;
            $producto_receta->saldo = $request->cantidad_prescrita - ($cantidad_dispensada);
            $producto_receta->estado = 2;
            $producto_receta->save();
            $updateStock->cantidad = $cantidad_actual - $nueva_cantidad;
            $updateStock->save();

            $kardex = new Kardexe;
            $kardex->codigo_producto = $codigo_producto;
            $kardex->nombre_producto = $nombre_producto;
            $kardex->tipo_movimiento = 'RC';
            $kardex->numero_movimiento = $request->nro_receta;
            $kardex->origen = $nombrefarmacia;
            $kardex->destino = 'BENEFICIARIO';
            $kardex->estado = 1;
            $kardex->id_tipo_movimiento = 4;
            $kardex->cantidad = $nueva_cantidad;
            $kardex->nombre_farmacia = $nombrefarmacia;
            $date = Carbon::now();
            $fecha = $date->format('d-m-Y');
            $kardex->fecha_movimiento = $fecha;
            $kardex->save();
            Session::flash('flash_message', 'Atención exitosa');
          } else {
            Session::flash('flash_message', 'La cantidad para entregar supera al stock actual del medicamento');
          }
        }
      } else {
        Session::flash('flash_message', 'No contamos con este medicamento');
      }
    }
    $id_receta_vale = $request->id_receta_vale;
    //--------------------------Modelos------------------------------------
    $model_productos_receta = new Producto_receta;
    $model_stock_farmacias = new Stock_farmacia;
    $model_receta_vale = new Receta_vale;
    //---------------------------------------------------------------------         
    $medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($id_receta_vale);
    $recetas = $model_receta_vale->ShowAllById($id_receta_vale);
    //---------------------------------------------------------------------
    $stocks = array();
    foreach ($medicamentos as $med) {
      $actual = $model_stock_farmacias->GetStockMedicamento($id_farmacia, $med->codigo);
      //$cantidad=$actual->cantidad;  
      $stocks[] = $actual;
    }
    return view('frontend.receta_vales.dispensar_medicinas', compact('medicamentos', 'recetas', 'stocks'));
  }

  public function dispensar_producto(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $modelFarmacia = new Farmacia();
    $farmacia = $modelFarmacia->GetFarmaByUser($request->id_user);
    $nombrefarmacia = $farmacia->nombre;
    $id_farmacia = $farmacia->id;

    foreach ($request->id_producto as $key => $value) {
      $id = $request->id_producto_receta[$key];
      //------------------------------------------------------------------
      $updateStock = Stock_farmacia::where('codigo_producto', $request->codigo_producto[$key])
        ->where('nombre_farmacia', $nombrefarmacia)->first();
      if (count($updateStock) > 0) {
        $cantidad_actual = $updateStock->cantidad;
        $nombre_producto = $updateStock->nombre_producto;
        $updateStock->cantidad = $cantidad_actual - $request->nueva_cantidad[$key];
        $updateStock->save();
      } else {
        $producto = Producto::where('codigo', $request->codigo_producto[$key])->first();
        $nombre_producto = $producto->nombre;
      }
      //------------------------------------------------------------------
      $producto_receta = Producto_receta::where('id', $id)->first();
      $producto_receta->cantidad_dispensada = $request->nueva_cantidad[$key];
      $cantidad_dispensada = $request->nueva_cantidad[$key];
      $producto_receta->saldo = $request->cantidad_prescrita[$key] - ($cantidad_dispensada);
      $producto_receta->estado = 2;
      $producto_receta->save();
      //------------------------------------------------------------------
      //------------------------------------------------------------------            
      $receta_vale = Receta_vale::where('id', $request->id_receta_vale)->first();
      $receta_vale->estado = 1;
      $receta_vale->save();
      //------------------------------------------------------------------
      $kardex = new Kardexe;
      $kardex->codigo_producto = $request->codigo_producto[$key];
      $kardex->nombre_producto = $nombre_producto;
      $kardex->tipo_movimiento = 'RC';
      $kardex->numero_movimiento = $request->nro_receta[$key];
      $kardex->origen = $nombrefarmacia;
      $kardex->destino = 'BENEFICIARIO';
      $kardex->estado = 1;
      $kardex->id_tipo_movimiento = 4;
      $kardex->cantidad = $request->nueva_cantidad[$key];
      $kardex->nombre_farmacia = $nombrefarmacia;
      $date = Carbon::now();
      $fecha = $date->format('d-m-Y');
      $kardex->fecha_movimiento = $fecha;
      $kardex->save();
    }
    Session::flash('flash_message', 'Atención exitosa');
    //return redirect('/');
    $id_receta_vale = $request->id_receta_vale;
    //--------------------------Modelos------------------------------------
    $model_productos_receta = new Producto_receta;
    $model_stock_farmacias = new Stock_farmacia;
    $model_receta_vale = new Receta_vale;
    $model_receta_diagnostico = new Receta_diagnostico;

    //---------------------------------------------------------------------         
    $medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($id_receta_vale);
    $recetas = $model_receta_vale->ShowAllById($id_receta_vale);
    $diagnosticos_egreso = $model_receta_diagnostico->DiagnosticosByIdRecetaEgreso($id_receta_vale);

    //---------------------------------------------------------------------
    $stocks = array();
    foreach ($medicamentos as $med) {
      $actual = $model_stock_farmacias->GetStockMedicamento($id_farmacia, $med->codigo);
      //$cantidad=$actual->cantidad;  
      $stocks[] = $actual;
    }
    return view('frontend.receta_vales.dispensar_productos', compact('medicamentos', 'recetas', 'stocks', 'diagnosticos_egreso'));
  }

