  public function genera_receta_duplicado($nro_receta, $id_farmacia)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $nro_receta = $nro_receta . ".";

    $model_receta = new Receta_vale;
    $rs = $model_receta->genera_receta_duplicado($nro_receta, $id_farmacia);
    if ($rs == "") {
      $nreceta = "1";
    } else {
      $porciones = explode(".", $rs);
      $nreceta = $porciones[1];
      $nro = explode("-", $nreceta);
      $nreceta = (int) $nro[0];
      $nreceta = $nreceta + 1;
    };
    return $nreceta;
  }

