  public function registrar_transferencia(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $model_productos = new Producto;
    $model_farmacia = new Farmacia;
    $model_consultorio = new Consultorio;
    //----------------------------------------------------------------------
    $transferencia = new \App\Models\Transferencia;
    $transferencia->nro_acta = $request->nro_acta;
    $transferencia->tipo = $request->tipo;
    $transferencia->fecha = $request->fecha;
    $transferencia->nombre_jefe_farmacia_local = $request->responsable_origen;
    $transferencia->nombre_jefe_servicio = $request->responsable_destino;
    $transferencia->id_farmacia = $request->id_origen;
    $id_farmacia = $request->id_origen;
    $tipo = $request->tipo;
    if ($tipo == 1) {
      $transferencia->id_farmacia_destino = $request->id_lugar;
      $transferencia->estado = 1;
      //Estado 1: Enviado
      $farma_destino = $model_farmacia->GetFarmaByIdfarma($request->id_lugar);
      $destino = $farma_destino->nombre; // Para el kardex
    } else {
      $transferencia->id_consultorio = $request->id_lugar;
      $transferencia->estado = 2;
      //Estado 2: Enviado y Recepcionado
      $consultorio_destino = $model_consultorio->GetNombreById($request->id_lugar);
      $destino = $consultorio_destino->nombre; // Para el kardex
    }
    //--------------Obtener el nombre de la farmacia------------------------        
    $farma = $model_farmacia->GetFarmaByIdfarma($id_farmacia);
    $nombre_farmacia = $farma->nombre;
    //----------------------------------------------------------------------
    $transferencia->save();
    $id_transferencia = $transferencia->id;
    //----------------------------------------------------------------------
    foreach ($request->id_producto as $key => $value) {
      $transferencia_producto = new \App\Models\Transferencia_producto;
      $transferencia_producto->id_transferencia = $id_transferencia;
      $transferencia_producto->id_producto = $request->id_producto[$key];
      $transferencia_producto->cantidad = $request->nro_med_solictados[$key];
      $transferencia_producto->estado = 1; //Estado 1:Registrado / Estado 0: anulado
      $transferencia_producto->save();
      //-----Obtener el codigo de los productos y actualizar el stock---------------
      $producto = $model_productos->GetCodByIdProducto($request->id_producto[$key]);
      $codigo_producto = $producto->codigo;
      $updateStock = Stock_farmacia::where('codigo_producto', $codigo_producto)
        ->where('id_farmacia', $id_farmacia)->first();
      $nombre_producto = $updateStock->nombre_producto;
      $cantidad_actual = $updateStock->cantidad;
      $updateStock->cantidad = $cantidad_actual - $request->nro_med_solictados[$key];
      $updateStock->save();
      //------Registrar movimiento en el Kardexs--------------------------
      $kardex = new Kardexe;
      $kardex->codigo_producto = $codigo_producto;
      $kardex->nombre_producto = $nombre_producto;
      $kardex->tipo_movimiento = 'TRANS';
      $kardex->numero_movimiento = $request->nro_acta;
      $kardex->origen = $nombre_farmacia;
      $kardex->destino = $destino;
      $kardex->estado = 1;
      $kardex->id_tipo_movimiento = 7;
      $kardex->cantidad = $request->nro_med_solictados[$key];
      $kardex->nombre_farmacia = $nombre_farmacia;
      $kardex->fecha_movimiento = $request->fecha;
      $kardex->save();
    }
    Session::flash('flash_message', 'Transferencia exitosa');
    return redirect('/all_transferencias/' . $request->id_user);
  }

  public function registrar_receta_rua(Request $request)
  {
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $modelFarmacia = new Farmacia;
    $farmacia = $modelFarmacia->GetFarmaByUser($request->id_user);
    $numero_receta = "P-" . $request->nro_receta . "-" . $request->digitos_adicionales;
    $ValidarReceta = new Receta_vale;
    $existe_receta_registra = $ValidarReceta->ValidarReceta($numero_receta, $request->id_farmacia);
    if ($existe_receta_registra == 1) {
      Session::flash('flash_message', 'La Receta ' . $numero_receta . ' ya se encuentra registrada.');
      return redirect('/');
    } else {
      //------Declaramos modelos----------------------------------------------
      $model_farmacia = new Farmacia;
      $model_productos = new Producto;
      //----------------------------------------------------------------------
      $id_farmacia = $request->id_farmacia;
      $farma = $model_farmacia->GetFarmaByIdfarma($id_farmacia);
      $nombre_farmacia = $farma->nombre;
      //------------------Registro de la Receta Vale--------------------------

      $receta_vale = new \App\Models\Receta_vale;
      $receta_vale->id_farmacia = $request->id_farmacia;
      $receta_vale->id_user = $request->id_user;
      $receta_vale->id_consultorio = $request->id_consultorio;
      $receta_vale->nro_receta = "P-" . $request->nro_receta . "-" . $request->digitos_adicionales;
      $receta_vale->dni_beneficiario = $request->dni_beneficiario;
      $receta_vale->nombre_beneficiario = $request->nombre_beneficiario;
      $receta_vale->paterno_beneficiario = $request->paterno_beneficiario;
      $receta_vale->materno_beneficiario = $request->materno_beneficiario;
      $receta_vale->tipo_beneficiario = $request->tipo_beneficiario;
      $receta_vale->dni_titular = $request->dni_titular;
      $receta_vale->fecha_expedicion = $request->fecha_expedicion;
      //$receta_vale->fecha_registro = Carbon::now();
      $receta_vale->fecha_registro = $request->fecha_expedicion;
      $receta_vale->id_diagnostico = $request->id_diagnostico;
      $receta_vale->nro_historia = $request->nro_historia;
      $receta_vale->grado = $request->grado;
      $receta_vale->id_medico = $request->id_medico;
      $receta_vale->tipo_receta = $request->tipo_receta;
      $receta_vale->turno = $request->turno;
      $receta_vale->estado = 1;
      if ($request->tipo == "dni") {
        $receta_vale->nro_rua = "SMPA-" . $request->nro_rua;
      } else {
        $receta_vale->nro_rua = $request->nro_rua;
      }
      $receta_vale->save();
      $id_receta_vale = $receta_vale->id;
      //--------------Fin del Registro de la Receta Vale----------------------
      if (empty($id_receta_vale)) {
        Session::flash('flash_message', 'No se registro los datos de la receta, hubo un problema con la conexion de internet,'
          . ' capturar la pantalla y enviar la incidencia a los correos: rencisoc@saludpol.gob.pe / goliverar@saludpol.gob.pe');
      } else {
        foreach ($request->id_producto as $key => $value) {
          //-----Registro de la tabla producto_receta ------------------------
          $producto_receta = new Producto_receta;
          $producto_receta->id_receta_vale = $id_receta_vale;
          $producto_receta->id_producto = $request->id_producto[$key];
          $producto_receta->cantidad_prescrita = $request->nro_med_solictados[$key];
          $producto_receta->cantidad_dispensada = $request->nro_med_entregados[$key];
          $producto_receta->saldo = $request->nro_med_solictados[$key] - $request->nro_med_entregados[$key];
          $producto_receta->estado = 2;
          $producto_receta->save();
          $id_producto_receta = $producto_receta->id;
          if (empty($id_producto_receta)) {
            Session::flash('flash_message', 'No se registro los productos dispensados de la receta, hubo un problema con la conexion de internet,'
              . ' capturar la pantalla y enviar la incidencia a los correos: rencisoc@saludpol.gob.pe / goliverar@saludpol.gob.pe');
          }

          $producto = Producto::where('id', $request->id_producto[$key])->first();
          $codigo_producto = $producto->codigo;
          $nombre_producto = $producto->nombre;

          $kardex = new Kardexe;
          $kardex->codigo_producto = $codigo_producto;
          $kardex->nombre_producto = $nombre_producto;
          $kardex->tipo_movimiento = 'RC';
          $kardex->numero_movimiento = "P-" . $request->nro_receta . "-" . $request->digitos_adicionales;
          $kardex->origen = $nombre_farmacia;
          $kardex->destino = 'BENEFICIARIO';
          $kardex->estado = 1;
          $kardex->id_tipo_movimiento = 4;
          $kardex->cantidad = $request->nro_med_entregados[$key];
          $kardex->nombre_farmacia = $nombre_farmacia;
          $kardex->fecha_movimiento = $request->fecha_expedicion;
          $kardex->save();
          /* -----Agregar cantidades en stock lotes --------------------------- */
          $idkardex = $kardex->id;
          //CADENA DE LOTE ID   

          if ($request->lotes_lote[$key] != "") {

            $cadena_lote_lote = $request->lotes_lote[$key];
            $cadena_lote_registro_sanitario = $request->lotes_registro_sanitario[$key];
            $cadena_lote_fecha_vencimiento = $request->lotes_fecha_vencimiento[$key];
            $cadena_lote_cantidad = $request->lotes_cantidad[$key];
            $lote_lote = explode("||", $cadena_lote_lote);
            $lote_registro_sanitario = explode("||", $cadena_lote_registro_sanitario);
            $lote_fecha_vencimiento = explode("||", $cadena_lote_fecha_vencimiento);
            $lote_cantidad = explode("||", $cadena_lote_cantidad);
            //var_dump($cantidad_lotes); exit;
            foreach ($lote_lote as $indice => $valor) {
              //$lote_id = $valor;
              //$cantidad_lote = $lote_cantidad[$indice];
              //--------------------------------------------
              $kardex_lote = new \App\Models\Kardex_lote;
              //$kardex_lote->id_stock_lote = $lote_id;

              $kardex_lote->id_kardex = $idkardex;
              $kardex_lote->lote = $valor;
              $kardex_lote->fecha_vencimiento = $lote_fecha_vencimiento[$indice];
              $kardex_lote->registro_sanitario = $lote_registro_sanitario[$indice];
              $kardex_lote->cantidad = $lote_cantidad[$indice];
              $kardex_lote->fecha_registro = $request->fecha_expedicion;
              $kardex_lote->save();

              /*
                              $stock_lote = \App\Models\Stock_lote::where('id', '=', $lote_id)->first();
                              $cantidad_stock_lote_actual = $stock_lote->cantidad;
                              $stock_lote->cantidad = $cantidad_stock_lote_actual - $cantidad_lote;
                              $stock_lote->save();
                             */
            }
          }
        }
      }
      Session::flash('flash_message', 'Atención exitosa');
      //--------------------------Modelos------------------------------------
      $model_productos_receta = new Producto_receta;
      $model_stock_farmacias = new Stock_farmacia;
      $model_receta_vale = new Receta_vale;
      $model_receta_diagnostico = new Receta_diagnostico;

      //----------------------------------------------------------------------
      $roles = $model_receta_vale->GetRolesByIdUser($request->id_user);
      $rol_responsable = 0;
      foreach ($roles as $r) {
        if ($r->id == 3) {
          $rol_responsable = 1;
        }
      }

      $rol_dispensador = 0;
      foreach ($roles as $r) {
        if ($r->id == 5) {
          $rol_dispensador = 1;
        }
      }
      //---------------------------------------------------------------------         
      $medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($id_receta_vale);
      $recetas = $model_receta_vale->ShowAllById($id_receta_vale);
      $diagnosticos_egreso = $model_receta_diagnostico->DiagnosticosByIdRecetaEgreso($id_receta_vale);
      //---------------------------------------------------------------------
      $stocks = array();
      foreach ($medicamentos as $med) {
        $actual = $model_stock_farmacias->GetStockMedicamento($id_farmacia, $med->codigo);
        //$cantidad=$actual->cantidad;  
        $stocks[] = $actual;
      }
      return view('frontend.receta_vales.dispensar_productos', compact('medicamentos', 'recetas', 'diagnosticos_egreso', 'stocks', 'fecha_actual', 'roles', 'rol_responsable', 'rol_dispensador', 'farmacia'));
    }
  }

  public function dispensar_producto_cirugia(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $obtenerId = DB::Transaction(function () use ($request) {
      $model_productos = new Producto;
      $model_farmacia = new Farmacia;
      $model_receta = new Receta_vale;
      $id_farmacia = $request->id_farmacia;
      $farma = $model_farmacia->GetFarmaByIdfarma($id_farmacia);
      $nombre_farmacia = $farma->nombre;
      $suma = 0;
      foreach ($request->id_producto as $key => $value) {
        //-----Registro de la tabla producto_receta ------------------------
        $producto_receta = Producto_receta::where('id', $request->id_producto_receta[$key])->first();
        //$producto_receta->id_receta_vale = $request->id_receta_vale;
        $producto_receta->id_producto = $request->id_producto[$key];
        $producto_receta->cantidad_prescrita = $request->nro_med_solictados[$key];
        $producto_receta->cantidad_dispensada = $request->nro_med_entregados[$key];
        $producto_receta->saldo = $request->nro_med_solictados[$key] - $request->nro_med_entregados[$key];
        $producto_receta->estado = 2;
        $producto_receta->save();
        $id_producto_receta = $producto_receta->id;
        $receta_vale = $model_receta->ObtenerDatosRecetaVale($request->id_receta_vale);
        if (empty($id_producto_receta)) {
          Session::flash('flash_message', 'No se registro los productos dispensados de la receta, hubo un problema con la conexion de internet,'
            . ' capturar la pantalla y enviar la incidencia a los correos: rencisoc@saludpol.gob.pe / goliverar@saludpol.gob.pe');
        } else {
          $producto = $model_productos->GetCodByIdProducto($request->id_producto[$key]);
          $codigo_producto = $producto->codigo;
          //-----Fin del Registro de la tabla producto_receta ----------------
          $updateStock = Stock_farmacia::where('codigo_producto', $codigo_producto)->where('id_farmacia', $id_farmacia)->first();
          if (count($updateStock) > 0) {
            $nombre_producto = $updateStock->nombre_producto;
            $cantidad_actual = $updateStock->cantidad;
            $updateStock->cantidad = $cantidad_actual - $request->nro_med_entregados[$key];
            $updateStock->save();
          } else {
            $producto = Producto::where('codigo', $codigo_producto)->first();
            $nombre_producto = $producto->nombre;
          }
          $pu_productos = $model_receta->PUdeProductosSegunKardex($nombre_farmacia, $receta_vale->fecha_registro);
          foreach ($pu_productos as $pu) {
            if ($pu->codigo_producto == $codigo_producto) {
              $subtotal = ($request->nro_med_entregados[$key]) * $pu->pu;
              $suma = $suma + $subtotal;
            }
          }
        }
        $kardex = new Kardexe;
        $kardex->codigo_producto = $codigo_producto;
        $kardex->nombre_producto = $nombre_producto;
        $kardex->tipo_movimiento = 'RC';
        $kardex->numero_movimiento = $request->nro_receta;
        $kardex->origen = $nombre_farmacia;
        $kardex->destino = 'BENEFICIARIO';
        $kardex->estado = 1;
        $kardex->id_tipo_movimiento = 4;
        $kardex->cantidad = $request->nro_med_entregados[$key];
        $kardex->nombre_farmacia = $nombre_farmacia;
        $kardex->fecha_movimiento = $request->fecha_expedicion;
        $kardex->save();
        /* -----Agregar cantidades en stock lotes --------------------------- */
        $idkardex = $kardex->id;
        //CADENA DE LOTE ID   
        if ($request->lotes_id[$key] != "") {
          $cadena_lote_id = $request->lotes_id[$key];
          $cadena_cantidad_id = $request->lotes_cantidad[$key];
          $lote_ids = explode("||", $cadena_lote_id);
          $cantidad_lotes = explode("||", $cadena_cantidad_id);
          foreach ($lote_ids as $indice => $valor) {
            $lote_id = $valor;
            $cantidad_lote = $cantidad_lotes[$indice];
            //--------------------------------------------               
            $kardex_lote = new \App\Models\Kardex_lote;
            $kardex_lote->id_stock_lote = $lote_id;
            $kardex_lote->id_kardex = $idkardex;
            $kardex_lote->cantidad = $cantidad_lote;
            //$kardex_lote->fecha_registro = "gfdsgdfsgsdgjhjfdsg";
            $kardex_lote->fecha_registro = $request->fecha_expedicion;
            $kardex_lote->save();
            $stock_lote = \App\Models\Stock_lote::where('id', '=', $lote_id)->first();
            $cantidad_stock_lote_actual = $stock_lote->cantidad;
            $stock_lote->cantidad = $cantidad_stock_lote_actual - $cantidad_lote;
            $stock_lote->save();
          }
        }
      }
      $update_receta_vale = $model_receta->ObtenerDatosRecetaVale($request->id_receta_vale);
      $update_receta_vale->total = $suma;
      $update_receta_vale->save();
      return ($request->id_receta_vale);
    });
    if ($obtenerId == 0) {
      Session::flash('flash_message', 'No se pudo registrar la Receta, hubo un problema con la conexión de internet de su establecimiento PNP, vuelva a intentarlo nuevamente');
      return redirect('/nueva_receta/' . $request->id_user . '/' . $request->id_farmacia);
    } else {
      //--------------------------Modelos------------------------------------
      $model_productos_receta = new Producto_receta;
      $model_stock_farmacias = new Stock_farmacia;
      $model_receta_vale = new Receta_vale;
      $model_diagnosticos = new Receta_diagnostico;
      //----------------------------------------------------------------------
      $dispensado = Producto_receta::where('id_receta_vale', $request->id_receta_vale)->where('saldo', '<', 1)->get();
      $verdispensado = count($dispensado);
      //----------------------------------------------------------------------
      $roles = $model_receta_vale->GetRolesByIdUser($request->id_user);
      $rol_responsable = 0;
      foreach ($roles as $r) {
        if ($r->id == 3) {
          $rol_responsable = 1;
        }
      }
      $rol_dispensador = 0;
      foreach ($roles as $r) {
        if ($r->id == 5) {
          $rol_dispensador = 1;
        }
      }
      //---------------------------------------------------------------------
      $modelConsultorio = new Consultorio;
      $consultorios = $modelConsultorio->ShowConsultorios($id_farmacia);
      //--------------------------------------------
      $modelMedico = new \App\Models\Medico;
      $medicos = $modelMedico->ShowMedicosByIpress($request->id_farmacia);
      //--------------------------------------------
      $modelFarmacia = new Farmacia;
      $farmacia = $modelFarmacia->GetFarmaByUser($request->id_user);
      //------------------------------------------------------------------------
      $medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($obtenerId);
      $recetas = $model_receta_vale->ShowAllById($obtenerId);
      //$medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($id_receta_vale);
      //$recetas = $model_receta_vale->ShowAllById($id_receta_vale);
      //---------------------------------------------------------------------
      $stocks = array();
      foreach ($medicamentos as $med) {
        //$actual = $model_stock_farmacias->GetStockMedicamento($id_farmacia, $med->codigo);
        $actual = $model_stock_farmacias->GetStockMedicamento($request->id_farmacia, $med->codigo);
        //$cantidad=$actual->cantidad;  
        $stocks[] = $actual;
      }

      $diagnosticos = $model_diagnosticos->DiagnosticosByIdReceta($obtenerId);
      //--------------------------------------------        
      $model_receta_medicos = new Receta_medico();
      $cirujanos = $model_receta_medicos->CirujanonByIdReceta($obtenerId);
      $model_receta_procedimientos = new Receta_procedimiento();
      $procedimientos = $model_receta_procedimientos->ProcedimietosByIdReceta($obtenerId);
      //----------------------------------------------------------------------


      $date = Carbon::now();
      $fecha_actual = $date->format('d-m-Y');
      Session::flash('flash_message', 'Atención exitosa');
      return view('frontend.receta_vales.dispensar_productos_cirugia', compact('verdispensado', 'cirujanos', 'medicamentos', 'recetas', 'stocks', 'fecha_actual', 'roles', 'rol_responsable', 'rol_dispensador', 'farmacia', 'consultorios', 'medicos', 'diagnosticos', 'procedimientos'));
    }
  }

  public function registrar_receta_rua_transaction_cirugia(Request $request)
