                  $stock_lote = \App\Models\Stock_lote::where('id', '=', $lote_id)->first();
                  $cantidad_stock_lote_actual = $stock_lote->cantidad;
                  $stock_lote->cantidad = $cantidad_stock_lote_actual - $cantidad_lote;
                  $stock_lote->save();
                }
              }
            }
          }
          return $id_receta_vale;
        });
        if ($obtenerId == 0) {
