        Session::flash('flash_message', 'La Receta ' . $numero_receta . ' ya se encuentra registrada.');
        return redirect('/');
      } else {
        $obtenerId = DB::Transaction(function () use ($request) {
          //------Declaramos modelos----------------------------------------------
          $model_farmacia = new Farmacia;
          $model_productos = new Producto;
          $model_receta_medico = new Receta_medico;
          $model_receta_diagnostico = new Receta_diagnostico;
          //----------------------------------------------------------------------
