          $nombre_farmacia = $farma->nombre;
          //------------------Registro de la Receta Vale--------------------------
          $receta_vale = new \App\Models\Receta_vale;
          $receta_vale->id_farmacia = $request->id_farmacia;
          $receta_vale->id_user = $request->id_user;
          $receta_vale->id_consultorio = $request->id_consultorio;
