          $receta_vale->nombre_beneficiario = $request->nombre_beneficiario;
          $receta_vale->paterno_beneficiario = $request->paterno_beneficiario;
          $receta_vale->materno_beneficiario = $request->materno_beneficiario;
          $receta_vale->tipo_beneficiario = $request->tipo_beneficiario;
          $receta_vale->dni_titular = $request->dni_titular;
          $receta_vale->fecha_expedicion = $request->fecha_expedicion;
          //$receta_vale->fecha_registro = Carbon::now();
          $receta_vale->fecha_registro = $request->fecha_expedicion;
          $receta_vale->fecha_intervencion = $request->fecha_intervencion;
          $receta_vale->id_diagnostico = $request->id_diagnostico;
          $receta_vale->nro_historia = $request->nro_historia;
          $receta_vale->grado = $request->grado;
          $receta_vale->id_medico = $request->id_medico;
          $receta_vale->tipo_receta = $request->tipo_receta;
          $receta_vale->turno = $request->turno;
          $receta_vale->estado = 1;
          if ($request->tipo == "dni") {
            $receta_vale->nro_rua = "SMPA-" . $request->nro_rua;
          } else {
            $receta_vale->nro_rua = $request->nro_rua;
          }
          $receta_vale->save();
          $id_receta_vale = $receta_vale->id;
          $update_contador = Contador_receta::where('id_farmacia', $request->id_farmacia)->first();
          $actual = $update_contador->numero + 1;
          Contador_receta::where('id_farmacia', $request->id_farmacia)
            ->update(['numero' => $actual]);
          //----------------------------------------------------------------------
          if ($request->id_medico_segundo != 0) {
            $medico_segundo = new Receta_medico();
            $medico_segundo->id_receta_vale = $id_receta_vale;
            $medico_segundo->id_medico = $request->id_medico_segundo;
            $medico_segundo->estado = 1;
            $medico_segundo->tipo = 2;
            $medico_segundo->save();
          }
          if ($request->id_medico_tercero != 0) {
            $medico_tercero = new Receta_medico();
            $medico_tercero->id_receta_vale = $id_receta_vale;
            $medico_tercero->id_medico = $request->id_medico_tercero;
            $medico_tercero->estado = 1;
            $medico_tercero->tipo = 2;
            $medico_tercero->save();
          }

          $anasteciologo = new Receta_medico();
          $anasteciologo->id_receta_vale = $id_receta_vale;
          $anasteciologo->id_medico = $request->id_anasteciologo;
          $anasteciologo->estado = 1;
          $anasteciologo->tipo = 1;
          $anasteciologo->save();

          $enfermera_principal = new Receta_medico();
          $enfermera_principal->id_receta_vale = $id_receta_vale;
          $enfermera_principal->id_medico = $request->id_enfermera_principal;
          $enfermera_principal->estado = 1;
          $enfermera_principal->tipo = 1;
          $enfermera_principal->save();

          if ($request->id_enfermera_secundaria != 0) {
            $enfermera_secundaria = new Receta_medico();
