            $enfermera_secundaria->estado = 1;
            $enfermera_secundaria->tipo = 2;
            $enfermera_secundaria->save();
          }

          //-----------------------------------------------------------------------
          if ($request->id_diagnostico_segundo != "") {
            $segundo_dignostico = new Receta_diagnostico();
            $segundo_dignostico->id_receta_vale = $id_receta_vale;
            $segundo_dignostico->id_diagnostico = $request->id_diagnostico_segundo;
            $segundo_dignostico->estado = 1;
            $segundo_dignostico->save();
          }
          if ($request->id_diagnostico_tercero != "") {
            $tercero_dignostico = new Receta_diagnostico();
            $tercero_dignostico->id_receta_vale = $id_receta_vale;
            $tercero_dignostico->id_diagnostico = $request->id_diagnostico_tercero;
            $tercero_dignostico->estado = 1;
            $tercero_dignostico->save();
          }
          //-----------------------------------------------------------------------
          $primer_procedimiento = new Receta_procedimiento();
          $primer_procedimiento->id_receta_vale = $id_receta_vale;
          $primer_procedimiento->id_procedimiento = $request->id_procedimiento_primero;
          $primer_procedimiento->estado = 1;
          $primer_procedimiento->tipo = 1;
          $primer_procedimiento->save();

          if ($request->id_procedimiento_segundo != "") {
            $segundo_procedimiento = new Receta_procedimiento();
            $segundo_procedimiento->id_receta_vale = $id_receta_vale;
            $segundo_procedimiento->id_procedimiento = $request->id_procedimiento_segundo;
            $segundo_procedimiento->estado = 1;
            $segundo_procedimiento->tipo = 2;
            $segundo_procedimiento->save();
          }

          if ($request->id_procedimiento_tercero != "") {
            $tercer_procedimiento = new Receta_procedimiento();
            $tercer_procedimiento->id_receta_vale = $id_receta_vale;
            $tercer_procedimiento->id_procedimiento = $request->id_procedimiento_tercero;
            $tercer_procedimiento->estado = 1;
            $tercer_procedimiento->tipo = 2;
            $tercer_procedimiento->save();
          }
          //--------------Fin del Registro de la Receta Vale----------------------   
          if (empty($id_receta_vale)) {
            Session::flash('flash_message', 'No se registro los datos de la receta, hubo un problema con la conexion de internet,'
              . ' capturar la pantalla y enviar la incidencia a los correos: rencisoc@saludpol.gob.pe / goliverar@saludpol.gob.pe');
          } else {
            foreach ($request->id_producto as $key => $value) {
              //-----Registro de la tabla producto_receta ------------------------
              $producto_receta = new Producto_receta;
              $producto_receta->id_receta_vale = $id_receta_vale;
              $producto_receta->id_producto = $request->id_producto[$key];
              $producto_receta->cantidad_prescrita = $request->nro_med_solictados[$key];
              $producto_receta->cantidad_dispensada = 0;
              $producto_receta->saldo = $request->nro_med_solictados[$key] - 0;
              $producto_receta->estado = 2;
              $producto_receta->save();
            }
          }
          return $id_receta_vale;
        });
        if ($obtenerId == 0) {
          Session::flash('flash_message', 'No se pudo registrar la Receta, hubo un problema con la conexión de internet de su establecimiento PNP, vuelva a intentarlo nuevamente');
          return redirect('/nueva_receta/' . $request->id_user . '/' . $request->id_farmacia);
        } else {
          //--------------------------Modelos------------------------------------
          $model_productos_receta = new Producto_receta;
          $model_stock_farmacias = new Stock_farmacia;
          $model_receta_vale = new Receta_vale;
          $model_diagnosticos = new Receta_diagnostico;
          //----------------------------------------------------------------------
          $dispensado = Producto_receta::where('id_receta_vale', $obtenerId)->where('saldo', '<', 1)->get();
          $verdispensado = count($dispensado);
          //----------------------------------------------------------------------
          $roles = $model_receta_vale->GetRolesByIdUser($request->id_user);
          $rol_responsable = 0;
          foreach ($roles as $r) {
            if ($r->id == 3) {
              $rol_responsable = 1;
            }
          }
          $rol_dispensador = 0;
          foreach ($roles as $r) {
            if ($r->id == 5) {
              $rol_dispensador = 1;
            }
          }

          $modelConsultorio = new Consultorio;
          $consultorios = $modelConsultorio->ShowConsultorios($request->id_farmacia);

          $medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($obtenerId);
          $recetas = $model_receta_vale->ShowAllById($obtenerId);
          //$medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($id_receta_vale);
          //$recetas = $model_receta_vale->ShowAllById($id_receta_vale);
          //---------------------------------------------------------------------
          $stocks = array();
          foreach ($medicamentos as $med) {
            //$actual = $model_stock_farmacias->GetStockMedicamento($id_farmacia, $med->codigo);
            $actual = $model_stock_farmacias->GetStockMedicamento($request->id_farmacia, $med->codigo);
            //$cantidad=$actual->cantidad;  
            $stocks[] = $actual;
          }

          $diagnosticos = $model_diagnosticos->DiagnosticosByIdReceta($obtenerId);
          //--------------------------------------------        
          $model_receta_medicos = new Receta_medico();
          $cirujanos = $model_receta_medicos->CirujanonByIdReceta($obtenerId);
          $model_receta_procedimientos = new Receta_procedimiento();
          $procedimientos = $model_receta_procedimientos->ProcedimietosByIdReceta($obtenerId);
          //----------------------------------------------------------------------
          $date = Carbon::now();
          $fecha_actual = $date->format('d-m-Y');
          Session::flash('flash_message', 'Atención exitosa');
          return view('frontend.receta_vales.dispensar_productos_cirugia', compact('verdispensado', 'cirujanos', 'medicamentos', 'recetas', 'stocks', 'fecha_actual', 'roles', 'rol_responsable', 'rol_dispensador', 'farmacia', 'consultorios', 'medicos', 'diagnosticos', 'procedimientos'));
        }
      }
    } else {
      Session::flash('flash_message', 'Registro incorrecto de la Receta, usted no ha seleccionado los productos para dispensar, vuelva a intentarlo...!!');
      return redirect('/nueva_receta/' . $request->id_user . '/' . $request->id_farmacia);
    }
  }

