  public function obtener_receta($id_farmacia, $nro_receta)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $model_receta = new Receta_vale;
    $model_productos = new Producto_receta;
    $model_diagnosticos = new Receta_diagnostico;
    $model_producto = new Producto();

    //$receta = $model_receta->GetRecetaByFarmaciaAndNroReceta($id_farmacia, $nro_receta);
    $receta = $model_receta->GetRecetaByEstablecimientoAndNroReceta(76, $nro_receta, 2019);
    $existe_kardex = Kardexe::where('id_nro_movimiento', $receta[0]->id)->first();
    if (count($existe_kardex) > 0) {
      $productos = $model_productos->ShowMedicinasById_receta_vale_resto($receta[0]->id);
    } else {
      $productos = $model_productos->ShowMedicinasById_receta_vale($receta[0]->id);
    }
    $diagnosticos = $model_diagnosticos->DiagnosticosByIdReceta($receta[0]->id);

    $model_kardex = new Kardexe();
    $fecha_fin = $model_kardex->getFechaServidor();
    $id_farmacia = Auth::user()->id_farmacia;
    $farmacia = DB::table('farmacias')->where('id', '=', $id_farmacia)->first();
    $id_establecimiento = $farmacia->id_establecimiento;

    $cantidad_dispensada = 0;
    $stock = array();
    $stockAlmacen = array();
    $stockEstablecimiento = array();
    $stock_principal = array();
    /*
    if (App::environment('desarrollo')):
      $client = new SoapClient(env('WS_URL_DESARROLLO')."/ws/ws_logistica.php?wsdl", array('login' => 'userafis@ludpol', 'password' => "WS@ludPol@fi"));
    elseif (App::environment('local')):
      $client = new SoapClient(env('WS_URL_REMOTO')."/webservices/server.php?wsdl", array('login' => 'userafis@ludpol', 'password' => "WS@ludPol@fi"));
    endif;
    */
    //$client = new SoapClient(env('WI_SALUDPOL_URL')."/webservices/server.php?wsdl", array('login' => env('WI_SALUDPOL_USERNAME1'), 'password' => env('WI_SALUDPOL_PASSWORD1')));
    $id_farmacia_almacen = 113;

    foreach ($productos as $key => $prod) :

      $cantidad_dispensada = 0;
      //$producto = $model_producto->GetCodByIdProducto($prod->id_producto);
      //$codigo_producto = $producto->codigo;
      /*
      $total = $model_kardex->ShowTotalByIdProductoAndIdFarmacia($prod->id_producto, $id_farmacia, $fecha_fin);
      $cantidad = 0;
      if (isset($total->total) && $total->total > 0){
        $cantidad = $total->total;
        //$cantidad_dispensada = $productos[$key]->cantidad_prescrita;
        $cantidad_dispensada = ($productos[$key]->cantidad_prescrita <=$total->total)?$productos[$key]->cantidad_prescrita:$total->total;
      }
      $stock[$prod->id_producto]=$cantidad;
      */


      /***********************************/
      $cantidadAlmacen = 0;
      //$cantidadAlmacen = $client->ObtenerStockProducto($codigo_producto,date("Y")/*"2020"*/);
      $totalAlmacen = $model_kardex->ShowTotalByIdProductoAndIdFarmacia($prod->id_producto, $id_farmacia_almacen, $fecha_fin);
      if (isset($totalAlmacen->total) && $totalAlmacen->total > 0) $cantidadAlmacen = $totalAlmacen->total;

      $cantidadEstablecimiento = 0;
      $totalEstablecimiento = $model_kardex->ShowTotalCantidadByIdProductoAndIdEstablecimiento($prod->id_producto, $id_establecimiento, $fecha_fin);
      if (isset($totalEstablecimiento->total) && $totalEstablecimiento->total > 0) $cantidadEstablecimiento = $totalEstablecimiento->total;

      $stockAlmacen[$prod->id_producto] = $cantidadAlmacen;
      $stockEstablecimiento[$prod->id_producto] = $cantidadEstablecimiento;

      /***********************************/

      $kardex_principal = $model_kardex->ShowTotalByIdProductoAndIdFarmacia($prod->id_producto, 3, $fecha_fin);
      $cantidad_pr = 0;
      $farmacia_pr = "";
      if (isset($kardex_principal->total) && $kardex_principal->total > 0) {
        $cantidad_pr = $kardex_principal->total;
        $farmacia_pr = $kardex_principal->farmacia;

        $cantidad_dispensada = ($productos[$key]->cantidad_prescrita <= $kardex_principal->total) ? $productos[$key]->cantidad_prescrita : $kardex_principal->total;
      }
      $stock_principal[$prod->id_producto]["cantidad"] = $cantidad_pr;
      $stock_principal[$prod->id_producto]["farmacia"] = $farmacia_pr;

      $productos[$key]->cantidad_dispensada = $cantidad_dispensada;

    endforeach;

    $array = array();
    $array["receta"] = $receta[0];
    $array["productos"] = $productos;
    $array["stock"] = $stock;
    $array["stockAlmacen"] = $stockAlmacen;
    $array["stockEstablecimiento"] = $stockEstablecimiento;
    $array["stock_principal"] = $stock_principal;
    $array["diagnosticos"] = $diagnosticos;
    echo json_encode($array);
  }


