  public function registrar_receta_rua_transaction(Request $request)
  {
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $codigo_comparar = "";
    foreach ($request->id_producto as $key => $value) {
      $prod = Producto::where('id', $request->id_producto[$key])->first();
      $codigo_pro = $prod->codigo;
      if ($codigo_comparar == $codigo_pro) {
        Session::flash('flash_message', 'No se registro la receta, por que dispensó 2 o mas veces el producto ' . $prod->nombre);
        return redirect('/nueva_receta/' . $request->id_user . '/' . $request->id_farmacia);
      } else {
        $codigo_comparar = $codigo_pro;
      }
    }

    $modelFarmacia = new Farmacia;
    $farmacia = $modelFarmacia->GetFarmaByUser($request->id_user);
    $numero_receta = "P-" . $request->nro_receta . "-" . $request->digitos_adicionales;
    $ValidarReceta = new Receta_vale;
    //--------------------------------------------
    $existe_receta_registra = $ValidarReceta->ValidarReceta($numero_receta, $request->id_farmacia);

    if ($existe_receta_registra == 1 && $request->modo_registro != 1 && $request->tipo_registro != 2) {
      Session::flash('flash_message', 'La Receta ' . $numero_receta . ' ya se encuentra registrada.');
      return redirect('/nueva_receta/' . $request->id_user . '/' . $request->id_farmacia);
    } else {

      $p_detalle = "";
      $p_detalle .= "{";
      foreach ($request->id_producto as $key => $value) :
        $p_detalle .= "{";
        $p_detalle .= $request->id_producto[$key] . ",";
        $p_detalle .= $request->tiempo_periodo[$key] . ",";
        $p_detalle .= $request->nro_med_solictados[$key] . ",";
        $p_detalle .= (isset($request->nro_med_entregados[$key]) && $request->nro_med_entregados[$key] != "") ? $request->nro_med_entregados[$key] : 0;
        $p_detalle .= ",";
        //$p_detalle.=$request->nro_stocks_almacen[$key].",";
        $p_detalle .= (isset($request->nro_stocks_almacen[$key]) && $request->nro_stocks_almacen[$key] != "") ? $request->nro_stocks_almacen[$key] : 0;
        $p_detalle .= ",";
        //$p_detalle.=$request->nro_stocks_establecimiento[$key].",";
        $p_detalle .= (isset($request->nro_stocks_establecimiento[$key]) && $request->nro_stocks_establecimiento[$key] != "") ? $request->nro_stocks_establecimiento[$key] : 0;
        $p_detalle .= ",";
        //$p_detalle.=$request->nro_stocks[$key];
        $p_detalle .= (isset($request->nro_stocks[$key]) && $request->nro_stocks[$key] != "") ? $request->nro_stocks[$key] : 0;
        $p_detalle .= ",-";
        $p_detalle .= "},";
      endforeach;
      $p_detalle = substr($p_detalle, 0, -1);
      $p_detalle .= "}";

      $p_diagnostico = "";
      $p_diagnostico .= "{";
      foreach ($request->id_diagnostico as $key => $value) :
        $p_diagnostico .= "{";
        $p_diagnostico .= $request->id_diagnostico[$key];
        $p_diagnostico .= "},";
      endforeach;
      $p_diagnostico = substr($p_diagnostico, 0, -1);
      $p_diagnostico .= "}";

      //id_diagnostico0
      //echo $request->id_farmacia;exit();
      $id_admision = (isset($request->id_admision) && $request->id_admision > 0) ? $request->id_admision : 0;
      $id_anestesiologo = (isset($request->id_anestesiologo) && $request->id_anestesiologo > 0) ? $request->id_anestesiologo : 0;
      $id_receta_vale = (isset($request->id_receta_vale) && $request->id_receta_vale > 0) ? $request->id_receta_vale : 0;
      $id_receta_vale_bus = (isset($request->id_receta_vale_bus) && $request->id_receta_vale_bus > 0) ? $request->id_receta_vale_bus : 0;

      $tipo_via = (isset($request->tipo_via) && $request->tipo_via != "") ? $request->tipo_via : "";
      $sub_via = (isset($request->sub_via) && $request->sub_via != "") ? $request->sub_via : "";
      $final_via = (isset($request->final_via) && $request->final_via != "") ? $request->final_via : "";

      $nro_guia = (isset($request->nro_guia) && $request->nro_guia != "") ? $request->nro_guia : "";
      $interconsulta = (isset($request->interconsulta) && $request->interconsulta != "") ? $request->interconsulta : "";
      $interconsulta_dias = (isset($request->dia_tto) && $request->dia_tto > 0) ? $request->dia_tto : 0;
      $id_prestacion = 0;
      $id_tipo_num = 1;
      //$estado_receta = 1;
      $estado_receta = (isset($request->estado_receta) && $request->estado_receta > 0) ? $request->estado_receta : 1;

      $nivel = $modelFarmacia->ObtenerNivelFarmacia($request->id_farmacia);
      if ($nivel->nivel == 3) {
        if ($request->interconsulta == 'SI') {
          //buscar_interconsulta
          $interconsultas_servicio = $ValidarReceta->ShowByServicioAndId_farmacia_Servicio($request->dni_beneficiario, $request->id_farmacia, $request->id_consultorio);
          $nro_interconsultas = count($interconsultas_servicio);
          if ($nro_interconsultas > 0) {
            DB::table('receta_vales')
