  public function registrar_receta_hospitalizacion_transaction(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $codigo_comparar = "";
    foreach ($request->id_producto as $key => $value) {
      $prod = Producto::where('id', $request->id_producto[$key])->first();
      $codigo_pro = $prod->codigo;
      if ($codigo_comparar == $codigo_pro) {
        Session::flash('flash_message', 'No se registro la receta, por que dispensó 2 o mas veces el producto ' . $prod->nombre);
        return redirect('/nueva_receta/' . $request->id_user . '/' . $request->id_farmacia);
      } else {
        $codigo_comparar = $codigo_pro;
      }
    }
    $modelFarmacia = new Farmacia;
    $farmacia = $modelFarmacia->GetFarmaByUser($request->id_user);
    $numero_receta = "P-" . $request->nro_receta . "-" . $request->digitos_adicionales;
    $ValidarReceta = new Receta_vale;

    //--------------------------------------------
    $existe_receta_registra = $ValidarReceta->ValidarReceta($numero_receta, $request->id_farmacia);

    if ($existe_receta_registra == 1) {
      Session::flash('flash_message', 'La Receta ' . $numero_receta . ' ya se encuentra registrada.');
      return redirect('/nueva_receta/' . $request->id_user . '/' . $request->id_farmacia);
    } else {
      //----------------------------------------------------------------------
      $id_farmacia = $request->id_farmacia;
      //------------------Registro de la Receta Vale--------------------------
      $receta_vale = new \App\Models\Receta_vale;
      $fechaServidor = $receta_vale->getFechaServidor();
      $receta_vale->id_farmacia = $request->id_farmacia;
      $receta_vale->id_user = $request->id_user;
      $receta_vale->id_consultorio = $request->id_consultorio;
      $receta_vale->nro_receta = $numero_receta;
      $receta_vale->dni_beneficiario = $request->dni_beneficiario;

      $receta_vale->cip_beneficiario = $request->cip_beneficiario;
      $receta_vale->tipodoc_beneficiario = $request->tipdoc_beneficiario;

      $receta_vale->nombre_beneficiario = $request->nombre_beneficiario;
      $receta_vale->paterno_beneficiario = $request->paterno_beneficiario;
      $receta_vale->materno_beneficiario = $request->materno_beneficiario;
      $receta_vale->tipo_beneficiario = $request->tipo_beneficiario;
      $receta_vale->dni_titular = $request->dni_titular;
      $receta_vale->tipodoc_titular = $request->tipdoc_titular;
      //$receta_vale->fecha_expedicion = $fechaServidor;//Wilian
      $receta_vale->fecha_expedicion = $request->fecha_expedicion; //Jose
      //$receta_vale->fecha_registro = $request->fecha_expedicion;//Wilian
      $receta_vale->fecha_registro = $request->fecha_atencion; //Jose
      $receta_vale->id_diagnostico = $request->id_diagnostico;
      $receta_vale->nro_historia = $request->nro_historia;
      $receta_vale->grado = $request->grado;
      $receta_vale->id_medico = $request->id_medico;
      $receta_vale->tipo_receta = $request->tipo_receta;
      $receta_vale->turno = $request->turno;
      $receta_vale->estado = 1;
      if (isset($request->id_admision) && $request->id_admision > 0)
        $receta_vale->id_admision = $request->id_admision;

      if ($request->tipo == "dni") {
        $receta_vale->nro_rua = "SMPA-" . $request->nro_rua;
      } else {
        $receta_vale->nro_rua = $request->nro_rua;
      }
      $receta_vale->obs_registro = $request->obs_registro;

      $nivel = $modelFarmacia->ObtenerNivelFarmacia($request->id_farmacia);
      if ($nivel->nivel == 3) {
        if ($request->interconsulta == 'SI') {

          //buscar_interconsulta
          $interconsultas_servicio = $ValidarReceta->ShowByServicioAndId_farmacia_Servicio($request->dni_beneficiario, $request->id_farmacia, $request->id_consultorio);

          $nro_interconsultas = count($interconsultas_servicio);
          if ($nro_interconsultas > 0) {
            DB::table('receta_vales')
              ->where('id', '=', $interconsultas_servicio->id)
              ->update(['interconsulta' => 'NO']);
          }

          if ($request->dia_tto == "") {
            $receta_vale->interconsulta_dias = 15;
            $aumentar = 16;
          } else {
            $receta_vale->interconsulta_dias = $request->dia_tto;
            $aumentar = $request->dia_tto + 1;
          }
          $receta_vale->interconsulta = $request->interconsulta;

          $fecha_actual = date("d-m-Y");
          $fecha_final_interconsulta = date("d-m-Y", strtotime($fecha_actual . "+ " . $aumentar . " days"));
          $receta_vale->fecha_final_interconsulta = $fecha_final_interconsulta;
        }
        $receta_vale->nro_guia = $request->nro_guia;
      }

      $receta_vale->save();
      $id_receta_vale = $receta_vale->id;


      //--------------Fin del Registro de la Receta Vale----------------------

      if (empty($id_receta_vale)) {
        Session::flash('flash_message', 'No se registro los datos de la receta, hubo un problema con la conexion de internet,'
          . ' capturar la pantalla y enviar la incidencia a los correos: rencisoc@saludpol.gob.pe');
      } else {

        if (isset($request->id_admision) && $request->id_admision > 0) :
          $admision = \App\Models\Admisione::where('id', $request->id_admision)->first();
          $admision->cantidad_receta = (isset($request->cantidad_receta) && $request->cantidad_receta > 0) ? $request->cantidad_receta : 1;
          $admision->save();
        endif;

        //------Declaramos modelos----------------------------------------------
        $model_farmacia = new Farmacia;
        $farma = $model_farmacia->GetFarmaByIdfarma($id_farmacia);
        $nombre_farmacia = $farma->nombre;

        foreach ($request->id_producto as $key => $value) {
          //-----Registro de la tabla producto_receta ------------------------
          $producto_receta = new Producto_receta;
          $producto_receta->id_receta_vale = $id_receta_vale;
          $producto_receta->id_producto = $request->id_producto[$key];
          $producto_receta->cantidad_prescrita = $request->nro_med_solictados[$key];
          $producto_receta->cantidad_dispensada = $request->nro_med_entregados[$key];
          $producto_receta->saldo = $request->nro_med_solictados[$key] - $request->nro_med_entregados[$key];
          $producto_receta->estado = 2;

          if ($farma->flag_receta_dias == 1) :
            $producto_receta->tiempo_periodo = $request->tiempo_periodo[$key];
          endif;
          $producto_receta->save();
          $id_producto_receta = $producto_receta->id;
          if (empty($id_producto_receta)) {
            Session::flash('flash_message', 'No se registro los productos dispensados de la receta, hubo un problema con la conexion de internet,'
              . ' capturar la pantalla y enviar la incidencia a los correos: rencisoc@saludpol.gob.pe');
          }

          $producto = Producto::where('id', $request->id_producto[$key])->first();
          $codigo_producto = $producto->codigo;
          $nombre_producto = $producto->nombre;

          $model_producto_anaquel = new \App\Models\Producto_anaquele;
          $existe_anaquel = $model_producto_anaquel->anaquelByIdProductoAndIdFarmacia($request->id_producto[$key], $id_farmacia);

          $kardex = new Kardexe;
          $kardex->codigo_producto = $codigo_producto;
          $kardex->nombre_producto = $nombre_producto;
          $kardex->tipo_movimiento = 'RC';
          $kardex->numero_movimiento = $numero_receta;
          $kardex->origen = $nombre_farmacia;
          $kardex->destino = 'BENEFICIARIO';
          $kardex->estado = 1;
          $kardex->id_tipo_movimiento = 4;
          $kardex->cantidad = $request->nro_med_entregados[$key];
          $kardex->nombre_farmacia = $nombre_farmacia;
          $kardex->fecha_movimiento = $request->fecha_expedicion;

          $kardex->id_producto = $request->id_producto[$key];
          $kardex->id_nro_movimiento = $id_receta_vale;
          $kardex->id_origen = $id_farmacia;
          //$kardex->id_destino = ; //Null Ya que no tiene destino (es externo)
          $kardex->id_farmacia = $id_farmacia;
          if ($existe_anaquel)
            $kardex->id_anaquel = $existe_anaquel->id_anaquel;
          $kardex->id_user_created = $request->id_user;
          $kardex->save();
          $idkardex = $kardex->id;
          /* -----Agregar cantidades en stock lotes --------------------------- */

          $cantidadEntregada = $request->nro_med_entregados[$key];
          $model_kardex = new Kardexe();
          $lotes = $model_kardex->GetKardexLotesByIdProductoAndIdFarmaciaAndCantidad($request->id_producto[$key], $id_farmacia, 0);
          //print_r($lotes);exit();
          foreach ($lotes as $keyLotes => $rowLotes) :

            if ($cantidadEntregada > 0) :
              if ($cantidadEntregada <= $rowLotes->cantidad) :
                // graba
                $kardex_lote = new \App\Models\Kardex_lote;
                $kardex_lote->id_kardex = $idkardex;
                $kardex_lote->lote = $rowLotes->lote;
                $kardex_lote->fecha_vencimiento = "01-" . $rowLotes->fecha_vencimiento;
                $kardex_lote->registro_sanitario = $rowLotes->registro_sanitario;
                $kardex_lote->cantidad = $cantidadEntregada;
                $kardex_lote->precio_unitario = $rowLotes->precio_unitario;
                $kardex_lote->fecha_registro = $request->fecha_expedicion;
                $kardex_lote->save();
                $cantidadEntregada = 0;
              else :
                // graba
                $kardex_lote = new \App\Models\Kardex_lote;
                $kardex_lote->id_kardex = $idkardex;
                $kardex_lote->lote = $rowLotes->lote;
