          $kardex->origen = $nombre_farmacia;
          $kardex->destino = 'BENEFICIARIO';
          $kardex->estado = 1;
          $kardex->id_tipo_movimiento = 4;
          $kardex->cantidad = $request->nro_med_entregados[$key];
          $kardex->nombre_farmacia = $nombre_farmacia;
          $kardex->fecha_movimiento = $request->fecha_expedicion;

          $kardex->id_producto = $request->id_producto[$key];
