            $kardex->id_anaquel = $existe_anaquel->id_anaquel;
          $kardex->id_user_created = $request->id_user;
          $kardex->save();
          $idkardex = $kardex->id;
          /* -----Agregar cantidades en stock lotes --------------------------- */

          $cantidadEntregada = $request->nro_med_entregados[$key];
          $model_kardex = new Kardexe();
          $lotes = $model_kardex->GetKardexLotesByIdProductoAndIdFarmaciaAndCantidad($request->id_producto[$key], $id_farmacia, 0);
