        //--------------------------------------------
        $modelMedico = new \App\Models\Medico;
        $medicos = $modelMedico->ShowMedicosByIpress($request->id_farmacia);

        $model_receta_diagnostico = new Receta_diagnostico;
        $diagnosticos_egreso = $model_receta_diagnostico->DiagnosticosByIdRecetaEgreso($id_receta_vale);

        $date = Carbon::now();
        $fecha_actual = $date->format('d-m-Y');
        $ruta = $request->ruta;

        $nivel_farmacia = $modelFarmacia->ObtenerNivelFarmacia($request->id_farmacia);
        $nivel = $nivel_farmacia->nivel;

        Session::flash('flash_message', 'Atención exitosa');
        return view('frontend.receta_vales.dispensar_productos', compact('medicamentos', 'recetas', 'fecha_actual', 'roles', 'rol_responsable', 'rol_dispensador', 'farmacia', 'consultorios', 'medicos', 'ruta', 'nivel', 'diagnosticos_egreso'));
      }
    }
  }

