          //print_r($lotes);exit();
          foreach ($lotes as $keyLotes => $rowLotes) :

            if ($cantidadEntregada > 0) :
              if ($cantidadEntregada <= $rowLotes->cantidad) :
                // graba
                $kardex_lote = new \App\Models\Kardex_lote;
                $kardex_lote->id_kardex = $idkardex;
                $kardex_lote->lote = $rowLotes->lote;
                $kardex_lote->fecha_vencimiento = "01-" . $rowLotes->fecha_vencimiento;
                $kardex_lote->registro_sanitario = $rowLotes->registro_sanitario;
                $kardex_lote->cantidad = $cantidadEntregada;
                $kardex_lote->precio_unitario = $rowLotes->precio_unitario;
                $kardex_lote->fecha_registro = $request->fecha_expedicion;
                $kardex_lote->save();
                $cantidadEntregada = 0;
              else :
                // graba
                $kardex_lote = new \App\Models\Kardex_lote;
                $kardex_lote->id_kardex = $idkardex;
                $kardex_lote->lote = $rowLotes->lote;
                $kardex_lote->fecha_vencimiento = "01-" . $rowLotes->fecha_vencimiento;
                $kardex_lote->registro_sanitario = $rowLotes->registro_sanitario;
                $kardex_lote->cantidad = $rowLotes->cantidad;
                $kardex_lote->precio_unitario = $rowLotes->precio_unitario;
                $kardex_lote->fecha_registro = $request->fecha_expedicion;
                $kardex_lote->save();
                $cantidadEntregada -= $rowLotes->cantidad;
              endif;
            endif;

          endforeach;
        }
      }
      if (empty($id_receta_vale)) {
        Session::flash('flash_message', 'No se pudo registrar la Receta, hubo un problema con la conexión de internet de su establecimiento PNP, vuelva a intentarlo nuevamente');
        return redirect('/nueva_receta/' . $request->id_user . '/' . $request->id_farmacia);
      } else {
        //----------------------------------------------------------------------
        $model_receta_vale = new Receta_vale;
        $roles = $model_receta_vale->GetRolesByIdUser($request->id_user);
        $rol_responsable = 0;
        foreach ($roles as $r) {
          if ($r->id == 3) {
            $rol_responsable = 1;
          }
        }
        $rol_dispensador = 0;
        foreach ($roles as $r) {
          if ($r->id == 5) {
            $rol_dispensador = 1;
          }
        }
        $recetas = $model_receta_vale->ShowAllById($id_receta_vale);
        //---------------------------------------------------------------------
        $model_productos_receta = new Producto_receta;
        $medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($id_receta_vale);
        //---------------------------------------------------------------------
        $modelConsultorio = new Consultorio;
        $consultorios = $modelConsultorio->ShowConsultorios($request->id_farmacia);
        //--------------------------------------------
        $modelMedico = new \App\Models\Medico;
        $medicos = $modelMedico->ShowMedicosByIpress($request->id_farmacia);

        $model_receta_diagnostico = new Receta_diagnostico;
        $diagnosticos_egreso = $model_receta_diagnostico->DiagnosticosByIdRecetaEgreso($id_receta_vale);

        $date = Carbon::now();
        $fecha_actual = $date->format('d-m-Y');
        $ruta = $request->ruta;
        Session::flash('flash_message', 'Atención exitosa');
        return view('frontend.receta_vales.dispensar_productos', compact('medicamentos', 'recetas', 'fecha_actual', 'roles', 'rol_responsable', 'rol_dispensador', 'farmacia', 'consultorios', 'medicos', 'ruta', 'diagnosticos_egreso'));
      }
    }
  }

