  public function registrar_admision_transaction(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $model_admision = new \App\Models\Admisione;
    $model_farma = new Farmacia;
    $farma = $model_farma->GetFarmaByIdfarma($request->id_farmacia);
    $id_establecimiento = $farma->id_establecimiento;
    $nro_admision = $model_admision->getNroAdmision($id_establecimiento);

    //exit($nro_admision);
    //$model_admision = new \App\Models\Admisione;
    $existe = $model_admision->ExisteAdmision($request->dni_beneficiario, $request->fecha_admision, $request->tipo_admision, $request->id_consultorio, $request->turno, $request->id_medico);
    if ($existe) {
      return redirect('/nueva_admision/' . $request->id_user . '/' . $request->id_farmacia)
        ->withInput()
        ->withErrors(array('No se ha podido registrar la Admision, Paciente ya existe en esta Fecha, Tipo de Atencion, Servicio, Turno y Medico'));
    } else {
      $obtenerId = DB::Transaction(function () use ($request, $nro_admision) {
        $admision = new \App\Models\Admisione;
        $admision->id_farmacia = $request->id_farmacia;
        $admision->id_user = $request->id_user;
        $admision->id_consultorio = $request->id_consultorio;
        $admision->nro_admision = $nro_admision;
        $admision->dni_beneficiario = $request->dni_beneficiario;
        $admision->nombre_beneficiario = $request->nombre_beneficiario;
        $admision->paterno_beneficiario = $request->paterno_beneficiario;
        $admision->materno_beneficiario = $request->materno_beneficiario;
        $admision->tipo_beneficiario = $request->tipo_beneficiario;
        $admision->fecha_nacimiento_beneficiario = $request->fecha_nacimiento_beneficiario;
        $admision->fecha_admision = $request->fecha_admision;
        $admision->tipo_admision = $request->tipo_admision;
        $admision->nro_historia = $request->nro_historia;
        $admision->turno = $request->turno;
        $admision->id_medico = $request->id_medico;
        $admision->grado = $request->grado;
        $admision->estado = 1;
        if (isset($request->id_cita) && $request->id_cita > 0)
          $admision->id_cita = $request->id_cita;
        $admision->save();
        $id_admision = $admision->id;
        return $id_admision;
      });

      if ($obtenerId == 0) {
        Session::flash('flash_message', 'No se pudo registrar la Admision, hubo un problema con la conexión de internet de su establecimiento PNP, vuelva a intentarlo nuevamente');
        return redirect('/nueva_admision/' . $request->id_user . '/' . $request->id_farmacia);
      } else {
        Session::flash('flash_message', 'Admision exitosa, El numero de Admision es ' . $nro_admision);
        return redirect('/ver_admision/' . $request->id_user . '/' . $nro_admision);
      }
    }
  }

  public function registrar_centro_quirurgico_transaction(Request $request)
