  public function actualizar_alta_hospitalizacion_transaction(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $nro_hospitalizacion = $request->nro_hospitalizado;
    $id_hospitalizacion = $request->id_hospitalizado;
    $model_cama = new \App\Models\Cama;
    $hospitalizacion = new \App\Models\Hospitalizacione;
    $model_usuario = new User;
    $model_farma = new Farmacia;
    $farma = $model_farma->GetFarmaByIdfarma($request->id_farmacia);
    //$cama_ocupada=$hospitalizacion->GetCamaById($request->id_farmacia,$id_hospitalizacion);
    $id_user_consultorio = Auth::user()->id_consultorio;
    $paciente_hospitalizado = $hospitalizacion->GetBuscaPaciente($farma->id_establecimiento, $id_hospitalizacion);

    if (count($paciente_hospitalizado) > 0) {
      $date = Carbon::now();
      $fecha_actual = $date->format('d-m-Y');
      if ($request->fecha_atencion == $fecha_actual) {
        $fecha_actual = $date->format('d-m-Y H:i:s');
        $fecha_salida = $fecha_actual;
      } else {
        $fecha_salida = $request->fecha_atencion;
      }

      $turno_salida = $request->turno;
      $condicion = $request->condicion;
      $id_medico_alta = $request->id_medico;
      $user = $model_usuario->GetById($request->id_user);
      $id_user_alta = $request->id_user;
      $nombre_registrador_alta = $user->name . ' ' . $user->paterno . ' ' . $user->materno;
      $id_diagnostico_final = $request->id_diagnostico;
      $estado = 2; //alta

      if ($id_user_consultorio != 17) {
        $id_cama_anterior = $paciente_hospitalizado->id_cama;
        if ($request->valor == 1) {
          $model_cama->actualizaEstado($id_cama_anterior, 0);
        }
      }

      DB::table('hospitalizaciones')
        ->where('id', '=', $request->id_hospitalizado)
        //->where('id_farmacia', '=', $request->id_farmacia)
        ->update([
          'fecha_salida' => $fecha_salida,
          'condicion' => $condicion,
          'turno_salida' => $turno_salida,
          'id_medico_alta' => $id_medico_alta,
          'id_diagnostico_final' => $id_diagnostico_final,
          'nombre_registrador_alta' => $nombre_registrador_alta,
          'id_user_alta' => $id_user_alta,
          'estado' => $estado,
        ]);


      Session::flash('flash_message', 'Se ha dado de alta al paciente con numero de hospitalizacion: ' . $nro_hospitalizacion);
      return redirect('/ver_paciente_alta/' . $request->id_user . '/' . $id_hospitalizacion);
    } else {
      Session::flash('flash_message', 'No se puede actualizar este registro, hubo un problema con la conexión de internet de su establecimiento PNP, vuelva a intentarlo nuevamente');
      return redirect('/ver_hospitalizacion/' . $request->id_user . '/' . $id_hospitalizacion);
    }
  }

