  public function invalidar_receta(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $id_farmacia = $request->id_farmacia;
    $nro_receta = $request->nro_receta;
    $id_user = $request->id_user;
    $id_receta = $request->id_receta;
    //----------------------------------------------------------------------
    $model_farmacia = new Farmacia;
    $model_stock_farmacia = new Stock_farmacia;
    $model_receta_devuelta = new \App\Models\Receta_devuelta;
    //----------------------------------------------------------------------        
    $farmacia = $model_farmacia->GetFarmaByIdfarma($id_farmacia);
    $nombre_farmacia = $farmacia->nombre;
    //----------------------------------------------------------------------            

    $existe_receta_devuelta = DB::table('receta_devueltas')
      ->where('id_receta_vale', $id_receta)
      ->where('id_farmacia', $id_farmacia)->first();

    if ($existe_receta_devuelta == false) {

      $devolver = new \App\Models\Receta_devuelta();
      $devolver->numero_movimiento = $nro_receta;
      //$id_receta_vales = $model_receta_devuelta->GetNroRecetaByNroRecera($nro_receta, $id_farmacia);        
      //$id_receta_vales = $model_receta_devuelta->GetNroRecetaByNroRecera($id_receta, $id_farmacia);
      $devolver->id_receta_vale = $id_receta;
      $date = Carbon::now();
      $fecha = $date->format('d-m-Y');
      $devolver->fecha_devolucion = $fecha;
      $devolver->id_farmacia = $id_farmacia;
      $devolver->id_user = $id_user;
      $devolver->motivo = $request->motivo;
      $devolver->save();
      //------Insertar Kardex-------------------------------------------------
      //$productos = $model_receta_devuelta->ProductosToDevolverVersionMejorada($id_farmacia, $nro_receta,$id_receta);
      $productos = $model_receta_devuelta->ProductosADevolverKardexAndRecetaVale($id_farmacia, $id_receta);
      /* print_r($id_receta);
        print_r($productos);
        exit(); */
      // $lotes = $model_receta_devuelta->LotesToDevolver($id_farmacia, $nro_receta,$id_receta);

      foreach ($productos as $p) {

        $model_producto_anaquel = new \App\Models\Producto_anaquele;
        $existe_anaquel = $model_producto_anaquel->anaquelByIdProductoAndIdFarmacia($p->id_producto, $id_farmacia);

        //------Insertamos el Kardexes--------------------------------------
        $insert_kardex = new Kardexe();
        $insert_kardex->codigo_producto = $p->codigo_producto;
        $insert_kardex->nombre_producto = $p->nombre_producto;
        $insert_kardex->tipo_movimiento = "DEVOLVER";
        $insert_kardex->numero_movimiento = $nro_receta;
        $insert_kardex->origen = $nombre_farmacia;
        $insert_kardex->destino = $nombre_farmacia;
        $insert_kardex->estado = 1;
        $insert_kardex->cantidad = $p->cantidad;
        $insert_kardex->nombre_farmacia = $nombre_farmacia;
        $insert_kardex->fecha_movimiento = $request->fecha_receta_origen;
        $insert_kardex->id_tipo_movimiento = 8;

        $insert_kardex->id_producto = $p->id_producto;
        $insert_kardex->id_nro_movimiento = $id_receta;
        //$insert_kardex->id_origen = $id_farmacia; -- Por que biene del benficiario
        $insert_kardex->id_destino = $id_farmacia;
        $insert_kardex->id_farmacia = $id_farmacia;
        if ($existe_anaquel)
          $insert_kardex->id_anaquel = $existe_anaquel->id_anaquel;
        $insert_kardex->id_user_created = $id_user;
        $insert_kardex->created_at = Carbon::now();
        $insert_kardex->save();

        $idkardex = $insert_kardex->id;
        $id_producto = $p->id_producto;
        //exit($id_farmacia."|".$id_receta."|".$id_producto);
        $lotes = $model_receta_devuelta->LotesADevolverKardexAndRecetaVale($id_farmacia, $id_receta, $id_producto);

        foreach ($lotes as $l) {
          $kardex_lote = new \App\Models\Kardex_lote;
          //$kardex_lote->id_stock_lote = $l->id; No se puede                
          $kardex_lote->id_kardex = $idkardex;
          $kardex_lote->lote = $l->lote;
          $kardex_lote->fecha_vencimiento = $l->fecha_vencimiento;
          $kardex_lote->registro_sanitario = $l->registro_sanitario;
          $kardex_lote->cantidad = $l->cantidad;
          $kardex_lote->precio_unitario = $l->precio_unitario;
          $kardex_lote->fecha_registro = $l->fecha_registro;
          $kardex_lote->presentacion_comercial = $l->presentacion_comercial;
          $kardex_lote->save();
        }

        $upKardex = Kardexe::where('id', '=', $p->idkardex)->first();
        $upKardex->numero_movimiento = $upKardex->numero_movimiento . "-i";
        $upKardex->id_user_update = $id_user;
        $upKardex->save();
      }

      $receta = Receta_vale::where('id', '=', $id_receta)->where('id_farmacia', '=', $id_farmacia)->first();
      $receta->estado = 0; //Receta devuelta o anulada
      $receta->save();
    }

    Session::flash('flash_message', 'Receta anulada');
    return redirect('/ver_receta/' . $id_user . '/' . $nro_receta . '/' . $id_receta);
  }

  public function invalidar_receta_digital(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $id_receta = $request->id_receta;
    $id_user = $request->id_user;
    $id_prestacion = $request->id_prestacion;
    $id_farmacia = $request->id_farmacia;
    $id_emergencia = $request->id_emergencia;
    $receta = Receta_vale::find($id_receta);
    if ($receta->estado == 1) {
      Session::flash('flash_message', 'La Receta ha sido dispensada ya no se puede anular');
    } else {
