  public function devolver_receta($id_farmacia, $nro_receta, $id_user)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $model_farmacia = new Farmacia;
    $model_stock_farmacia = new Stock_farmacia;
    $model_receta_devuelta = new \App\Models\Receta_devuelta;
    //----------------------------------------------------------------------        
    $farma = $model_farmacia->GetFarmaByIdfarma($id_farmacia);
    $nombre_farmacia = $farma->nombre;
    //----------------------------------------------------------------------            
    $devolver = new \App\Models\Receta_devuelta();
    $devolver->numero_movimiento = $nro_receta;
    $id_receta_vales = $model_receta_devuelta->GetNroRecetaByNroRecera($nro_receta, $id_farmacia);
    $devolver->id_receta_vale = $id_receta_vales->id;
    $date = Carbon::now();
    $fecha = $date->format('d-m-Y');
    $devolver->fecha_devolucion = $fecha;
    $devolver->id_farmacia = $id_farmacia;
    $devolver->id_user = $id_user;
    $devolver->save();
    //------Insertar Kardex-------------------------------------------------
    $productos = $model_receta_devuelta->ProductosToDevolver($id_farmacia, $nro_receta);
    $lotes = $model_receta_devuelta->LotesToDevolver($id_farmacia, $nro_receta);
    foreach ($productos as $p) {
      //------Insertamos el Kardexes--------------------------------------
      $insert_kardex = new Kardexe();
      $insert_kardex->codigo_producto = $p->codigo_producto;
      $insert_kardex->nombre_producto = $p->nombre_producto;
      $insert_kardex->tipo_movimiento = "DEVOLVER";
      $insert_kardex->numero_movimiento = $nro_receta;
      $insert_kardex->origen = $nombre_farmacia;
      $insert_kardex->destino = $nombre_farmacia;
      $insert_kardex->estado = 1;
      $insert_kardex->cantidad = $p->cantidad;
      $insert_kardex->nombre_farmacia = $nombre_farmacia;
      $insert_kardex->fecha_movimiento = $fecha;
      $insert_kardex->id_tipo_movimiento = 8;
      $insert_kardex->save();
      //--- Actualizamos el Stock_farmacia--------------------------------
      $stock_farmacia = $model_stock_farmacia->GetProductoById_farmaciaAndCodProduto($id_farmacia, $p->codigo_producto);
      //var_dump($stock_farmacia->cantidad); exit;
      $insert_stock_farmacia = Stock_farmacia::where('id', '=', $stock_farmacia->id)->first();
      $cantidad_stock = $stock_farmacia->cantidad;
      $insert_stock_farmacia->cantidad = $cantidad_stock + $p->cantidad;
      $insert_stock_farmacia->save();
    }
    /* ------------ Actualizar Lotes ----------------------------------------- */
    foreach ($lotes as $l) {
      $lote_actualizar = \App\Models\Stock_lote::where('id', '=', $l->id)->first();
      $cantidad = $lote_actualizar->cantidad;
      $lote_actualizar->cantidad = $cantidad + $l->cantidad;
      $lote_actualizar->save();
    }
    $receta = Receta_vale::where('nro_receta', '=', $nro_receta)->where('id_farmacia', '=', $id_farmacia)->first();
    $receta->estado = 0; //Receta devuelta o anulada
    $receta->save();
    Session::flash('flash_message', 'Receta anulada');
    return redirect('/ver_receta/' . $id_user . '/' . $nro_receta);
  }

