  public function pp_obtener_procedimiento_servicio(Request $request)
  {
    $buscar = trim($request->input('buscar'));
    $nivel = intval($request->input('nivel'));
    $genero = intval($request->input('genero'));
    $id_servicio = intval($request->input('id_servicio'));

    $columnas_nivel = [1 => 'p.t_nivel1', 2 => 'p.t_nivel2', 3 => 'p.t_nivel3'];
    if ($id_servicio <= 0 || !isset($columnas_nivel[$nivel])) {
      return response()->json([]);
    }
    $columna_nivel = $columnas_nivel[$nivel];
    $limite = $buscar == '' ? 10 : 50;

    $procedimiento = DB::select("select p.id, p.codigo, coalesce(nullif(ps.descripcion_corta, ''), p.descripcion) as descripcion
      from procedimientos p
      inner join procedimientos_servicios ps on ps.id_procedimiento = p.id
      where ps.id_servicio = ? and ps.id_establecimiento = ? and ps.id_estado_reg = 1
        and translate(lower(p.codigo || ' - ' || p.descripcion || ' ' || coalesce(ps.descripcion_corta, '')), 'áéíóúäëïöü', 'aeiouaeiou') like translate(lower(?), 'áéíóúäëïöü', 'aeiouaeiou')
        and p.convenio = 1 and p.estado = 1
        and (p.genero = ? or p.genero = 3) and coalesce(" . $columna_nivel . ", 0) > 0
      order by ps.orden asc, p.codigo asc
      limit " . $limite, [$id_servicio, Auth::user()->id_establecimiento, '%' . $buscar . '%', $genero]);

    $array = array();
    foreach ($procedimiento as $leer) {
      $array[] = array(
        "value" => $leer->codigo . " - " . $leer->descripcion,
        "label" => $leer->codigo . " - " . $leer->descripcion,
        "id" => $leer->id,
        "codigo" => $leer->codigo
      );
    }
    return response()->json($array);
  }

