  public function obtener_laboratorio_convenio($buscar, $nivel, $genero, $tipo_atencion, $id_servicio = 0, $id_perfil_preoperatorio = 0)
  {

    $model_procedimiento = new \App\Models\Laboratorio;
    if($tipo_atencion==7 && $nivel==1)
      $tipo_atencion=1;

    if ($buscar === 'all' || $buscar === '') {
        $buscar = null;
    }
    $procedimiento = $model_procedimiento->getLaboratorioRuaConvenio($buscar, $nivel, $genero, $tipo_atencion, $id_servicio, $id_perfil_preoperatorio);
    
    $array = array();
    $codigo = "";
    foreach ($procedimiento as $leer) {
      $codigo = isset($leer->cpms_personalizado ) ? $leer->cpms_personalizado  : $leer->codigo;
      $array[] = array(
        "value" => $leer->codigo . " - " . $leer->descripcion,
        "label" => $codigo . " - " . $leer->descripcion,
        "id" => $leer->id,
        "id_categoria" => $leer->id_categoria,
        "codigo_procedimiento" => $leer->codigo,
        "id_procedimiento" => $leer->id_procedimiento,
        "categoria_nombre" => $leer->categoria_nombre
      );
    }

    echo json_encode($array);
  }

  public function obtener_laboratorio_convenio_emergencia($buscar, $nivel, $genero, $tipo_atencion, $id_servicio = 0)
  {

    $model_procedimiento = new \App\Models\Laboratorio;
    $procedimiento = $model_procedimiento->getLabExamenes($buscar, $nivel, $genero, $tipo_atencion, $id_servicio);
    
    $array = array();
    foreach ($procedimiento as $leer) {
      $array[] = array(
        "value" => $leer->codigo . " - " . $leer->descripcion,
        "label" => $leer->codigo . " - " . $leer->descripcion,
        "id" => $leer->id,
        "id_categoria" => $leer->id_categoria,
        "codigo_procedimiento" => $leer->codigo,
        "id_procedimiento" => $leer->id_procedimiento
      );
    }

    echo json_encode($array);
  }

  public function obtener_producto($buscar)
  {

    $model_producto = new \App\Models\Producto;
    $producto = $model_producto->getProductoByNombre($buscar);
    $array = array();
    foreach ($producto as $leer) {
      $array[] = array(
        "value" => $leer->codigo . " - " . $leer->nombre,
        "label" => $leer->codigo . " - " . $leer->nombre,
        "id" => $leer->id,
      );
    }

    echo json_encode($array);
  }

