  public function obtenerRecetasMesActualByBeneficiario($dni_beneficiario)
  {
    $model_receta = new Receta_vale;
    $receta = $model_receta->GetRecetasMesActualByBeneficiario($dni_beneficiario);
    
    $consultorio = "";
    $m = 0;
    foreach ($receta as $key => $row) :

      if ($row->cod_atencion != $consultorio && $consultorio != "") {
        $detresumen1[$consultorio] = $m;
        $m = 1;
      } else {
        $m++;
      }

      $consultorio = $row->cod_atencion;

      if (($key + 1) == (int) count($receta)) {
        $detresumen1[$consultorio] = $m;
      }


    endforeach;

    foreach ($receta as $key => $row) :

      foreach ($detresumen1 as $keydet => $det) :
        if ($row->cod_atencion == $keydet) :
          $receta[$key]->colspan = $det;
        endif;

      endforeach;

    endforeach;

    return $receta;
  }

