  public function obtenerProductosFarmaciasByNivel($id_farmacia, $tipo_receta, $id_consultorio)
  {
    $modelFarmacia = new Farmacia();
    $model_producto = new Producto;
    $nivel = $modelFarmacia->ObtenerNivelFarmacia($id_farmacia);
    if ($tipo_receta == "AMBULATORIO" || $tipo_receta == "HOSPITALIZACION" || $tipo_receta == "EMERGENCIA") :
      $producto = $model_producto->getProductosByNivelAndIdServicio($nivel->nivel, $id_consultorio);
    else :
      $producto = $model_producto->ProductosFarmaciasSegunNivel($nivel->nivel);
    endif;
    return $producto;
  }

  public function formulario_cita(Request $request)
  {
    if (!Auth::check()) :
        return redirect('/auth/login');
    else:
      if(Auth::user()->actualizo_passw==0):
        return redirect('auth/password/change');
      endif;
    endif;

    $model_kardex = new Kardexe();
    $model_usuario = new User;

    $fechaServidor = $model_kardex->getFechaServidor();
    $user = $model_usuario->GetById(Auth::user()->id);
    $flagemergenciareferencia = $user->flagemergenciareferencia;
    $establecimientoactual = Auth::user()->id_establecimiento;
      //***jhonmatos */
      $date = new Carbon();
      $anio = $date->format('Y');
    $servicio = "SELECT distinct (sc.id_consultorio ) as id,
                    c.nombre
                    from sub_consultorios sc
                    inner join consultorios c on c.id = sc.id_consultorio
                    where sc.id_establecimiento  = '$establecimientoactual'";
    $servicio = DB::select($servicio);

    $estableciemientoreferencia = "SELECT  
                                  *,
                                  concat(nombre,' - ',red_region,' - ',codigo )  as concatenado
                                  from establecimientos e where id <> '$establecimientoactual'";
                                  $estableciemientoreferencia = DB::select($estableciemientoreferencia);

    $establecimiento = Establecimiento::where('id', $establecimientoactual)->first();
    $flag_api_sp = DB::table('config_options')->where('id', 5)->value('api_sp_activated'); // si es true debería utilizarse el API de SALUDPOL , caso contrario, la ws de SALUDPOL
    return view('frontend.citas.form_cita', compact('fechaServidor','servicio','anio','flagemergenciareferencia','estableciemientoreferencia', 'establecimiento','flag_api_sp'));
  }

