  public function consultarExistenciaContraReferenciaPendiente($id_servicio, $dni_beneficiario)
  {
    $model_asegurado = new Asegurado();
    $model_referencia = new Referencia();
    $model_prestacionreferncia = new \App\Models\Prestaciones;
    $diagnostico_prestacion_referencia = null;
    $procedimientos_refencia = null;
    $asegurado = $model_asegurado->busca_asegurado_por_dni($dni_beneficiario);
    $ultimaReferenciaParaContraReferir = Referencia::where('referencias.id_asegurado', $asegurado[0]->id)
    ->where('estado_proceso', 5)
    ->leftJoin('establecimientos', 'referencias.id_establecimiento', '=', 'establecimientos.id')
    ->leftJoin('prestaciones as p', 'p.id', '=', 'referencias.id_prestacion')
    ->leftJoin('sub_consultorios as sc', 'p.id_sub_consultorio', '=', 'sc.id')
    ->leftJoin('consultorios as c', 'sc.id_consultorio', '=', 'c.id')
    ->orderBy('id', 'desc')
    ->select('referencias.*', 'c.nombre as nombre_servicio', 'establecimientos.nombre as nombre_establecimiento')
    ->first();
    $id_servicio_contraReferencia = null;
    $existeContraReferenciaPendiente = isset($ultimaReferenciaParaContraReferir);
    if ($existeContraReferenciaPendiente) {
      $id_servicio_contraReferencia = $ultimaReferenciaParaContraReferir->id_servicio;
      $diagnostico_prestacion_referencia = $model_prestacionreferncia->GetDiagnosticoByIdPrestacion($ultimaReferenciaParaContraReferir->id_prestacion);
      $procedimientos_refencia = $model_referencia->buscar_procedimiento_referencia($ultimaReferenciaParaContraReferir->id);
    }
    $response = [
      'existeContraReferenciaPendiente' => $existeContraReferenciaPendiente,
      'referencia' => $ultimaReferenciaParaContraReferir,
      'id_servicio_contraReferencia' => $existeContraReferenciaPendiente ? $id_servicio_contraReferencia : null,
      'servicios_ipress_origen' => $existeContraReferenciaPendiente ? $model_referencia->busca_servicio_por_ipres_origen_referencia($ultimaReferenciaParaContraReferir->id_establecimiento) : null,
      'id_establecimiento_destino_referencia' => $existeContraReferenciaPendiente ? $ultimaReferenciaParaContraReferir->id_establecimiento_des : null,
      'id_establecimiento_origen_referencia' => $existeContraReferenciaPendiente ? $ultimaReferenciaParaContraReferir->id_establecimiento : null,
      'nombre_establecimiento' => $existeContraReferenciaPendiente ? $ultimaReferenciaParaContraReferir->nombre_establecimiento : null,
      'diagnostico_prestacion_referencia' => $existeContraReferenciaPendiente ? $diagnostico_prestacion_referencia : null,
      'procedimientos_refencia' => $existeContraReferenciaPendiente ? $procedimientos_refencia : null
    ];
    return response()->json($response);
  }

