    //   case 13: case 16: case 68: case 43: case 77: case 119: case 126: case 136:
    //     $is_especialidad_quirurgica = "SI"; break;
    // endswitch;
    $esQuirurgico = DB::table('consultorios')
    ->where('flag_quirurgico', 1)
    ->where('id', $cita->id_servicio)
    ->exists();
    if($esQuirurgico){
      $is_especialidad_quirurgica = "SI";
    }

    $codigo = null; $codigo_siteds = null;
    $fecha_atencion = date('d-m-Y', strtotime($cita->fecha_hora));
    $codigo = $model_cita->busca_Siteds_Atencion($cita->nro_doc_ident,$fecha_atencion);
    if(!empty($codigo))
      $codigo_siteds = $codigo->codigo_siteds;
     // Verificar si el usuario es medico de profesion
     $model_medico = new Medico();
     $medico = $model_medico->GetDatosMedicoByDniAndEstablecimiento(Auth::user()->dni,Auth::user()->id_establecimiento );
     $is_profesion_medico = false;
     if (count($medico) > 0) {
       switch ($medico->id_profesion) {
         case 20: case 4: case 51: case 52: case 1: $is_profesion_medico = true; break;
       }
       if (!$is_profesion_medico && (intval($nivel) == 1 || intval($nivel) == 2) && in_array(intval($medico->id_profesion), [12, 2, 5])) {
          $is_profesion_medico = true;
       }
     }
     else{
     	return redirect('/auth/login');
     }

    $procedimientos = [];
    $diagnosticos = [];
    $cqxIntervencion = null;
    if (isset($data_cq_cita) && !empty($data_cq_cita) && isset($data_cq_cita->id_cqx_intervenciones)) {
      $cqxIntervencion = CqxIntervencion::find($data_cq_cita->id_cqx_intervenciones);
      if (isset($cqxIntervencion) && !empty($cqxIntervencion) && isset($cqxIntervencion->id_prestacion)) {
        $diagnosticos = $model_prestacion->GetDiagnosticoByIdPrestacion($cqxIntervencion->id_prestacion);
        if (intval($cqxIntervencion->id_prestacion) > 1910698) {
          $procedimientos = $model_prestacion->GetProcedimientosByIdPrestacionydiag($cqxIntervencion->id_prestacion, 1);
        } else {
          $procedimientos = $model_prestacion->GetProcedimientosByIdPrestacion($cqxIntervencion->id_prestacion, 1);
        }

        $cqxProcedimientos = DB::table('cqx_procedimientos as cp')
                              ->join('procedimientos as p', 'cp.id_procedimiento', '=', 'p.id')
                              ->where('cp.id_cqx_intervenciones', $cqxIntervencion->id)
                              ->select('cp.id as cod','p.codigo as codigo','p.descripcion as nombre',DB::raw("'' as cantidad"),DB::raw("'' as id_diagnostico"),'p.id as id_procedimiento')
                              ->get();
        if (isset($cqxProcedimientos) && count($cqxProcedimientos) > 0) {
          $procedimientos = array_merge($cqxProcedimientos, $procedimientos);
        }
      }
    }
    return view('frontend.atenciones.form_atencion', compact(
