  private function formulario_atencion_escalas() 
  {
    $aPuntaleLetras = ['', 'A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I'];
    $model_reseta_vale = new \App\Models\Receta_vale();
    $escala = $model_reseta_vale->GetEscalas();
    $escala_opciones = $model_reseta_vale->GetEscalaOpciones();
    $aEscala = [];
    foreach ($escala as $item) {
      $aEscala[$item->id]['nombre'] = $item->nombre;
      $aEscala[$item->id]['tipo'] = $item->tipo;
    }
    foreach ($escala_opciones as $item) {
      if ($item->id_parent == 0) {
        $aEscala[$item->id_escala]['item'][$item->id]['nombre'] = $item->nombre;
      } else {
        $puntaje = null;
        if ($aEscala[$item->id_escala]['tipo'] == 3) {
          $puntaje = isset($aPuntaleLetras[$item->puntaje]) ? $aPuntaleLetras[$item->puntaje] : '--';
        } else {
          $puntaje = $item->puntaje;
        }
        $aEscala[$item->id_escala]['item'][$item->id_parent]['item'][] = [
          'nombre' => $item->nombre,
          'puntaje' => $puntaje
        ];
      }
    }
    return $aEscala;
  }

  public function formulario_atencion_escala_resultado(Request $request) 
  {
    $aData = [];

    $aId = empty($request->id) ? [] : $request->id;
    $aValue = empty($request->value) ? [] : $request->value;

    foreach($aId as $key => $value) {
      $aData[$value] = isset($aValue[$key]) ? (is_numeric($aValue[$key]) ? intval($aValue[$key]) : $aValue[$key]) : 0;
    }

    $aResultado = [];
    $model_reseta_vale = new \App\Models\Receta_vale();
    $escala_resultados =  $model_reseta_vale->GetEscalaResultados();
    foreach ($escala_resultados as $item) {
      if (isset($aData[$item->id_escala])) {
        $dataValue = (int)$aData[$item->id_escala];
        if ($item->minimo == $item->maximo && $item->maximo == -1) {
          $aResultado[$item->id_escala] = [
            'escala' => $item->nombre,
            'puntaje' => 'Total ' . $aData[$item->id_escala]
          ];  
        } else if ($item->minimo == -1) {
          if ($item->maximo == $dataValue ) {
            $aResultado[$item->id_escala] = [
              'escala' => $item->nombre,
              'puntaje' => 'Total ' . $dataValue . ' - ' . $item->resultado
            ];  
          } else if (!isset($aResultado[$item->id_escala])) {
            $aResultado[$item->id_escala] = [
              'escala' => $item->nombre,
              'puntaje' => 'Total ' . $dataValue
            ];
          }
        } else {
          if ($dataValue >= $item->minimo && $dataValue <= $item->maximo) {
            $aResultado[$item->id_escala] = [
              'escala' => $item->nombre,
              'puntaje' => 'Total ' . $dataValue . ' - ' . $item->resultado
            ];
          }
        }
      }
    }
    
    echo json_encode($aResultado);
  }

