  private function ppQuitarConsultoriosProcedimiento($aConsultorios)
  {
    if (count($aConsultorios) == 0 || !\Schema::hasColumn('sub_consultorios', 'flag_procedimiento')) return $aConsultorios;
    $ids = array_map(function ($c) { return intval($c->id); }, $aConsultorios);
    $ids_proc = DB::table('sub_consultorios')->whereIn('id', $ids)->where('flag_procedimiento', 1)->lists('id');
    if (count($ids_proc) == 0) return $aConsultorios;
    return array_values(array_filter($aConsultorios, function ($c) use ($ids_proc) {
      return !in_array(intval($c->id), array_map('intval', $ids_proc));
    }));
  }

