  public function listar_ordenes_procedimientos_pendientes($dni_beneficiario)
  {
    $sql = "select s.id as nro_orden, to_char(s.fecha_solicitud, 'DD-MM-YYYY') as fecha_orden,
        ta.nombre as tipo_atencion, c.nombre as servicio_solicitante, c.id as id_servicio_solicitante,
        trim(coalesce(m.paterno,'') || ' ' || coalesce(m.materno,'') || ', ' || coalesce(m.nombre,'')) as personal_salud,
        pr.codigo, pr.descripcion, d.id_procedimiento, d.requiere_cita,
        min(case when d.estado = 1 then d.id end) as id_detalle,
        count(d.id) as cantidad,
        sum(case when d.estado = 1 then 1 else 0 end) as pendientes,
        (select to_char(cr.fecha_hora, 'DD-MM-YYYY HH:MI AM') from solicitud_procedimientos_detalle dr
           inner join citas cr on cr.id = dr.id_cita_reevaluacion and cr.id_estado_reg = 1
          where dr.id_solicitud = s.id and dr.id_procedimiento = d.id_procedimiento
          order by cr.id desc limit 1) as fecha_cita_reevaluacion,
        (select string_agg(ps.id_servicio::text, ',') from procedimientos_servicios ps
          where ps.id_procedimiento = d.id_procedimiento and ps.id_establecimiento = p.id_establecimiento and ps.id_estado_reg = 1) as ids_servicio_procedimiento
      from solicitud_programacion_procedimientos s
      inner join solicitud_procedimientos_detalle d on d.id_solicitud = s.id
      inner join procedimientos pr on pr.id = d.id_procedimiento
      inner join prestaciones p on p.id = s.id_prestacion
      left join tipo_atenciones ta on ta.id = s.id_tipo_atencion
      left join sub_consultorios sc on sc.id = p.id_sub_consultorio
      left join consultorios c on c.id = sc.id_consultorio
      left join medicos m on m.id = p.id_medico
      where s.asegurado_dni = ? and s.tiene_pendientes = true and p.id_establecimiento = ?
        and d.requiere_cita in (1, 2) -- requiere_cita = 0: se atiende sin cita, no se lista para citar
        and p.flag in (1, 2)
        and coalesce(s.flag, 0) > 0 and coalesce(s.ruta_firma, '') not in ('', 'NULL') -- solo órdenes firmadas
      group by s.id, s.fecha_solicitud, ta.nombre, c.nombre, c.id, m.paterno, m.materno, m.nombre,
               pr.codigo, pr.descripcion, d.id_procedimiento, d.requiere_cita, p.id_establecimiento
      having sum(case when d.estado = 1 then 1 else 0 end) > 0
      order by s.fecha_solicitud desc, s.id desc";
    $data = DB::select($sql, [trim($dni_beneficiario), Auth::user()->id_establecimiento]);
    return response()->json($data);
  }

  public function pp_servicios_procedimiento()
  {
    if (!\Schema::hasColumn('sub_consultorios', 'flag_procedimiento')) {
      return response()->json([]);
    }
    $ids = DB::table('sub_consultorios')
      ->where('id_establecimiento', Auth::user()->id_establecimiento)
      ->where('flag_procedimiento', 1)
      ->where('id_estado_reg', 1)
      ->distinct()
      ->lists('id_consultorio');
    return response()->json(array_values(array_map('intval', $ids)));
  }

  private function ppTieneCitaReevaluacion($id_solicitud, $id_procedimiento)
  {
    return DB::table('solicitud_procedimientos_detalle as d')
      ->join('citas as c', 'c.id', '=', 'd.id_cita_reevaluacion')
      ->where('d.id_solicitud', $id_solicitud)
      ->where('d.id_procedimiento', $id_procedimiento)
      ->where('c.id_estado_reg', 1)
      ->exists();
  }

  public function pp_eliminar_procedimiento_solicitud(Request $request)
  {
    if (!Auth::check()) {
      return response()->json(['success' => false, 'message' => 'Sesión expirada.']);
    }
    $id_solicitud = intval($request->id_solicitud);
    $id_procedimiento = intval($request->id_procedimiento);

    $detalles = DB::table('solicitud_procedimientos_detalle')
      ->where('id_solicitud', $id_solicitud)
      ->where('id_procedimiento', $id_procedimiento)
      ->where('estado', '<>', 0)
      ->get();
    if (count($detalles) == 0) {
      return response()->json(['success' => false, 'message' => 'El procedimiento no existe o ya fue eliminado.']);
    }
    foreach ($detalles as $d) {
      if (in_array(intval($d->estado), array(3, 6))) {
        return response()->json(['success' => false, 'message' => 'El procedimiento programado ya fue atendido; no se puede eliminar.']);
      }
      if (in_array(intval($d->estado), array(4, 5))) {
        return response()->json(['success' => false, 'message' => 'El procedimiento programado fue observado o anulado; no se puede eliminar.']);
      }
    }
    foreach ($detalles as $d) {
      if (intval($d->estado) === 2) {
        return response()->json(['success' => false, 'message' => 'El procedimiento ya cuenta con cita. Primero debe anularse la cita del procedimiento.']);
      }
    }
    if ($this->ppTieneCitaReevaluacion($id_solicitud, $id_procedimiento)) {
      return response()->json(['success' => false, 'message' => 'El procedimiento cuenta con cita de reevaluación. Primero debe anularse esa cita.']);
    }

    DB::beginTransaction();
    try {
      DB::table('solicitud_procedimientos_detalle')
        ->where('id_solicitud', $id_solicitud)
        ->where('id_procedimiento', $id_procedimiento)
        ->where('estado', 1)
        ->update(['estado' => 0, 'updated_at' => Carbon::now(), 'updated_us' => Auth::id()]);

      $quedan = DB::table('solicitud_procedimientos_detalle')->where('id_solicitud', $id_solicitud)->whereIn('estado', [1, 2])->count();
      DB::table('solicitud_programacion_procedimientos')->where('id', $id_solicitud)->update(['tiene_pendientes' => $quedan > 0]);
      $activos = DB::table('solicitud_procedimientos_detalle')->where('id_solicitud', $id_solicitud)->where('estado', '<>', 0)->count();
      if ($activos == 0) {
        DB::table('solicitud_programacion_procedimientos')->where('id', $id_solicitud)->update([
          'id_estado_reg' => 0,
          'fecha_anulacion' => Carbon::now(),
          'anulado_us' => Auth::id(),
          'updated_at' => Carbon::now(),
          'updated_us' => Auth::id(),
        ]);
      }
      DB::commit();
      return response()->json(['success' => true, 'message' => 'Procedimiento eliminado correctamente.']);
    } catch (\Exception $e) {
      DB::rollBack();
      Log::error('pp_eliminar_procedimiento_solicitud: ' . $e->getMessage());
      return response()->json(['success' => false, 'message' => 'No se pudo eliminar el procedimiento.']);
    }
  }

