    $dFecha = mktime(0, 0, 0, $aFechaAtencion[1], $aFechaAtencion[2], $aFechaAtencion[0]);
    $result = $model_cita->GetCitasMedicasDelMes($documento, $aFechaAtencion[0], $aFechaAtencion[1]);

    $aFeriado = null;
    foreach($feriados as $key => $value) {
      $aFeriado[$value->feriado] = 1;
    }
    unset($feriados);

    // Valida el máximo de citas del mes
    $result = $model_cita->ExisteCitaAllIpress($documento, $fecha_atencion, $id_ipress, $id_consultorio);
    // Valida el intervalo de dias entre citas
    $aDetalleFCalculo = $this->CalculoLimiteFechaCita($id_ipress, $fecha_atencion, $aFeriado);
    if ($aDetalleFCalculo['es_domingo']) {
      $status = 2; // La fecha de reserva es Domingo
    } else {
      if ($aDetalleFCalculo['es_feriado']) {
        $status = 2; // Fecha de reserva no permitido en Domingo o feriado
      }
    }

    if ($result) {
      $status = 7;
      //$status = 4;
      //return view('frontend.citas.modal_cita_horario_lista', compact('status', 'fecha_atencion'));
    } else {
      $result = $model_cita->ValidarCitasEnRango($documento, $id_ipress, $id_consultorio, $aDetalleFCalculo['fecha_inferior'], $aDetalleFCalculo['fecha_superior']);
      if (!empty($result)) {
        $status = 5;
        $aDetalle['intervalo_cita'] = $aDetalleFCalculo['intervalo_cita'];
        $aDetalle['paciente'] = $result->paciente;
        $aDetalle['servicio'] = $result->servicio;
        $aDetalle['medico'] = $result->medico;
        $aDetalle['fecha'] = Util::GetFechaTexto($result->fecha_hora);
        return view('frontend.citas.modal_cita_horario_lista', compact('status', 'fecha_atencion', 'aDetalle'));
      }
    }

    $medico_turno = new \App\Models\Medico_turno;
    $model_consultorio = new Consultorio;
    $consultorio = $model_consultorio->GetNombreById($id_consultorio);
    $turno = $medico_turno->GetTurnos();
     
    ///ubicamos el id del consultorio CAR
    $id_sub_consultorios = SubConsultorio::where('abreviatura','=','CAR')->
                            where('id_establecimiento','=',$id_ipress)->
                            where('id_consultorio','=',$id_consultorio)->first(); 
    //dd($aConsultorios[0]->id);
    $aConsultorios = $medico_turno->GetSubConsultorioByIdConsultorioCAR($id_consultorio, $id_ipress,$id_sub_consultorios->id);
    //dd($aConsultorios[0]->id);

    $aHorarios = null;
    $aHorariosConfig = null;
    $oMedicoTurno = new \App\Models\Medico_turno; 
    $resultTurnos = $medico_turno->GetSubConsultorioTurnoByIdConsultorioCAR($aConsultorios[0]->id,Auth::user()->id_establecimiento, 0);
    //dd($resultTurnos);

      $iHorario = 1;
      
      for($it = 0; $it < count($resultTurnos); $it++) {
        $horarios = $medico_turno->GetHorarioConsultorioByIdConsultorioTurnoCAR(
          0, 
          $resultTurnos[$it]->id_sub_consultorio_turno,
          $fecha_atencion, 
          $resultTurnos[$it]->tiempo_atencion, 
          $resultTurnos[$it]->hora_ini, 
          $resultTurnos[$it]->hora_fin
        );    
        
        //dd($horarios);

        if($horarios==null){
          $aHorarios = null; 
        }else{
          
          foreach($horarios as $horario) {  
                //dd($horario);
                $aCadMedicoCita = explode("#", $horario->id_medico);
                $event_click = '';
                $value_color = '';
                
                if ($aCadMedicoCita[1] == 0) {
                  $value_color = 'color:#000000;cursor:pointer';
                  $event_click = 'guardarCita(' . $aConsultorios[0]->id . ',\'' . $horario->fecha_cita . '\',' . $resultTurnos[$it]->id_turno . ')';
      
                  
                  $aHorarios['medico']['medico'] = $horario->nombre . ' ' . $horario->paterno . ' ' . $horario->materno;  
                  $aHorarios['horario'][] = [
                  
                    'hora' => $horario->fecha_hora . ' - ' . $horario->fecha_fin,
                    'click' => $event_click,
                    'color' => $value_color, 
                    
                  ];
                } 
            $iHorario++;
          }   
         
          /*
          dd($aHorarios);
          if($aHorarios['medico']==null){
            $aHorarios = null; 
          }else{
            $aHorarios['medico']=$aHorarios['medico'];
            $aHorarios['horario']=$aHorarios['horario'][0];
          }
          */
        
          if($aHorarios['medico']==null){
            $aHorarios = null; 
          } 

        }      
      } 
    if ($status == 0 && empty($aHorarios)) {
        $status = 1; // No se tiene programado médicos en el horario
    }  
    if($aHorarios==null){
      return json_encode(null);
    }else{ 
      return ($aHorarios);
    }
  }

