  public function modal_cita_horario_cuadro($id_ipress, $id_consultorio, $fecha_atencion)
  {
    $medico_turno = new \App\Models\Medico_turno;
    $model_consultorio = new Consultorio;
    $consultorio = $model_consultorio->GetNombreById($id_consultorio);
    $turno = $medico_turno->GetTurnos();
    $medicos = $medico_turno->GetSubConsultorioByIdConsultorio($id_consultorio, $id_ipress,$fecha_atencion);
    $aConsultorios = $medico_turno->GetSubConsultorioByIdConsultorio($id_consultorio, $id_ipress,$fecha_atencion);

    //$medicos = $medico_turno->GetSubConsultorioByIdConsultorio($id_consultorio, $id_ipress);
    //$aConsultorios = $medico_turno->GetSubConsultorioByIdConsultorio($id_consultorio, $id_ipress);
    $aHorarios = null;
    $aHorariosConfig = null;
    $oMedicoTurno = new \App\Models\Medico_turno;
    for($ic = 0; $ic < count($aConsultorios); $ic++) {
      $aHorarios[0][$ic]['value'] = $aConsultorios[$ic]->nombre;
//    $resultTurnos = $medico_turno->GetSubConsultorioTurnoByIdConsultorio($aConsultorios[$ic]->id);
//$resultTurnos = $medico_turno->GetSubConsultorioTurnoByIdConsultorio2($aConsultorios[$ic]->id,"",Auth::user()->id_establecimiento);
$resultTurnos = $medico_turno->GetSubConsultorioTurnoByIdConsultorio2($aConsultorios[$ic]->id_consultorio, $aConsultorios[$ic]->id,"",Auth::user()->id_establecimiento);
$iHorario = 1;
      for($it = 0; $it < count($resultTurnos); $it++) {
        $horarios = $medico_turno->GetHorarioConsultorioByIdConsultorioTurno(
          $id_ipress, 
          $resultTurnos[$it]->id_sub_consultorio_turno, 
          $fecha_atencion, 
          $resultTurnos[$it]->tiempo_atencion, 
          $resultTurnos[$it]->hora_ini, 
          $resultTurnos[$it]->hora_fin
        );
        foreach($horarios as $horario) {
          $aCadMedicoCita = explode("#", $horario->id_medico); 
          //$aHorarios[$iHorario][$ic]['x'] = $horario;
          if ($aCadMedicoCita[1] == 0) {
            $aHorarios[$iHorario][$ic]['color'] = 'color:#000000;cursor:pointer';
            $aHorarios[$iHorario][$ic]['click'] = 'guardarCita(' . $aConsultorios[$ic]->id . ',\'' . $horario->fecha_cita . '\',' . $resultTurnos[$it]->id_turno . ')'; 
          } else if ($aCadMedicoCita[1] >= 1) {
            $aHorarios[$iHorario][$ic]['color'] = 'background:#fff3cd;color:#000000;';            
          }
          $aHorarios[$iHorario][$ic]['medico'] = '<strong>Medico:</strong><br>' . $horario->nombre . ' ' . $horario->paterno . ' ' . $horario->materno . '<br><br><strong>';
          $aHorarios[$iHorario][$ic]['value'] = 'Horario:</strong><br>' . $horario->fecha_hora . '<br>' . $horario->fecha_fin;
          $iHorario++;
        }        
      }
    }
    return view('frontend.citas.modal_cita_horario_lista', 
      compact('medicos', 'fecha_atencion', 'id_ipress', 'id_consultorio', 'turno', 'consultorio', 'aHorarios')
    );
  }

