  public function cronograma_cita($id_ipress, $id_consultorio)
  {

    $medico_turno = new \App\Models\Medico_turno;
    $model_consultorio = new Consultorio;
    //$id_ipress="75";
    //$id_consultorio="105";
    $consultorio = $model_consultorio->GetNombreById($id_consultorio);
    $cronograma = $medico_turno->GetCalendarioByIdIpressAndIdConsultorio($id_ipress, $id_consultorio, "", $consultorio->dura_cons);

    $data = array();
    foreach ($cronograma as $key => $row) :
      $datos = array();
      $datos["end"] = $row->end;
      $datos["start"] = $row->start;
      $datos["nro_citas"] = $row->nro_citas;
      $datos["nro_programado"] = $row->nro_programado;
      $disponible = $row->nro_programado - $row->nro_citas;
      //$datos["title"] = $disponible." Disponbiles \n ".$row->nro_citas." Programado";
      $datos["title"] = $disponible . " Disponbile";
      $datos["color"] = "#d4edda";
      $data[$key] = $datos;
    endforeach;

    foreach ($cronograma as $row) :
      $key++;
      $datos["end"] = $row->end;
      $datos["start"] = $row->start;
      $datos["nro_citas"] = $row->nro_citas;
      $datos["nro_programado"] = $row->nro_programado;
      $disponible = $row->nro_programado - $row->nro_citas;
      $datos["title"] = $row->nro_citas . " Programado";
      $datos["color"] = "#fff3cd";
      $data[$key] = $datos;
    endforeach;

    echo json_encode($data);
    //return view('frontend.citas.modal_cita_medico',compact('medicos','horario','fecha_atencion','id_ipress','id_consultorio'));

  }

  public function registrar_cita_transaction(Request $request)
  {
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;
    $esAfiliado = (int)$request->es_afiliado;
    $id_cita = 0;

    if ($request->cita_pp == 1) {
      $pp_validar = SolicitudProgramacionProcDetalles::where("id", $request->id_solicitud_procedimiento_detalle)->first();
      if ($pp_validar && intval($pp_validar->requiere_cita) === 2
        && !$this->ppTieneCitaReevaluacion($pp_validar->id_solicitud, $pp_validar->id_procedimiento)) {
        Log::info("Cita PP bloqueada: falta cita de reevaluación (detalle " . $pp_validar->id . ")");
        echo $id_cita;
        return;
      }
    }

    Log::info("Info Registro Cita" . 
      "\n\ndatos del request: " . json_encode($request->all())
    );
    try {
      DB::transaction(function () use (&$id_cita,$request){

        $id_turno = 0;
        if (!empty($request->id_turno)) {
          $id_turno = $request->id_turno;
        }

        $model_cita = new \App\Models\Cita;

        if($request->establecimiento_referencia != ""){
          
          $establecimientoref = "SELECT *, e.nombre as nombre_establecimiento from establecimientos e where id = '$request->establecimiento_referencia'";
          $establecimientoref = DB::select($establecimientoref);
          $establecimientoref = $establecimientoref[0];
          Log::info("Cita: " . $establecimientoref->nombre_establecimiento);
        }else{
          $establecimientoref = "SELECT *, e.nombre as nombre_establecimiento from establecimientos e where id = '76'";
          $establecimientoref = DB::select($establecimientoref);
          $establecimientoref = $establecimientoref[0];
          $establecimientoref->nombre_establecimiento = 0;
          Log::info("Cita: " . $establecimientoref->nombre_establecimiento);
        }

        if($request->referido == "NO"){
          $request->servicio_referencia   = $request->consultorio_referencia;
        }
        $tipodoc_beneficiario = !empty($request->tipodoc_beneficiario)?$request->tipodoc_beneficiario:(!empty($request->tipodoc_beneficiario_bus)?$request->tipodoc_beneficiario_bus:null);// Se agrego tipodoc_beneficiario_bus cuando viene de QX cita
        $nrodocafiliado = !empty($request->nrodocafiliado)?$request->nrodocafiliado:(!empty($request->dni_beneficiario)?$request->dni_beneficiario:null);//se agrego dni_beneficiario cuando viene QX cita

        //$id_cita = $model_cita->registrarCita($id_cita, $request->id_establecimiento, $request->id_consultorio/*id_servicio*/, /*$id_medico*/ NULL, $request->id_user, $request->fecha_cita, $tipodoc_beneficiario, $nrodocafiliado, $request->nombre_beneficiario, $request->paterno_beneficiario, $request->materno_beneficiario, $request->tipo_beneficiario, $request->nro_historia, $request->grado, $request->fecnacafiliado, $request->nomsexo, $request->cip_beneficiario, $request->tipodoc_titular, $request->nrodoctitular, $request->nombre_titular, $request->paterno_titular, $request->materno_titular, NULL, 1, 1, $request->correo, $request->domicilio, $request->telefono,$request->telefono2, $request->tipo_cita,1,$request->referido,$request->adicional
        //,$establecimientoref->nombre_establecimiento,$request->servicio_referencia,$request->tipo_doc,$request->numero_doc,$request->ano,$request->origen_doc,$request->codigo_renipres,$request->obs_registro_cita,'');
