        $cita_nueva = DB::table('citas as c')
          ->join('asegurados as a', 'a.id', '=', 'c.id_asegurado')
          ->join('sub_consultorios as scn', 'scn.id', '=', 'c.id_sub_consultorio')
          ->where('c.id', $id_cita)
          ->select('a.nro_doc_ident', 'c.id_establecimiento', 'scn.id_consultorio')
          ->first();
        if ($cita_nueva) {
          $pendientes_reeval = DB::select("select d.id
              from solicitud_procedimientos_detalle d
              inner join solicitud_programacion_procedimientos s on s.id = d.id_solicitud
              inner join prestaciones p on p.id = s.id_prestacion
              inner join sub_consultorios sc on sc.id = p.id_sub_consultorio
            where s.asegurado_dni = ? and p.id_establecimiento = ? and sc.id_consultorio = ?
              and d.requiere_cita = 2 and d.estado = 1
              and not exists (select 1 from solicitud_procedimientos_detalle dr
                                inner join citas cr on cr.id = dr.id_cita_reevaluacion and cr.id_estado_reg = 1
                               where dr.id_solicitud = d.id_solicitud and dr.id_procedimiento = d.id_procedimiento)",
            [$cita_nueva->nro_doc_ident, $cita_nueva->id_establecimiento, $cita_nueva->id_consultorio]);
          $ids_reeval = array_map(function ($r) { return $r->id; }, $pendientes_reeval);
