          } else {
            $aseguradoTitular = Asegurado::where("nro_doc_ident", $request->nrodoctitular)->first();
            if($aseguradoTitular){
              $asegurado->id_asegurado_titular = $aseguradoTitular->id;
            }
          }
        }
        $asegurado->save();
      }

    } catch (\Exception $e) {
      Log::error('Ocurrió una excepción: ' . $e->getMessage());
      $id_cita = 0;
    }
    echo $id_cita;
  }

  public function registrar_cita_transaction_v2(Request $request)
