      $pp_validar = SolicitudProgramacionProcDetalles::where("id", $request->id_solicitud_procedimiento_detalle)->with("procedimiento")->first();
      if ($pp_validar && intval($pp_validar->procedimiento->requiere_cita) === 2
        && !$this->ppTieneCitaReevaluacion($pp_validar->id_solicitud, $pp_validar->id_procedimiento)) {
        Log::info("Cita PP bloqueada: falta cita de reevaluación (detalle " . $pp_validar->id . ")");
        echo $id_cita;
        return;
      }
