  public function modal_historial_informes_pp($id_asegurado){
    $prestaciones = Prestaciones::select('prestaciones.id as prestacion_id', 'consultorios.nombre as servicio_nombre', 'id_tipo_atencion', 'prestaciones.updated_at',
    'establecimientos.nombre as establecimiento_nombre', DB::raw("CONCAT(medicos.paterno || ' ' || medicos.materno || ', ' || medicos.nombre) as medico_nombres"), 'sub_consultorios.descripcion as consultorio_nombre')
    ->leftJoin("sub_consultorios", "sub_consultorios.id", "=", "prestaciones.id_sub_consultorio")
    ->leftJoin("consultorios", "consultorios.id", "=", "sub_consultorios.id_consultorio")
    ->leftJoin("medicos", "medicos.id", "=", "prestaciones.id_medico")
    ->leftJoin("establecimientos", "establecimientos.id", "=", "prestaciones.id_establecimiento")
    ->where("id_asegurado", $id_asegurado)->whereNotNull("informe_pp")->get();
    return json_encode($prestaciones);
  }

