            $query->select('prestaciones.id', 'prestaciones.id_establecimiento', 'prestaciones.id_asegurado', 'prestaciones.updated_at', 'prestaciones.fecha_atencion', 'prestaciones.created_at', 'prestaciones.id_tipo_atencion', 'prestaciones.id_sub_consultorio', 'prestaciones.id_medico')
              ->with(['establecimiento' => function ($q) {
                  $q->select('establecimientos.id', 'establecimientos.nombre');
              }]);
        }
