    $servicio = SubConsultorio::where("sub_consultorios.id", $solicitudPp->prestacion->id_sub_consultorio)
    ->leftJoin("consultorios", "sub_consultorios.id_consultorio", "=", "consultorios.id")
    ->select(
        'consultorios.nombre as nombre_consultorio'
    )
    ->first();
    $medicoPrestacion = Medico::where("id", $solicitudPp->prestacion->id_medico)->first();
    $datos_paciente = $this->getDatosPaciente($solicitudPp->prestacion->id_asegurado);
    $pdf = \PDF::loadView(
            'pdf.ver_solicitud_pp_pdf',
            compact(
              "solicitudPp",
              "diagnosticosAtencion",
              "datos_paciente",
              "servicio",
              "medicoPrestacion",
              "detallesAgrupados"
