        );
    $pdf->getDomPDF()->set_option("enable_php", true);
    $pdf->setPaper('A4', 'portrait');
    return $pdf->stream('solicitud_pp.pdf');
  }

  public function calcularIpress_bene($nro_doc_ident) 
  {
    $prestaciones = DB::table("prestaciones")
    ->join("asegurados", "asegurados.id", "=", "prestaciones.id_asegurado")
    ->where("asegurados.nro_doc_ident", $nro_doc_ident)
    ->select("prestaciones.created_at as fecha_creacion")
    ->get();
    
    $anioActual = Carbon::now()->year;
    
    $tieneEnEsteAnio = false;

    foreach ($prestaciones as $p) {
      $fechaSinMs = substr($p->fecha_creacion, 0, 19);
      $anio = Carbon::parse($fechaSinMs)->year;

      if ($anio == $anioActual) {
          $tieneEnEsteAnio = true;
          break;
      }
    }

    if (empty($prestaciones)) {
      $evaluacion = "NUEVO";
    } elseif ($tieneEnEsteAnio) {
        $evaluacion = "CONTINUADOR";
    } else {
        $evaluacion = "REINGRESO";
    }
    return $evaluacion;
  }

