  private function ppConfiguracionSolicitados(Request $request){
    $config = array();
    if (!$request->pp_activo || !is_array($request->id_procedimiento_p)) {
      return $config;
    }
    $ids = array_values(array_filter(array_map('intval', $request->id_procedimiento_p), function ($id) { return $id > 0; }));
    if (count($ids) == 0) {
      return $config;
    }
    $filas = DB::table('procedimientos_servicios')
      ->where('id_servicio', intval($request->id_servicio))
      ->where('id_establecimiento', Auth::user()->id_establecimiento)
      ->where('id_estado_reg', 1)
      ->whereIn('id_procedimiento', $ids)
      ->get();
    foreach ($filas as $fila) {
      $config[intval($fila->id_procedimiento)] = $fila;
    }
    foreach ($ids as $id) {
      if (!isset($config[$id])) return null;
    }
    return $config;
  }

  private function ppPlazoAgregarVencido(Request $request){
    if (!$request->pp_activo || !is_array($request->id_procedimiento_p)) {
      return false;
    }
    if (count(array_filter(array_map('intval', $request->id_procedimiento_p), function ($id) { return $id > 0; })) == 0) {
      return false;
    }
    $limite = SolicitudProgramacionProcedimientos::ppLimiteAgregar($request->id_prestacion);
    return $limite && Carbon::now()->gt($limite);
  }

