        //   "is_programacion_quirurgica" => true,
        //   "id_medico_reg_programacion" => $idMedico,
        //   "id_prioridad_programacion" => $idPrioridadProgramacion,
        //   "is_requiere_internamiento_preqx" => $isRequiereInternamientoPreqx,
        //   "is_hospitalizacion_postqx" => $isHospitalizacionPostqx,
        //   "id_lugar_operacion" => $idLugarOperacion,
        //   "id_tiempo_internamiento_preqx" => $idTiempoInternamientoPreqx,
        //   "id_tiempo_hospitalizacion_postqx" => $idTiempoHospitalizacionPostqx,
        //   "id_prestacion" => $id_prestacion,
        //   "flag" => 3
        // ]);

        $cqxIntervencionUpdate = CqxIntervencion::find($idCqxIntervencion);
        $cqxIntervencionUpdate->update([
          "id_medico_reg_programacion" => $idMedico,
          "id_prioridad_programacion" => $idPrioridadProgramacion,
          "is_requiere_internamiento_preqx" => $isRequiereInternamientoPreqx,
          "is_hospitalizacion_postqx" => $isHospitalizacionPostqx,
          "id_lugar_operacion" => $idLugarOperacion,
          "fecha_probable" => $fechaProbable,
          "hora_fin_prog_qx" => $horaFinPq,
          "hora_inicio_prog_qx" => $horaInicioPq,
          "emergencia_duracion_cirugia" => $tiempoCuracionCqx,
          "flag" => 2,
          "id_tiempo_internamiento_preqx" => $idTiempoInternamientoPreqx,
          "id_tiempo_hospitalizacion_postqx" => $idTiempoHospitalizacionPostqx,
          "emergencia_tipo_cirugia"=>$id_tipo_cirugia
        ]);
          
        if (isset($request->cqx_profesional) && is_array($request->cqx_profesional) && count($request->cqx_profesional) > 0) {
          $modelCqProfesional = new CqxProfesional();
          foreach ($request->cqx_profesional as $key => $cqxProfesional) {
            if (isset($cqxProfesional)) {
              $pIdMedico = $request->cqx_profesional[$key];
              $pIdMedicoCargo = (isset($request->cqx_tipo_professional[$key]) && $request->cqx_tipo_professional[$key] > 0 ? $request->cqx_tipo_professional[$key] : 0);
              $flagPersonal = 0;
              $response = $modelCqProfesional->RegistrarProfesionalesPreQx(
                                                  $idCqxIntervencion,
                                                  $pIdMedico, 
                                                  $pIdMedicoCargo,
                                                  Auth::user()->id,
                                                  $flagPersonal,
                                                  $cqxCitaId);
            }
          }
        }
        
        // Registra Prestacion Principal para utilizar en Cqx Intraoperatorio - Qurirurgico - Anestesiologia
        $MedicoId_Request = !empty($request->cqx_profesional)  ? ($request->cqx_profesional[0])  : null; 
        if($MedicoId_Request==null){
            Session::flash('flash_message', 'No se pudo registrar la Prestacion, Debe seleccionar un cirujano !');
            return redirect('/all_citas_medico_paciente');
        }
        if( empty($request->fecha_probable_pq) && !isset($request->fecha_probable_pq)){
            Session::flash('flash_message', 'No se pudo registrar la Prestacion, Debe indicar la fecha  probable !');
            return redirect('/all_citas_medico_paciente');
        }
        $PrestacionUnica_returnId = $model_prestacion->registrarPrestacion_cqxPrincipal($idCqxIntervencion,$id_cita,$id_asegurado,3, $request->id_establecimiento,$request->fecha_probable_pq,  $MedicoId_Request , $id_estado_reg, $request->id_user, $ipress_bene,$upss_bene, $request->id_modalidad,  $request->codigo_upss,null,null,null);                      
        if(empty($PrestacionUnica_returnId) || $PrestacionUnica_returnId==0){
            Session::flash('flash_message', 'No se pudo registrar la Prestacion, Hubo problema con el registro de Prestacion Principal!');
            return redirect('/all_citas_medico_paciente');
        }

        if (isset($request->cqx_procedure_id_pq) && is_array($request->cqx_procedure_id_pq) && count($request->cqx_procedure_id_pq) > 0) {
          $modelCqProcedimiento = new CqxProcedimiento();
          foreach ($request->cqx_procedure_id_pq as $key => $cqxProcedureId) {
            $response = $modelCqProcedimiento->RegistrarProcedimientoPreQx(
                                                  $idCqxIntervencion,
                                                  $cqxProcedureId,
                                                  Auth::user()->id,
                                                  $cqxCitaId,
                                                  1,
                                                  false);
          }
        }

        $modelUpss = new Upss();
        $upssQp = $modelUpss->upssPorServicioPorIdAtencion($request->id_servicio, 3);
        $idUpssTraslado = isset($idLugarOperacion) && intval($idLugarOperacion) === 2 ? 66 : $upssQp->id; 
        $fechaDerivacion = Carbon::now();
        $model_orden = new HospitalizacionOrden();
        $response = $model_orden->RegistrarOrdenDeHospitalizacionSinValidar(
                                    $request->id_establecimiento,
                                    $id_tipo_atencion,
                                    $idCqxIntervencion,
                                    $idAseguradoPq,
                                    $fechaDerivacion,
                                    $request->id_medico,
                                    $request->id_servicio,
                                    Auth::user()->id,
                                    $upssQp->id,
                                    $idUpssTraslado,
                                    $idLugarOperacion,null);
                                    
        if (
          isset($isActiveInterconsultaPreQuirurgicaPq) && 
          intval($isActiveInterconsultaPreQuirurgicaPq) === 1 &&
          isset($request->preqx_id_servicio_pq) &&
          is_array($request->preqx_id_servicio_pq) &&
          count($request->preqx_id_servicio_pq)
          ) {
            $currentTime = Carbon::now();
            $turno = "M";
            if ($currentTime->between(Carbon::createFromTime(1, 31), Carbon::createFromTime(7, 30))) {
              $turno = 'MD'; // madrugada
            } elseif ($currentTime->between(Carbon::createFromTime(7, 31), Carbon::createFromTime(13, 30))) {
              $turno = 'M';  // mañana
            } elseif ($currentTime->between(Carbon::createFromTime(13, 31), Carbon::createFromTime(19, 30))) {
              $turno = 'T';  // tarde
            } elseif ($currentTime->between(Carbon::createFromTime(19, 31), Carbon::createFromTime(23, 59))) {
              $turno = 'N';  // noche
            } else {
              $turno = 'N';
            }
            foreach ($request->preqx_id_servicio_pq as $key => $preqxInterconsulta) {
              $upss = DB::table('upsses')
