                      ->where('id_consultorio', $preqxInterconsulta)
                      ->where('id_tipo_atencion', 1)
                      ->where('estado', 1)
                      ->first();
                      
              $preqxMotivo = isset($preqx_motivo_interconsulta_pq[$key]) ? $preqx_motivo_interconsulta_pq[$key] : null; 
              if (isset($upss) && !empty($upss)) {
                Interconsulta::create([
                  'id_prestacion' => $id_prestacion,
                  'id_asegurado' => $idAseguradoPq,
                  'id_ext' => $prestacionPq->id_ext,
                  'id_tipo_atencion' => $prestacionPq->id_tipo_atencion,
                  'fecha_atencion' => $prestacionPq->fecha_atencion,
                  'id_medico_solicitante' => $prestacionPq->id_medico,
                  'motivo_interconsulta'=> $preqxMotivo,
                  'id_establecimiento'=> $prestacionPq->id_establecimiento,
                  'id_estado_reg'=> 1,
                  'id_servicio'=> $preqxInterconsulta,
                  'turno'=> $turno,
                  'codigo_upss'=> $upss->codigo,
                  'descripcion_upss'=> $upss->descripcion_upss,
                  'created_at' => Carbon::now(),
                  'pre_quirurgico' => true
                ]);

                CqxCita::create([
                  'id_cqx_intervenciones' => $idCqxIntervencion,
                  'id_consultorio' => $preqxInterconsulta,
                  'id_prestacion' => 0,
                  'id_cita' => 0,
                  'tipo' => 1,
                  'flag' => 1,
                  'id_estado_reg'=> false,
                  'created_us'=> Auth::user()->id,
                  'created_at' => Carbon::now(),
                  'es_interconsulta' => true,
                ]);
              }
            }
        }
        if ($request->hasFile('fileMopri_pq')) {
          foreach ($request->fileMopri_pq as $fileMopriPq) {
            if (!is_null($fileMopriPq) && $fileMopriPq->isValid()) {
              $timestamp = Carbon::now()->format('YmdHis');
              $uniqueId = uniqid();
              $extension = $fileMopriPq->getClientOriginalExtension();
              $original_name = $fileMopriPq->getClientOriginalName();
              $size = $fileMopriPq->getSize();
              $tipoDocumento = $fileMopriPq->getClientMimeType(); 
              $directorio = 'formatos_escaneados';
              $nombreArchivo = "mopri_{$timestamp}_{$uniqueId}." . strtolower($extension);
              $rutaRelativa = $directorio . '/' . $nombreArchivo;
              $contenido = file_get_contents($fileMopriPq->getRealPath());
              if (!Storage::disk('local')->exists($directorio)) {
                Storage::disk('local')->makeDirectory($directorio);
              }
              Storage::disk('local')->put($rutaRelativa, $contenido);
              $pathFile = $rutaRelativa;
              $newCqxFormatoEscaneado = CqxFormatoEscaneado::create([
                'id_tipo_formato' => 2,
                'id_intervencion' => $idCqxIntervencion,
                'id_asegurado' => $idAseguradoPq,
                'tipo_documento' => $tipoDocumento,
                'tamano_archivo' => $size,
                'fecha_creacion' => Carbon::now()->toDateString(),
                'hora_creacion' => Carbon::now()->toTimeString(),
                'created_us' => Auth::user()->id,
                'created_at' => Carbon::now()->toDateString(),
                'estado' => 1,
                'ruta' => $directorio . '/',
                'nombre_archivo' => $nombreArchivo,
                'flag_origen_escaneado' => 1,
                'nombre_simple' => $original_name
              ]);
            }
          }
        }
      }
    }
    if (intval($request->has_intervencion_quirurgica)==0 && intval($request->valueToogleProgramacionQuirurgica_pq)==0) {
      if(!empty($request->id_cqx_intervencion_pq)){
        $newCqxCita = CqxCita::create([
          "id_cqx_intervenciones" => $idCqxIntervencion,
          "id_consultorio" => $request->id_servicio,
          "id_prestacion" => $id_prestacion,
          "fecha_atencion" => Carbon::now(),
          "id_cita" => $id_cita,
          "tipo" => 2,
          "flag" => 3,
          "id_estado_reg" => 1,
          "created_us" => Auth::user()->id,
          "created_at" => Carbon::now()
        ]);
      }
    }

    /******************* END - PROGRAMACIÓN QUIRÚRGICA ************************** */

      
    DB::commit();
    
    if ($id_prestacion == 0) {  
      Session::flash('flash_message', 'No se pudo registrar la Prestacion, hubo un problema con la conexión de internet de su establecimiento PNP, vuelva a intentarlo nuevamente');
      return redirect('/listar_citas_medico_paciente');
    } else {
      Session::flash('flash_message', 'Prestación exitosa');
      return redirect('/ver_prestacion/' . $request->id_user . '/' . $id_prestacion);
    }

    } catch (QueryException $e) {
      DB::rollback();
      throw $e;
    } catch (Exception $e) {
      DB::rollback();
      throw $e;
    }
  }

