        $flag_cq = intval($request->has_intervencion_quirurgica);
        $id_hora_toma_muestra = null;

        $id_procedimiento_lab = $model_procedimiento->RegistrarLaboratorioOrden3($request->id_user, $id_prestacion, $request->id_establecimiento, $request->fecha_hora_atencion, $p_laboratorio, $has_observacion_unica, $id_evaluacion, $request->id_farmacia, $id_interconsulta, $request->id_tipo_atencion, $request->id_servicio, $id_area, $id_cama, $request->id_medico, $cita->id_asegurado, $lab_orden_observacion_unica, $flag_cq, $id_hora_toma_muestra);
      endif;
    endif;

