      $solicitudPp = null;
      foreach ($request->id_procedimiento_p as $key => $procedimiento_id) {
        if (intval($procedimiento_id) <= 0) continue;
        if (!$solicitudPp) {
          $solicitudPp = new SolicitudProgramacionProcedimientos();
          $solicitudPp->id_prestacion = $id_prestacion;
          $solicitudPp->id_tipo_atencion = $request->id_tipo_atencion;
          $solicitudPp->asegurado_dni = $request->dni_beneficiario;
          $solicitudPp->fecha_solicitud = Carbon::now();
          $solicitudPp->created_us = Auth::id();
          $solicitudPp->updated_us = Auth::id();
          $solicitudPp->save();
        }
        for ($i = 0; $i < intval($request->procedimiento_cantidad_p[$key]); $i++) {
          $solicitudPp->detalles()->create([
            'id_procedimiento' => $procedimiento_id,
            'requiere_cita' => $pp_config[intval($procedimiento_id)]->requiere_cita,
            'requiere_informe' => $pp_config[intval($procedimiento_id)]->requiere_informe,
            'cantidad' => $request->procedimiento_cantidad_p[$key],
            'id_diagnostico' => $request->miSelectPp[$key],
            'indicacion' => $request->procedimiento_indicacion_p[$key],
            'created_us' => Auth::id(),
            'updated_us' => Auth::id(),
          ]);
        }
        if (!$solicitudPp->tiene_pendientes) {
          $solicitudPp->tiene_pendientes = true;
          $solicitudPp->save();
        }
      }
    }

    /*function escape_pg_value($value) {
    if ($value === null || $value === '') return 'NULL';
    if (is_numeric($value)) return $value;
    $escaped = str_replace(['\\', '"'], ['\\\\', '\\"'], $value);
    return '"' . $escaped . '"';
    }*/
    if (isset($request->id_examen_rad)) :
      $p_radiologia = "";
