      $p_radiologia .= "}";
      if($request->id_examen_rad[0]!=""):
        $id_procedimiento_rad = $model_procedimiento->RegistrarProcedimientoImagenes($request->id_user, $id_prestacion, $request->id_establecimiento, $request->fecha_expedicion, $p_radiologia, 3, 0, $request->id_farmacia);
        /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////// Identificar radiología a la cual pertenece 
        if($request->id_establecimiento == 76 ){
          $updated = DB::table('rua_imagenologia')->where('id', $request->id_rua_imagenes)->update(['id_rad' => $id_procedimiento_rad, 'id_estado_reg' => 1, 'id_asegurado' => $cita->id_asegurado]);
        }
        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
      endif;
    endif;

    /***************************************************************************/
    $model_interconsulta = new \App\Models\Interconsulta;
    
    if (isset($request->id_servicio_interconsulta)) :
