  public function ver_mopri($id_prestacion,$id_intervencion,$id_cita,$id_hospitalizacion){

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;
    
    $id_user = Auth::user()->id;
    $model_intraoperatorio = new IntraOperatorio;
    $model_atencione = new CqxAtencione;
    $model_intervencion = new CqxIntervencion;
    $model_prestacion = new Prestaciones;
    $modal_cita = new Cita;
    $model_receta = new Receta_vale;
    $model_asegurado = new Asegurado;

    $codigo_cups="";
    $hopitalizacion = Hospitalizacione::select('hospitalizaciones.id', 'hospitalizaciones.cups_pnp')
    ->join('cqx_intervenciones', 'hospitalizaciones.id', '=', 'cqx_intervenciones.id_hospitalizacion')
    ->where('cqx_intervenciones.id',  $id_intervencion)
    ->first();
    if(!empty($hopitalizacion->cups_pnp)){
      $codigo_cups=$hopitalizacion->cups_pnp;
    }

    $intervencion = $model_intervencion->GetById($id_intervencion);

    $ultimoRegistro = CqxAtencione::where('id_cqx_intervencion', $id_intervencion)->orderBy('created_at', 'desc')->first();
   
    $atencion = $model_atencione->GetDatosByIdIntervencion_cqx($id_intervencion);

    $prestacion = $model_prestacion->GetPrestacionById($ultimoRegistro->id_prestacion);
    //dd($prestacion);

    $procedimiento = $model_prestacion->GetProcedimientosByIdPrestacion($ultimoRegistro->id_prestacion, 1);

    $dato_titular = $model_asegurado->Busca_datos_titular($prestacion->id_asegurado_titular);
    
    $admision = $model_receta->getHospitalizacionById_farmacia_new_x($id_hospitalizacion);

    $cirujanos = $model_intraoperatorio->profesiones_activos(0,$id_intervencion);

    





    return view('frontend.atenciones.ver_mopri', compact('id_prestacion','id_intervencion','id_cita','codigo_cups','intervencion','prestacion','dato_titular','admision','cirujanos','procedimiento'));
  }


