public function editProcedimiento(Request $request)
{
  foreach ($request->prestacion_procedimiento_id as $prestacion_procedimiento) {
    $r = DB::table('prestacion_procedimientos')
      ->where('id', $prestacion_procedimiento)
    //->get();
      ->update([
        'id_procedimiento' => $request->id_procedimientos[$prestacion_procedimiento],
