  public function registrar_emergencia_transaction(Request $request)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    if (count($request) > 0) {
      $model_emergencia = new \App\Models\Emergencia;
      $model_farma = new Farmacia;

      $farma = $model_farma->GetFarmaByIdfarma($request->id_farmacia);
      $id_establecimiento = $farma->id_establecimiento;
      $nro_emergencia = $model_emergencia->getNroEmergencia($id_establecimiento);

      //mantbeneficiario                          
      $model_asegurado = new \App\Models\Asegurado;

      $model_asegurado->tipo_doc_ident = $request->tipdoc_beneficiario;
      $model_asegurado->nro_doc_ident = $request->dni_beneficiario;
      $model_asegurado->cip  = $request->cip;
      $model_asegurado->nombre   = $request->nombre_beneficiario;
      $model_asegurado->paterno   = $request->paterno_beneficiario;
      $model_asegurado->materno  = $request->materno_beneficiario;
      $model_asegurado->sexo    = $request->sexo;
      $model_asegurado->fecha_nac   = $request->fecha_nac;
      $model_asegurado->id_estado_reg   = '1';
      $model_asegurado->observacion  = 'Pruebas';
      $model_asegurado->created_us   = $request->id_user;

      //$model_asegurado->id_distrito //De la Reniec
      //$model_asegurado->direccion   =$request->Direccion; //De la Reniec
      $model_asegurado->id_distrito_referencial = $request->Distrito;
      $model_asegurado->domicilio  = $request->direccion_referencial;
      //$model_asegurado->direccion_referencial  =$request->direccion_referencial;                        
      $model_asegurado->telefono = $request->telefono;

      $existe_beneficiario = \App\Models\Asegurado::where('nro_doc_ident', '=', $request->dni_beneficiario)->first();

      if ($existe_beneficiario == false) {
        $model_asegurado->save();
        $id_persona = $model_asegurado->id;
      } else {
        $existe_beneficiario->cip  = $request->cip;

        $id_persona = $existe_beneficiario->id;
        $existe_beneficiario->save();
      }

      $model_asegurado_historia = new \App\Models\Asegurado_historia;
      $model_asegurado_historia->id_asegurado = $id_persona;
      $model_asegurado_historia->id_establecimiento  = $id_establecimiento;
      $model_asegurado_historia->nro_historia  =   $request->nro_historia;
      $model_asegurado_historia->id_estado_reg =  '1';
      //created_at  updated_at  updated_us  deleted_at  deleted_us
      $model_asegurado_historia->created_us = $request->id_user;

      $existe_asegurado_historia = \App\Models\Asegurado_historia::where('id_asegurado', '=', $id_persona)->where('id_establecimiento', $id_establecimiento)->first();

      if ($existe_beneficiario == false) {
        $model_asegurado_historia->save();
      }


      $obtenerId = DB::Transaction(function () use ($request, $nro_emergencia, $id_establecimiento, $id_persona) {
        /*$model_cuarto = new \App\Models\Cuarto;
                        $model_consultorio = new \App\Models\Consultorio;
                        $model_asignacion = new \App\Models\Asignacion_servicio;
                        $model_cama = new \App\Models\Cama;*/
        $model_usuario = new User;
        $emergencia = new \App\Models\Emergencia;

        $emergencia->nro_emergencia = $nro_emergencia;

        $emergencia->dni_beneficiario = $request->dni_beneficiario;
        $emergencia->dni_titular = $request->dni_titular; //VALIDAR 


        $emergencia->secuencia = 0;
        $emergencia->fecha_ingreso = $request->fecha_atencion;
        //$emergencia->fecha_egreso=$request->fecha_egreso;//EGRESO  

        $emergencia->prioridad = $request->Prioridad;
        $emergencia->conducido = $request->Conducido;

        $emergencia->hora_ingreso = $request->hora_atencion;
        //$emergencia->hora_egreso =$request->hora_egreso;//EGRESO  

        $emergencia->id_persona  = $id_persona; //FALTA
        $emergencia->codigo_usuario_ingreso  = $request->id_user;
        $emergencia->id_urgencia = null;

        $emergencia->id_forma_ingreso = $request->id_forma_ingreso;
        $emergencia->id_estado_ingreso = $request->id_estado_ingreso;

        //$emergencia->id_condicion=$request->id_condicion; //EGRESO    
        //$emergencia->id_destino=$request->id_destino;  //EGRESO
        $emergencia->id_triaje = $request->id_triaje;
        /* id_tarifa   
                        codigo_usuario_egreso   id_sala codigo_medico   folio   numero_descanso_medico  observacion fecha_registro_ingreso  hora_registro_ingreso   fecha_registro_egreso   hora_registro_egreso    fecha_atencion  hora_atencion   codigo_medico_2 id_sub_especialidad_servicio    numero_boleta   numero_documento_coronel_guardia */ //ATENCION y EGRESO   
        $emergencia->categoria = $request->categoria;

        $emergencia->temperatura = $request->temperatura;
        $emergencia->sa02_porcentaje = $request->sa02_porcentaje;
        $emergencia->presion_arterial_x = $request->presion_arterial_x;
        $emergencia->presion_arterial_y = $request->presion_arterial_y;
        $emergencia->talla_cm = $request->talla_cm;
        $emergencia->tamano_cintura_cm = $request->tamano_cintura_cm;
        $emergencia->frecuencia_respiratoria = $request->frecuencia_respiratoria;
        $emergencia->peso_kg = $request->peso_kg;
        $emergencia->frecuencia_cardiaca_fetal = $request->frecuencia_cardiaca_fetal;
        $emergencia->frecuencia_cardiaca = $request->frecuencia_cardiaca;
        $emergencia->fi02 = $request->fi02;
        $emergencia->id_establecimiento = $id_establecimiento;
        $emergencia->save();
        $id_hospitalizacion = $emergencia->id;
        return $id_hospitalizacion;
      });

      if ($obtenerId == 0) {
        Session::flash('flash_message', 'No se pudo registrar la Hospitalización, hubo un problema con la conexión de internet de su establecimiento PNP, vuelva a intentarlo nuevamente');
        //return redirect('/nueva_hospitalizacion/' . $request->id_user . '/' . $request->id_farmacia);
      } else {
        Session::flash('flash_message', 'Hospitalización exitosa, El numero de Hospitalizacion es ' . $nro_emergencia);
        return redirect('/ver_hospitalizacion/' . $request->id_user . '/' . $obtenerId);
      }
    } else {
      return redirect('/nueva_admision/');
    }
  }

  public function formulario_atencion_teleconsulta()
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;
    $model_medico = new Medico();
    $model_usuario = new User;
    $id_user = Auth::user()->id;
    $usuario_actual = $model_usuario->GetById($id_user);
    $id_farmacia = Auth::user()->id_farmacia;
    $model_consultorio = new Consultorio;
    $model_kardex = new Kardexe();
    $fechaServidor = $model_kardex->getFechaServidor();
