    $model_radiologia = new \App\Models\Radiologia;
    $model_cqx_tipo_profesional = new CqxTipoProfesional;
    $model_kardex = new Kardexe();
    $model_medico = new Medico();
    $model_consultorio = new Consultorio();
    $model_medico_consultorio = new Medico_consultorio();

    $farmacia = $modelfarma->GetFarmaByUser(Auth::user()->id);
    $id_farmacia = $farmacia->id;
    $flag_receta_dias = $farmacia->flag_receta_dias;

    $fechaServidor = $model_kardex->getFechaServidor();
    $date = Carbon::now();
    $fecha_actual = $date->format('d-m-Y');
    $receta = $model_receta->GetDatosRecetasByIdPrestacion($id_prestacion);

    $diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacion($id_prestacion);
    $procedimiento = $model_prestacion->GetProcedimientosByIdPrestacion($id_prestacion, 1);
    //$laboratorio = $model_prestacion->GetProcedimientosByIdPrestacion($id_prestacion, 2);
    //$laboratorio = $model_prestacion->GetProcedimientosByIdPrestacionLab($id_prestacion);
    $laboratorio = $model_laboratorio->GetLaboratorioByIdPrestacion($id_prestacion);
    $radiologia = $model_prestacion->GetProcedimientosByIdPrestacion($id_prestacion, 3);
    $pendiente_firma = $model_prestacion->GetDocumentosPendintesFirmarPrestacionId($id_prestacion);
    $flag_pendinte_firma = (count($pendiente_firma) > 0) ? 1 : 0;

    $id_ipress = $farmacia->id_establecimiento;
    $establecimiento = $model_establecimiento->GetById($id_ipress);
    if ($id_ipress == 1) {
      $nivel = 2;
    } else {
      $nivel = $establecimiento[0]->nivel;
    }

    /*
    if($prestacion->tipo_atencion=='EMERGENCIA'):
      $model_emergencia = new \App\Models\Emergencia;
      $obtenerdato = $model_emergencia->GetObtenerServicio($prestacion->id_ext);
      $prestacion->servicio= $obtenerdato->servicio;
      $prestacion->consultorio= $obtenerdato->consultorio;
      $producto = $model_producto->getProductosByNivelAndIdServicio($nivel, 76, $id_farmacia); //76 -> servicio de hopitalizacion 
    else:
      if($prestacion->tipo_atencion=='HOSPITALIZACION'){
        $model_hospitalizacion = new \App\Models\Hospitalizacione;
        $obtenerdatoh = $model_hospitalizacion->GetObtenerDatos($prestacion->id_ext);
        $prestacion->servicio= $obtenerdatoh->servicio;
        $prestacion->consultorio= $obtenerdatoh->consultorio;
        $prestacion->pabellon= $obtenerdatoh->pabellon;
        $prestacion->piso= $obtenerdatoh->piso;
        $prestacion->cuarto= $obtenerdatoh->cuarto;
        $prestacion->cama= $obtenerdatoh->cama;
      
      }
      $producto = $model_producto->getProductosByNivelAndIdServicio($nivel, $prestacion->id_consultorio, $id_farmacia);
    endif; */

    $producto = $model_producto->getProductosByNivelAndIdServicio($nivel, $prestacion->id_consultorio, $id_farmacia);
    
    $farmacias = $modelfarma->GetFarmaciaByIdEstablecimiento($id_ipress);

    $datos_gastro = null;

    if ($prestacion->id_consultorio == 102 &&  $prestacion->id_establecimiento==76) {
      //----------- INICIO OFTALMOLOGÌA -----------
      $datos_gastro = Gastroenterologia::where('prestacion_id', '=', $id_prestacion)->first();
      //----------- FIN OFTALMOLOGÌA -----------
    }
    $cqx_tipo_professionales = $model_cqx_tipo_profesional->GetAllActivos();

    $cqx_profesionales = $model_medico->GetProfesionalesXEspecialidad($prestacion->id_establecimiento, $prestacion->id_consultorio);

    $consultorios = $model_consultorio->ShowConsultorios($farmacia->id);

    $model_riesgo_qx = new \App\Models\CqxCita();
    // $data_cq_cita = $model_riesgo_qx->GetCitaIntervencionQuirurgica($prestacion->id_cita);
    
    $intervencion_quirurgica = DB::table('cqx_intervenciones as iq')
            ->join('prestaciones as p', 'iq.id_prestacion', '=', 'p.id')
            ->join('sub_consultorios as sc', 'p.id_sub_consultorio', '=', 'sc.id')
            ->join('consultorios as c', 'sc.id_consultorio', '=', 'c.id')
            ->where('iq.id_asegurado', $prestacion->id_asegurado)
            ->where('iq.id_establecimiento', $prestacion->id_establecimiento)
            ->where('iq.id_consultorio', $prestacion->id_consultorio)
            ->where('iq.flag', 1)
            // ->whereIn('iq.flag', [1, 2, 3])
            ->select('iq.id', 'iq.id_prestacion', 'iq.flag as estado', 'c.nombre as consultorio', DB::raw("TO_CHAR(iq.fecha_solicitud, 'DD-MM-YYYY') as fecha_solicitud"))
            ->orderBy('iq.id', 'desc')
            ->first();

    $medico_intervencion = $model_medico->GetMedicoByDNI(Auth::user()->dni, Auth::user()->id_establecimiento);
    $especialidad_medico = $model_medico_consultorio->GetConsultorioByIdEstablecimientoAndIdMedico(Auth::user()->id_establecimiento, $medico_intervencion->id, $prestacion->id_consultorio);

    $showFormIntervencionQuirurgica = false;
    $showFormDetailIntervencionQuirurgica = false;
    if ($intervencion_quirurgica && intval($intervencion_quirurgica->estado) === 1) {
      $showFormDetailIntervencionQuirurgica = true;
    } else {
      if (
        intval($prestacion->id_establecimiento) === intval(Auth::user()->id_establecimiento) && 
        isset($especialidad_medico) && 
        count($especialidad_medico) > 0 && 
        $especialidad_medico[0]->flag_quirurgico
      ) {
        $showFormIntervencionQuirurgica = true;
      }
    }
    return view('frontend.atenciones.mostrar_atencion', compact('farmacia', 'prestacion', 'diagnostico', 'procedimiento', 'medicamentos', 'id_prestacion', 'fechaServidor', 'receta', 'producto', 'farmacias', 'nivel', 'laboratorio', 'radiologia', 'flag_pendinte_firma','datos_gastro', 'cqx_tipo_professionales', 'cqx_profesionales', 'consultorios', 'intervencion_quirurgica', 'showFormIntervencionQuirurgica', 'showFormDetailIntervencionQuirurgica'));
  }

