  public function condicion_paciente_ant($nro_doc_ident, $id_establecimiento, $id_tipo_atencione, $id_sub_consultorio){
  
    $model_prestacion = new Prestaciones;
    $count_establecimiento = $model_prestacion->GetCountAtenciones($nro_doc_ident, $id_establecimiento, $id_tipo_atencione);
    
    if($count_establecimiento->atencion > 0):
      $condicion['ipress_bene'] = 'CONTINUADOR';
      $count_servicio = $model_prestacion->GetCountAtenciones($nro_doc_ident, $id_establecimiento, $id_tipo_atencione, $id_sub_consultorio);
      
      if($count_servicio->atencion>0):
        $condicion['upss_bene'] = 'CONTINUADOR';
      else:
        $condicion['upss_bene'] = 'NUEVO';
      endif;
    else:
      $condicion['ipress_bene'] = 'NUEVO';
      $condicion['upss_bene'] = 'NUEVO';
    endif;
    echo json_encode($condicion);
  }

  public function condicion_paciente($nro_doc_ident, $id_establecimiento, $id_tipo_atencione, $id_sub_consultorio){
  
    $model_prestacion = new Prestaciones;

    // Cantidad de atenciones en el Establecimiento o IPRESS
    $cant_atenciones_ipress = $model_prestacion->GetCountAtencionesPorAnioActual($nro_doc_ident, $id_establecimiento, $id_tipo_atencione);

    if ($cant_atenciones_ipress->atenciones > 0):
      $condicion['ipress_bene'] = 'CONTINUADOR';
    else:
      $cant_atenciones_ipress2 = $model_prestacion->GetCountAtencionesActual($nro_doc_ident, $id_establecimiento, $id_tipo_atencione);
      if ($cant_atenciones_ipress2->atenciones == 0):
        $condicion['ipress_bene'] = 'NUEVO';
      else:
        $condicion['ipress_bene'] = 'REINGRESO';
      endif;
    endif;

    // Cantidad de atenciones en el Servicio o UPSS
    $cant_atenciones_servicio = $model_prestacion->GetCountAtencionesPorAnioActual($nro_doc_ident, $id_establecimiento, $id_tipo_atencione, $id_sub_consultorio);

    if ($cant_atenciones_servicio->atenciones > 0):
      $condicion['upss_bene'] = 'CONTINUADOR';
    else:
      $cant_atenciones_servicio2 = $model_prestacion->GetCountAtencionesActual($nro_doc_ident, $id_establecimiento, $id_tipo_atencione, $id_sub_consultorio);
      if ($cant_atenciones_servicio2->atenciones == 0):
        $condicion['upss_bene'] = 'NUEVO';
      else:
        $condicion['upss_bene'] = 'REINGRESO';
      endif;
    endif;
    echo json_encode($condicion);
  }

  public function CalculoLimiteFechaCita($id_ipress, &$fechaAtencion, &$aFeriado) {
    $aDetalle = [];
    $aDetalle['fecha'] = $fechaAtencion;
    $aDetalle['es_feriado'] = false;
    $aDetalle['es_domingo'] = false;

    $establecimiento = (new \App\Models\Establecimiento())->Get($id_ipress);

    $aDetalle['intervalo_cita'] = $intervalo_cita = 4;

    if(!empty($establecimiento)) {
      $aDetalle['intervalo_cita'] = $establecimiento->intervalo_cita;
      $intervalo_cita = $establecimiento->intervalo_cita - 1;
    }

    $aFechaAtencion = explode('-', $fechaAtencion);
    $diaSemana = date('N', mktime(0, 0, 0, $aFechaAtencion[1], $aFechaAtencion[2], $aFechaAtencion[0]));
    if ($diaSemana == 7) {
      $aDetalle['es_domingo'] = true;
    }

    if (array_key_exists($fechaAtencion, $aFeriado)) {
      $aDetalle['es_feriado'] = true;
    }
 // Matriz de días de la semana
 $days_dias = array(
  'Monday'=>'Lunes',
  'Tuesday'=>'Martes',
  'Wednesday'=>'Miercoles',
  'Thursday'=>'Jueves',
  'Friday'=>'Viernes',
  'Saturday'=>'Sabado',
  'Sunday'=>'Domingo'
  );

  //Buscar día
  $aDetalle['diasseleccionados'] = $days_dias [date('l', mktime(0, 0, 0, $aFechaAtencion[1], (int)$aFechaAtencion[2],$aFechaAtencion[0]))];
        $aDetalle['fecha_inferior'] = date('Y-m-d', mktime(0, 0, 0, $aFechaAtencion[1], (int)$aFechaAtencion[2] - $intervalo_cita, $aFechaAtencion[0]));
    
        $aDetalle['fecha_superior'] = date('Y-m-d', mktime(0, 0, 0, $aFechaAtencion[1], (int)$aFechaAtencion[2] + $intervalo_cita, $aFechaAtencion[0]));   
    
        return $aDetalle;
      }

  public function hc_electronica($id_asegurado) {
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $flag_bloqueo_atencion = $id_asegurado ? DB::table('asegurados')->where('id', $id_asegurado)->value('flag_bloqueo_atencion') : null;
    if ($flag_bloqueo_atencion !== null && intval($flag_bloqueo_atencion) === 1) :
        return response()->json(['message' => 'No puede ver la atención de este paciente.'], 403);
    endif;

    $model_paciente = new \App\Models\Paciente;
    $model_prestacion = new \App\Models\Prestaciones;
    $paciente = $model_paciente->getById($id_asegurado);
    $atenciones = $model_prestacion->GetAtencionesByIdAsegurado($paciente->id_asegurado);

    $id_usuario = Auth::user()->id;
    $accesos = DB::table('users')
    ->select('users.*')
    ->where('id',$id_usuario)
    ->first();
    return view('frontend.atenciones.hc_electronica', compact('paciente','atenciones','accesos'));
  }

