  public function obtener_servicios($id_beneficiario) {
    
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;
    
    $usuario = "SELECT * from asegurados where nro_doc_ident = '$id_beneficiario' and id_estado_reg = '1'";
    $usuario = DB::select($usuario);
    $usuario = $usuario[0];

    $tiempo="SELECT DATE_PART('YEAR',AGE('$usuario->fecha_nac'::date))";
    $tiempo = DB::select($tiempo);
    $tiempo=$tiempo[0]->date_part;

    if($usuario->sexo == 'F'){//ginecologia
      if($tiempo <= 14){//pediatria
        $servicios=" SELECT c.id,c.nombre
        from consultorios c where tipo = '1' and estado = '4' and id != '152' and id != '28' and id != '108' order by nombre asc";
        $servicios = DB::select($servicios);
      }else if($tiempo >= 60){//geriatria
        $servicios=" SELECT c.id,c.nombre
        from consultorios c where tipo = '1' and estado = '4' and id != '49' and id != '152' and id != '136'and id != '108' order by nombre asc";
        $servicios = DB::select($servicios);
      }else{//
        $servicios=" SELECT c.id,c.nombre
        from consultorios c where tipo = '1' and estado = '4' and id != '49' and id != '152' and id != '136' and id != '28' and id != '108' order by nombre asc";
        $servicios = DB::select($servicios);
      }

    }else{//no ginecologia
      if($tiempo <= 14){//pediatria
        $servicios=" SELECT c.id,c.nombre
        from consultorios c where tipo = '1' and estado = '4' and id != '152' and id != '28' and id != '77' and id != '131' and id != '108' order by nombre asc";
        $servicios = DB::select($servicios);
      }else if($tiempo >= 60){//geriatria
        $servicios=" SELECT c.id,c.nombre
        from consultorios c where tipo = '1' and estado = '4' and id != '49' and id != '152' and id != '136' and id != '77' and id != '131' and id != '108' order by nombre asc";
        $servicios = DB::select($servicios);
      }else{//
        $servicios=" SELECT c.id,c.nombre
        from consultorios c where tipo = '1' and estado = '4' and id != '49' and id != '152' and id != '136' and id != '28' and id != '77' and id != '131' and id != '108' order by nombre asc";
        $servicios = DB::select($servicios);
      }
    }
 
    return $servicios;

  }

