  public function modal_cita_horario_lista_cita_medico($id_ipress, $id_consultorio, $fecha_atencion, $documento)
  { 
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;
    
    $status = 0;
    $model_cita = new Cita();

    $aFechaAtencion = explode('-', $fecha_atencion);

    $feriados = $model_cita->GetFeriados($aFechaAtencion[0], $aFechaAtencion[1]);
    $dFecha = mktime(0, 0, 0, $aFechaAtencion[1], $aFechaAtencion[2], $aFechaAtencion[0]);
    $result = $model_cita->GetCitasMedicasDelMes($documento, $aFechaAtencion[0], $aFechaAtencion[1]);

    $aFeriado = null;
    foreach($feriados as $key => $value) {
      $aFeriado[$value->feriado] = 1;
    }
    unset($feriados);

    // Valida el máximo de citas del mes
    $result = $model_cita->ExisteCitaAllIpress($documento, $fecha_atencion, $id_ipress, $id_consultorio);
    // Valida el intervalo de dias entre citas
    $aDetalleFCalculo = $this->CalculoLimiteFechaCita($id_ipress, $fecha_atencion, $aFeriado);
    if ($aDetalleFCalculo['es_domingo']) {
      $status = 2; // La fecha de reserva es Domingo
    } else {
      if ($aDetalleFCalculo['es_feriado']) {
        $status = 2; // Fecha de reserva no permitido en Domingo o feriado
      }
    }

    if ($result) {
      $status = 7;
      //$status = 4;
      //return view('frontend.citas.modal_cita_horario_lista', compact('status', 'fecha_atencion'));
    } else {
      $result = $model_cita->ValidarCitasEnRango($documento, $id_ipress, $id_consultorio, $aDetalleFCalculo['fecha_inferior'], $aDetalleFCalculo['fecha_superior']);
      if (!empty($result)) {
        $status = 5;
        $aDetalle['intervalo_cita'] = $aDetalleFCalculo['intervalo_cita'];
        $aDetalle['paciente'] = $result->paciente;
        $aDetalle['servicio'] = $result->servicio;
        $aDetalle['medico'] = $result->medico;
        $aDetalle['fecha'] = Util::GetFechaTexto($result->fecha_hora);
        return view('frontend.citas.modal_cita_horario_lista', compact('status', 'fecha_atencion', 'aDetalle'));
      }
    }

    $medico_turno = new \App\Models\Medico_turno;
    $model_consultorio = new Consultorio;
    $consultorio = $model_consultorio->GetNombreById($id_consultorio);
    $turno = $medico_turno->GetTurnos();
    $fecha_atencion_1 = date('d-m-Y', strtotime($fecha_atencion));
    $aConsultorios = $medico_turno->GetSubConsultorioByIdConsultorio_fecha($id_consultorio, $id_ipress,$fecha_atencion_1,0);
    $aConsultorios = $this->ppQuitarConsultoriosProcedimiento($aConsultorios);
    

    $aHorarios = null;
    $aHorariosConfig = null;
    $oMedicoTurno = new \App\Models\Medico_turno;
    for($ic = 0; $ic < count($aConsultorios); $ic++) {
      $resultTurnos = $medico_turno->GetSubConsultorioTurnoByIdConsultorio2($aConsultorios[$ic]->id_consultorio,$aConsultorios[$ic]->id,$fecha_atencion,Auth::user()->id_establecimiento);
      


      $iHorario = 1;
      
      for($it = 0; $it < count($resultTurnos); $it++) {
        $horarios = $medico_turno->GetHorarioConsultorioByIdConsultorioTurno(
          $id_ipress, 
          $resultTurnos[$it]->id_sub_consultorio_turno,
          $fecha_atencion, 
          $resultTurnos[$it]->tiempo_atencion, 
          $resultTurnos[$it]->hora_ini, 
          $resultTurnos[$it]->hora_fin
        );
       
        
        foreach($horarios as $horario) {
          
          $aCadMedicoCita = explode("#", $horario->id_medico); 
          
          $event_click = '';
          $value_color = '';
          if ($aCadMedicoCita[1] == 0) {
            $value_color = 'color:#000000;cursor:pointer';
            $event_click = 'guardarCita(' . $aConsultorios[$ic]->id . ',\'' . $horario->fecha_cita . '\',' . $resultTurnos[$it]->id_turno . ')';
            
            //$asegurado = ''; 
          } else if ($aCadMedicoCita[1] >= 1) {
            
            $value_color = 'background:#E1D097;color:#000000;';
            //$asegurado = $horario->adni . ' - ' . $horario->anombre . ' ' . $horario->apaterno . ' ' . $horario->amaterno;
          }
          $aHorarios[$horario->medico]['medico'] = $horario->nombre . ' ' . $horario->paterno . ' ' . $horario->materno;
          $aHorarios[$horario->medico]['consultorios'][$aConsultorios[$ic]->id]['consultorio'] = $aConsultorios[$ic]->nombre;
          $aHorarios[$horario->medico]['consultorios'][$aConsultorios[$ic]->id]['horario'][] = [
           
            'hora' => $horario->fecha_hora . ' - ' . $horario->fecha_fin,
            'click' => $event_click,
            'color' => $value_color,
            //'asegurado' => $asegurado 
            
          ];
          
          $iHorario++;
        }        
      }
    }
    if ($status == 0 && empty($aHorarios)) {
        $status = 1; // No se tiene programado médicos en el horario
    }
    return view('frontend.citas.modal_cita_horario_lista_cita_medico', compact('fecha_atencion', 'aHorarios', 'status'));
  }
  public function modal_cita_horario_lista_cita_medico_cqx($id_ipress, $id_consultorio, $fecha_atencion, $documento, $id_intervencion)
  { 
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;
    
    $status = 0;
    $model_cita = new Cita();

    $aFechaAtencion = explode('-', $fecha_atencion);

    $feriados = $model_cita->GetFeriados($aFechaAtencion[0], $aFechaAtencion[1]);
    $dFecha = mktime(0, 0, 0, $aFechaAtencion[1], $aFechaAtencion[2], $aFechaAtencion[0]);
    $result = $model_cita->GetCitasMedicasDelMes($documento, $aFechaAtencion[0], $aFechaAtencion[1]);

    $aFeriado = null;
    foreach($feriados as $key => $value) {
      $aFeriado[$value->feriado] = 1;
    }
    unset($feriados);

    // Valida el máximo de citas del mes
    $result = $model_cita->ExisteCitaAllIpress($documento, $fecha_atencion, $id_ipress, $id_consultorio);
    // Valida el intervalo de dias entre citas
    $aDetalleFCalculo = $this->CalculoLimiteFechaCita($id_ipress, $fecha_atencion, $aFeriado);
    if ($aDetalleFCalculo['es_domingo']) {
      $status = 2; // La fecha de reserva es Domingo
    } else {
      if ($aDetalleFCalculo['es_feriado']) {
        $status = 2; // Fecha de reserva no permitido en Domingo o feriado
      }
    }

    if ($id_consultorio == 113) {
      $total_citas = 0;
      $total_citas = $model_cita->obtenerTotalCitas($id_consultorio, $fecha_atencion);
    }

    if ($result) {
      $status = 7;
      //$status = 4;
      //return view('frontend.citas.modal_cita_horario_lista', compact('status', 'fecha_atencion'));
    } else {
      $result = $model_cita->ValidarCitasEnRango($documento, $id_ipress, $id_consultorio, $aDetalleFCalculo['fecha_inferior'], $aDetalleFCalculo['fecha_superior']);
      if (!empty($result)) {
        $status = 5;
        $aDetalle['intervalo_cita'] = $aDetalleFCalculo['intervalo_cita'];
        $aDetalle['paciente'] = $result->paciente;
        $aDetalle['servicio'] = $result->servicio;
        $aDetalle['medico'] = $result->medico;
        $aDetalle['fecha'] = Util::GetFechaTexto($result->fecha_hora);
        return view('frontend.citas.modal_cita_horario_lista_cqx', compact('status', 'fecha_atencion', 'aDetalle'));
      }
    }
    $date = Carbon::now();
    $fecha_actual = $date->format('Y-m-d');
    $medico_turno = new \App\Models\Medico_turno;
    $model_consultorio = new Consultorio;
    $consultorio = $model_consultorio->GetNombreById($id_consultorio);
    $turno = $medico_turno->GetTurnos();
    $fecha_atencion_1 = date('d-m-Y', strtotime($fecha_atencion));
    $aConsultorios = $medico_turno->GetSubConsultorioByIdConsultorio_fecha_cqx($id_consultorio, $id_ipress,$fecha_atencion_1,0);//SP
  
    $aHorarios = null;
    $aHorariosConfig = null;
    $oMedicoTurno = new \App\Models\Medico_turno;

    $turnosParametros=array();
    for ($ic = 0; $ic < count($aConsultorios); $ic++) {
      $resultTurnos = $medico_turno->GetSubConsultorioTurnoByIdConsultorioCqx($aConsultorios[$ic]->id, $fecha_atencion, Auth::user()->id_establecimiento);//SP
      if (!empty($resultTurnos)) {
          foreach ($resultTurnos as $turno) {
              $turnosParametros[] = [
                  'id_sub_consultorio_turno' => $turno->id_sub_consultorio_turno,
                  'id_sub_consultorio' => $turno->id_sub_consultorio,
                  'tiempo_atencion' => $turno->tiempo_atencion,
                  'hora_ini' => $turno->hora_ini,
                  'hora_fin' => $turno->hora_fin,
                  'id_consultorio' => $aConsultorios[$ic]->id_consultorio,
                  'id_turno' => $turno->id_turno,
              ];
          }
      }
    }
   
    $filasSql = [];
    foreach ($turnosParametros as $value) {
        $fila = [
            $value['id_consultorio'],
            $value['id_turno'],
            $value['id_sub_consultorio_turno'],
            $value['id_sub_consultorio'],
            $fecha_atencion,  
            $value['tiempo_atencion'],
            $value['hora_ini'], 
            $value['hora_fin'],
        ];
        $cadena = implode('|', $fila);
        $cadena = '"' . str_replace('"','\"',$cadena) . '"';
        $filasSql[] = $cadena;
    }

    $p_consultorios_turnos = '{' . implode(',', $filasSql) . '}';
    $horarios = $medico_turno->GetHorarioConsultorioByIdConsultorioTurnoCqx($p_consultorios_turnos);//SP
    $contador_disponible = 0;
    foreach($horarios as $horario) {
      $iHorario=1;
      $aCadMedicoCita = explode("#", $horario->id_medico_agg); 
      $event_click = '';
      $value_color = '';
      $valor_adicional = '0';
      if ($aCadMedicoCita[1] == 0) { //disponible
        $value_color = 'color:#000000;cursor:pointer';
        $event_click = 'guardarCita(' . $horario->id_sub_consultorio . ',\'' . $horario->fecha_cita . '\',' . $horario->id_turno . ',' . $valor_adicional. ')';
        
        $asegurado = '';
        if($fecha_actual==$fecha_atencion){
          $contador_disponible++;
        }  

      } else if ($aCadMedicoCita[1] >= 1) { //ocupado
        //buscar en la tabla citas, los estados de atencion en el dia del consultorio
        $model_cita = new \App\Models\Cita;
        $asegurado ="";
          $cita_estado = $model_cita->GetCitasEstado($horario->fecha_cita, $horario->id_consultorio);
          if(count($cita_estado)>0):
            //0 : programado 1 : atendido 2 : extemporaneo 3 : no llego 4 : espera 
            switch($cita_estado[0]->estado_dia_paciente){
              case 0: $fechaActual_carbon =Carbon::now();
                      $fechahora= $horario->fecha_cita;
                      $fechaCita = Carbon::createFromFormat('Y-m-d H:i', $fechahora);
                      $siFechaCitaesMenor = $fechaCita->lte($fechaActual_carbon);
                      if($siFechaCitaesMenor && $cita_estado[0]->estado_dia_paciente == 0){
                        $value_color = 'background:#fac4c9;color:#000000;';
                      }
                      else
                      {
                        $value_color = 'background:#E1D097;color:#000000;';   
                      }
                      break;
              case 1: $value_color = 'background:#b0f2c2;color:#000000;'; break;
              case 2: $value_color = 'background:#ffed73;color:#000000;'; break;
              case 4: $value_color = 'background:#d4eafc;color:#000000;';break;
            } 
            $asegurado = $cita_estado[0]->nro_doc_ident . ' - ' . $cita_estado[0]->nombre . ' ' . $cita_estado[0]->paterno . ' ' . $cita_estado[0]->materno;
          else:
            $value_color = 'background:#E1D097;color:#000000;';
          endif;
      }

      $aHorarios[$horario->id_medico_agg]['medico'] = $horario->medico_nombre . ' ' . $horario->medico_paterno . ' ' . $horario->medico_materno;
      $aHorarios[$horario->id_medico_agg]['consultorios'][$horario->id_consultorio]['consultorio'] = $horario->sub_consultorio_nombre;
      $aHorarios[$horario->id_medico_agg]['consultorios'][$horario->id_consultorio]['horario'][] = [
      'hora' => $horario->fecha_hora . ' - ' . $horario->fecha_fin,
      'click' => $event_click,
      'color' => $value_color,
      'asegurado' => $asegurado 
      ];
      $iHorario++;
    }

    if ($status == 0 && empty($aHorarios)) {
        $status = 1; 
    }
    return view('frontend.citas.modal_cita_horario_lista_cita_medico_cqx', compact('fecha_atencion', 'aHorarios', 'status', 'id_consultorio', 'total_citas','fecha_actual','id_intervencion'));
  }

  public function obtener_prestacion($id_prestacion)
  {
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $prestacion = Prestaciones::where('id', '=', $id_prestacion)->first();
    $valida = $prestacion->ruta_prestacion == null ? false : true;
    return json_encode($valida);
  }
  
