//lrojas
public function eliminardiagnosticos(Request $request){

  $idprestacion = json_decode($request->idprestacion);

  $idcodigo = json_decode($request->codigo);
  $idFarmacia = Auth::user()->id_farmacia;
  $idusuario =Auth::user()->id;
  $motivo = 'eliminacion de diagnostico';

  

  $result = DB::table('prestacion_procedimientos as t1')
  ->select('t1.id as cod', 't1.id_procedimiento as id_procedimiento', 't2.codigo', 't2.descripcion as nombre', 't1.cantidad', 't3.id_diagnosticos as id_diagnostico')
  ->join('procedimientos as t2', 't1.id_procedimiento', '=', 't2.id')
  ->join('procedimientos_diagnoticos as t3', function ($join) {
      $join->on('t3.id_prestacion', '=', 't1.id_prestacion')
          ->on('t3.id_procedimientos', '=', 't1.id_procedimiento');
  })
  ->where('t1.id_prestacion', $idprestacion)
  ->where('t1.tipo_procedimiento', 1)
  ->where('t1.id_estado_reg', 1)
  ->get();


  foreach($result as $value){
    $id_prestacion_procedimiento = $value->cod;
