  ->select('id')
  ->where('id_prestacion', $idprestacion)
  ->get();

  $recetaValesIds = array_map(function($item) {
   return $item->id;
    }, $recetaVales);
    $recetavalesinvalidar = [];


    foreach ($recetaValesIds as $recetaValeId) {
      $productoReceta = DB::table('producto_recetas')
        ->where('id_receta_vale', $recetaValeId)
        ->where('id_diagnosticos', $idcodigo)
        ->first();
      if ($productoReceta) {
        $recetavalesinvalidar[] = $recetaValeId;
      }
    }

    foreach ($recetavalesinvalidar as $recetaValeIdx) {
      $newRequest = new Request([
        'id_prestacion' => $idprestacion,
        'id_farmacia' => $idFarmacia,
        'id_user' => $idusuario,
        'motivo' => $motivo,
        'id_receta' => $recetaValeIdx,
      ]);
  
      $this->invalidar_receta_digital($newRequest);
  
     
    }
  
  DB::table('receta_diagnosticos')
    ->where('id_prestacion', $idprestacion)
    ->where('id_diagnostico', $idcodigo)
    ->update([
        'estado' => 2,
    ]);

    // Recuperar el estado actualizado
    $updatedEstado = DB::table('receta_diagnosticos')
    ->where('id_prestacion', $idprestacion)
    ->where('id_diagnostico', $idcodigo)
    ->value('estado');




  echo json_encode($updatedEstado);

}

