public function guardar_nuevos_diagnosticos(Request $request){



  if (!Auth::check()) :
    return redirect('/auth/login');
  endif;

  $id_prestacion =0;
  $iduser =  Auth::user()->id;
  $model_prestacion = new \App\Models\Prestaciones;
  $nombreDiagnosticoValues = $request->input('nombre_diagnostico_array');
  $tipodiagnostico = $request->input('id_tipo_diagnostico_array');
  $idprestacionuevo = $request->input('idprestacionnuevo');

 

  $idiagnosticosCodigos = array_map(function($diagnostico) {
      return trim(substr($diagnostico, 0, strpos($diagnostico, '-')));
  }, $nombreDiagnosticoValues);
  
  $idiagnosticos =[];
  
  foreach ($idiagnosticosCodigos as $codigo) {
      $diagnostico = DB::table('diagnosticos')
                        ->where('codigo', $codigo)
                        ->first();
  
      if ($diagnostico) {
          $idiagnosticos[] = $diagnostico->id;
      }
  }

  
  $p_diagnostico = "";
  $p_diagnostico .= "{";
  if (isset($idiagnosticos)) :
    foreach ($idiagnosticos as $key => $value) :
      if ($idiagnosticos[$key] != "") {
        $p_diagnostico .= "{";
        $p_diagnostico .= $idiagnosticos[$key] . ",";
        $p_diagnostico .= (isset($tipodiagnostico[$key]) && $tipodiagnostico[$key] > 0) ? $tipodiagnostico[$key] : "0";
        $p_diagnostico .= "},";
      }
    endforeach;
    if (strlen($p_diagnostico) > 1) $p_diagnostico = substr($p_diagnostico, 0, -1);
  endif;
  $p_diagnostico .= "}";

  
  $id_prestacion = $model_prestacion->registrardiagnosticoNuevo($p_diagnostico,$iduser,$idprestacionuevo);


  if ($id_prestacion == 0) {
    echo json_encode('No se pudo registrar la Prestacion, hubo un problema con la conexión de internet de su establecimiento PNP, vuelva a intentarlo nuevamente');
  } else {
    echo json_encode('Se guardo correctamente el diganostico');
  }


}

