    $id_receta_vale = $receta->postRegistrarRecetaValeNuevoConDiagnostico($id_receta_vale, $request->farmaciavalor, $request->id_user, $id_consultorio, $nro_receta, $digitos_adicionales, $dni_beneficiario, $cip_beneficiario, $tipodoc_beneficiario, $nombre_beneficiario, $paterno_beneficiario, $materno_beneficiario, $tipo_beneficiario, $dni_titular, $tipdoc_titular, $nombre_titular, $paterno_titular, $materno_titular, $request->fechexpedicion, $fecha_atencion, $nro_historia, $grado, $id_medico, $id_anestesiologo, $id_tiporeceta, $turno, $obs_registro, $id_receta_vale_bus, $id_admision, $tipo_via, $sub_via, $final_via, $nro_guia, $interconsulta, $interconsulta_dias, $id_prestacion, $id_tipo_num, $estado_receta, $p_detalle, $p_diagnostico, $sexo, $fecha_nacimiento, $codigo_upss);
    
  else :
    $id_receta_vale = 1;
  endif;


  if ($id_receta_vale > 0) {
    if ($request->id_sub_consultorio != 976) {//telecon
      Session::flash('flash_message', 'Prestación exitosa');
      return redirect('/ver_prestacion/' . $request->id_user . '/' . $id_prestacion);
    } else {
      Session::flash('flash_message', 'Prestación exitosa');
      return redirect('/ver_prestacion_teleconsulta/' . $request->id_user . '/' . $id_prestacion);
    }
  }
