  public function formulario_atencion_tomado($id_cita, $id_medico, $id_sub_consultorio)
  {

    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $id_user = Auth::user()->id;
    $id_farmacia = Auth::user()->id_farmacia;

    $model_consultorio = new Consultorio;
    $model_cita = new \App\Models\Cita;
    $cita = $model_cita->GetCitasById($id_cita);
    
    if ($id_medico > 0) {
      $model_medico = new Medico;
      $medico = $model_medico->MostrarMedico($id_medico);
      
      $cita->id_medico = $medico->id;
      $cita->medico_nombre = $medico->nombre;
      $cita->medico_paterno = $medico->paterno;
      $cita->medico_materno = $medico->materno;
      $cita->dni = $medico->dni;
      $cita->colegiatura = $medico->colegiatura;
      $cita->rne = $medico->rne;
      $cita->especializacion = $medico->especializacion;
      $cita->profesion = $medico->profesion;

      $model_subconsultorio = new SubConsultorio;
      $sub_consultorio = $model_subconsultorio->GetNombreById($id_sub_consultorio);
      $cita->id_sub_consultorio = $sub_consultorio->id;
      $cita->consultorio = $sub_consultorio->descripcion;
    }

    $model_prestacion = new Prestaciones;
    $prestacion = $model_prestacion->GetPrestacionByIdCita($id_cita);

    $model_kardex = new Kardexe();
    $fechaServidor = $model_kardex->getFechaServidor();

    $model_farma = new Farmacia();
    $farmacia = $model_farma->GetFarmaByIdfarma($id_farmacia);
    $id_ipress = $farmacia->id_establecimiento;
    //$farmacia = $model_farma->GetFarmaByUser($id_user);
    //$id_farmacia = $farmacia->id;

    $model_producto = new Producto;
    $model_establecimiento = new \App\Models\Establecimiento;
    $establecimiento = $model_establecimiento->GetById($id_ipress);
    $establecimientos = $model_establecimiento->ShowAllEstablecimientos();

    $tipo_atencion = $model_farma->GetFarmaciaTipoAtencionByIdFarmacia($id_farmacia);
    //print_r($tipo_atencion);exit();
    if ($id_ipress == 1) {
      $nivel = 2;
    } else {
      $nivel = $establecimiento[0]->nivel;
    }

    $id_tipo_atencione=1;

    //$id_consultorio=8;
    $producto = $model_producto->getProductosByNivelAndIdServicio($nivel, $cita->id_servicio, $id_farmacia);
    $consultorio = $model_consultorio->ShowConsultorios($id_farmacia);
    $farmacias = $model_farma->GetFarmaciaByIdEstablecimiento($farmacia->id_establecimiento);
    $codigo_upss = $model_consultorio->ShowCodigoUpssIdTipoAtencion($cita->id_servicio,$id_tipo_atencione);
    
    if(count($codigo_upss)==0){
      return redirect('/all_citas_medico_paciente/')->withInput()->withErrors(array('Debe registrar un upss..!'));
    }

    $model_prestacion = new Prestaciones;

    // Cantidad de atenciones en el Establecimiento o IPRESS
    $cant_atenciones_ipress = $model_prestacion->GetCountAtencionesPorAnioActual($cita->nro_doc_ident, $farmacia->id_establecimiento, $id_tipo_atencione);

    if ($cant_atenciones_ipress->atenciones > 0):
      $ipress_bene = 'CONTINUADOR';
    else:
      $cant_atenciones_ipress2 = $model_prestacion->GetCountAtencionesActual($cita->nro_doc_ident, $farmacia->id_establecimiento, $id_tipo_atencione);
      if ($cant_atenciones_ipress2->atenciones == 0):
        $ipress_bene = 'NUEVO';
      else:
        $ipress_bene = 'REINGRESO';
      endif;
    endif;

    // Cantidad de atenciones en el Servicio o UPSS
    $cant_atenciones_servicio = $model_prestacion->GetCountAtencionesPorAnioActual($cita->nro_doc_ident, $farmacia->id_establecimiento, $id_tipo_atencione, $cita->id_sub_consultorio);

    if ($cant_atenciones_servicio->atenciones > 0):
      $upss_bene = 'CONTINUADOR';
    else:
      $cant_atenciones_servicio2 = $model_prestacion->GetCountAtencionesActual($cita->nro_doc_ident, $farmacia->id_establecimiento, $id_tipo_atencione, $cita->id_sub_consultorio);
      if ($cant_atenciones_servicio2->atenciones == 0):
        $upss_bene = 'NUEVO';
      else:
        $upss_bene = 'REINGRESO';
      endif;
    endif;

    if($id_tipo_atencione==1){
      if($cita->id_tipo_cita!=''){
        $modalidad = $cita->id_tipo_cita;
      }
      else{
        $modalidad = 0;
      }
    }
    else{
      $modalidad =0;
    }

    $aEscala = $this->formulario_atencion_escalas();

    $client = new SoapClient(env('WI_SALUDPOL_URL') . "/ws/WS_AfiliadoSP_Serv.php?wsdl", array('login' => env('WI_SALUDPOL_USERNAME'), 'password' => env('WI_SALUDPOL_PASSWORD')));
    try { $beneficiario = $client->getAseguradoValidate($cita->tipo_doc_ident, $cita->nro_doc_ident); } catch(Exception $e) { $beneficiario = new \stdClass(); }

    if (is_object($beneficiario)) :
      $flag = 1 ;
    else:
      $flag = 0 ;
    endif;
    return view('frontend.atenciones.form_atencion_tomado', compact('aEscala', 'fechaServidor', 'codigo_upss','producto', 'cita', 'consultorio', 'id_cita', 'tipo_atencion', 'farmacias', 'nivel','id_tipo_atencione','establecimientos','ipress_bene','upss_bene','modalidad','flag','prestacion'));
  }

  public function modal_cita_horario_lista_referencia($id_ipress, $id_consultorio, $fecha_atencion, $documento)
  {
    $status = 0;$sw = 0;
    $model_cita = new Cita();

    $aFechaAtencion = explode('-', $fecha_atencion);

    $feriados = $model_cita->GetFeriados($aFechaAtencion[0], $aFechaAtencion[1]);
    $dFecha = mktime(0, 0, 0, $aFechaAtencion[1], $aFechaAtencion[2], $aFechaAtencion[0]);
    $result = $model_cita->GetCitasMedicasDelMes($documento, $aFechaAtencion[0], $aFechaAtencion[1]);

    $aFeriado = null;
    foreach($feriados as $key => $value) {
      $aFeriado[$value->feriado] = 1;
    }
    unset($feriados);

    // Valida el máximo de citas del mes
    $result = $model_cita->ExisteCitaAllIpress($documento, $fecha_atencion, $id_ipress, $id_consultorio);
    // Valida el intervalo de dias entre citas
    $aDetalleFCalculo = $this->CalculoLimiteFechaCita($id_ipress, $fecha_atencion, $aFeriado);
  
    if($id_consultorio != 114){
      
      if ($aDetalleFCalculo['es_domingo']) {
        $status = 2; // La fecha de reserva es Domingo
      } else {
        if ($aDetalleFCalculo['es_feriado']) {
          $status = 2; // Fecha de reserva no permitido en Domingo o feriado
        }
      }
  
    }

    if ($result) {
      $status = 7;
      //$status = 4;
      //return view('frontend.citas.modal_cita_horario_lista', compact('status', 'fecha_atencion'));
    } else {
      $result = $model_cita->ValidarCitasEnRango($documento, $id_ipress, $id_consultorio, $aDetalleFCalculo['fecha_inferior'], $aDetalleFCalculo['fecha_superior']);
      if (!empty($result)) {
        $status = 5;
        $aDetalle['intervalo_cita'] = $aDetalleFCalculo['intervalo_cita'];
        $aDetalle['paciente'] = $result->paciente;
        $aDetalle['servicio'] = $result->servicio;
        $aDetalle['medico'] = $result->medico;
        $aDetalle['fecha'] = Util::GetFechaTexto($result->fecha_hora);
        return view('frontend.citas.modal_cita_horario_lista_referencia', compact('status', 'fecha_atencion', 'aDetalle'));
      }
    }

    $medico_turno = new \App\Models\Medico_turno;
    $model_consultorio = new Consultorio;
    $consultorio = $model_consultorio->GetNombreById($id_consultorio);
    $turno = $medico_turno->GetTurnos();
    
    $date = Carbon::now();
    $fecha_actual = $date->format('Y-m-d');
    //Lista de consultorios de un servicio
    $aConsultorios = $medico_turno->GetSubConsultorioByIdConsultorio($id_consultorio, $id_ipress);
    
    $aHorarios = null;
    $aHorariosConfig = null;
    $oMedicoTurno = new \App\Models\Medico_turno;
    for($ic = 0; $ic < count($aConsultorios); $ic++) {
      //$resultTurnos = $medico_turno->GetSubConsultorioTurnoByIdConsultorio($aConsultorios[$ic]->id);
      //$resultTurnos = $medico_turno->GetSubConsultorioTurnoByIdConsultorio2($aConsultorios[$ic]->id,"",Auth::user()->id_establecimiento);
      $resultTurnos = $medico_turno->GetSubConsultorioTurnoByIdConsultorio2($aConsultorios[$ic]->id_consultorio, $aConsultorios[$ic]->id,$fecha_atencion,Auth::user()->id_establecimiento);
	    
      if($fecha_atencion>='2023-09-01'):
        if($aConsultorios[$ic]->id==1295 || $aConsultorios[$ic]->id==1296):
           $sw=1;
        else:
            $sw=0;
        endif;
	    endif;

      $iHorario = 1;
      
      if($sw==0):
        for($it = 0; $it < count($resultTurnos); $it++) {
          //valido que tenga los consultorios tenga tiempo de atencion
          if($resultTurnos[$it]->tiempo_atencion != ''):
            $horarios = $medico_turno->GetHorarioConsultorioByIdConsultorioTurno(
              $id_ipress, 
              $resultTurnos[$it]->id_sub_consultorio_turno,
              $fecha_atencion, 
              $resultTurnos[$it]->tiempo_atencion, 
              $resultTurnos[$it]->hora_ini, 
              $resultTurnos[$it]->hora_fin
            );
            
            $contador_disponible = 0;
            foreach($horarios as $horario) {
              
              $aCadMedicoCita = explode("#", $horario->id_medico); 
              $event_click = '';
              $value_color = '';
              $valor_adicional = '0';
              if ($aCadMedicoCita[1] == 0) { //disponible
                $value_color = 'color:#000000;cursor:pointer';
                $event_click = 'guardarCita(' . $aConsultorios[$ic]->id . ',\'' . $horario->fecha_cita . '\',' . $resultTurnos[$it]->id_turno . ',' . $valor_adicional. ')';
                
                $asegurado = '';
                if($fecha_actual==$fecha_atencion){
                  $contador_disponible++;
                }
                  

              } else if ($aCadMedicoCita[1] >= 1) { //ocupado
                //buscar en la tabla citas, los estados de atencion en el dia del consultorio
                $model_cita = new \App\Models\Cita;
                $asegurado ="";
                  $cita_estado = $model_cita->GetCitasEstado($horario->fecha_cita, $aConsultorios[$ic]->id);
                  if(count($cita_estado)>0):
                    //0 : programado 1 : atendido 2 : extemporaneo 3 : no llego 4 : espera 
                    switch($cita_estado[0]->estado_dia_paciente){
                      case 0: $fechaActual_carbon =Carbon::now();
                              $fechahora= $horario->fecha_cita;
                              $fechaCita = Carbon::createFromFormat('Y-m-d H:i', $fechahora);
                              $siFechaCitaesMenor = $fechaCita->lte($fechaActual_carbon);
                              if($siFechaCitaesMenor && $cita_estado[0]->estado_dia_paciente == 0){
                                $value_color = 'background:#fac4c9;color:#000000;';
                              }
                              else
                              {
                                $value_color = 'background:#E1D097;color:#000000;';   
                              }
                              break;
                      case 1: $value_color = 'background:#b0f2c2;color:#000000;'; break;
                      case 2: $value_color = 'background:#ffed73;color:#000000;'; break;
                      case 4: $value_color = 'background:#d4eafc;color:#000000;';break;
                    } 
                    $asegurado = $cita_estado[0]->nro_doc_ident . ' - ' . $cita_estado[0]->nombre . ' ' . $cita_estado[0]->paterno . ' ' . $cita_estado[0]->materno;
                  else:
                    $value_color = 'background:#E1D097;color:#000000;';
                  endif;
                //$value_color = 'background:#E1D097;color:#000000;';
              }

              $aHorarios[$horario->medico]['medico'] = $horario->nombre . ' ' . $horario->paterno . ' ' . $horario->materno;
              $aHorarios[$horario->medico]['consultorios'][$aConsultorios[$ic]->id]['consultorio'] = $aConsultorios[$ic]->nombre;
              $aHorarios[$horario->medico]['consultorios'][$aConsultorios[$ic]->id]['horario'][] = [
              'hora' => $horario->fecha_hora . ' - ' . $horario->fecha_fin,
              'click' => $event_click,
              'color' => $value_color,
              'asegurado' => $asegurado 
              ];
              $iHorario++;
            }
            
            //buscar en la tabla consultorio, si aplican los adicionales
            $model_subconsultorio = new \App\Models\SubConsultorio;
            $model_cita_paciente = new \App\Models\Cita;
            $adicional_subconsultorio = $model_subconsultorio->GetAdicional($aConsultorios[$ic]->id);
            
            if($adicional_subconsultorio->adicional==1):
                
              if($contador_disponible==0):
                
                if($fecha_actual==$fecha_atencion){
                  
                  $valor_adicional = '1';
                  $value_color = 'background:#0ba8e2;color:#FFFFFF;';
                  $total_paciente = $model_cita_paciente->GetNumeroPaciente($horario->medico, $fecha_actual,$aConsultorios[$ic]->id );
                  
                  for($i=0; $i<$total_paciente->adicional; $i++ ) {
                    //$aHorarios[$horario->medico]['medico'] = $horario->nombre . ' ' . $horario->paterno . ' ' . $horario->materno;
                    //$aHorarios[$horario->medico]['consultorios'][$aConsultorios[$ic]->id]['consultorio'] = $aConsultorios[$ic]->nombre;
                    $fecha_hora = 'ADICIONAL';
                    $fecha_fin = $i+1;
                  
                    $aHorarios[$horario->medico]['consultorios'][$aConsultorios[$ic]->id]['horario'][] = [
                    'hora' => $fecha_hora . ' - ' . $fecha_fin,
                    'click' => $event_click,
                    'color' => $value_color,
                    'asegurado' => '' 
                    ];
                  }

                  $fecha_hora = '+ REGISTRAR';
                  $fecha_fin = 'CITA ADICIONAL';
                  
                  $value_color = 'background:#41C94B;color:#FFFFFF;cursor:pointer';
                  $event_click = 'guardarCita(' . $aConsultorios[$ic]->id . ',\'' . $horario->fecha_cita . '\',' . $resultTurnos[$it]->id_turno . ',' . $valor_adicional. ')';
                  $aHorarios[$horario->medico]['medico'] = $horario->nombre . ' ' . $horario->paterno . ' ' . $horario->materno;
                  $aHorarios[$horario->medico]['consultorios'][$aConsultorios[$ic]->id]['consultorio'] = $aConsultorios[$ic]->nombre;
                  $aHorarios[$horario->medico]['consultorios'][$aConsultorios[$ic]->id]['horario'][] = [
                  'hora' => $fecha_hora . ' - ' . $fecha_fin,
                  'click' => $event_click,
                  'color' => $value_color,
                  'asegurado' => '' 
                  ];
                }
              endif;
            endif;
          endif;  
        }
      else:
          $sw=0;
      endif;
    }
    
    if ($status == 0 && empty($aHorarios)) {
        $status = 1; // No se tiene programado médicos en el horario
    }
    return view('frontend.citas.modal_cita_horario_lista_referencia', compact('fecha_atencion', 'aHorarios', 'status'));
  }
  
