  public function modal_siteds($id,$id_asegurado,$retorno)
  {
    $citas = \App\Models\Cita::find($id);
    $establecimiento = \App\Models\Establecimiento::find($citas->id_establecimiento); // TAGSITEDS
    $subConsultorio = \App\Models\SubConsultorio::find($citas->id_sub_consultorio); // TAGSITEDS
    $consultorio = \App\Models\Consultorio::find($subConsultorio->id_consultorio); // TAGSITEDS

    $modelCita = new Cita();
    $asegurado = \App\Models\Asegurado::find($id_asegurado);
    $codigo = null; $codigo_siteds = null;
    $fecha_atencion = date('d-m-Y', strtotime($citas->fecha_hora));
    $codigo = $modelCita->busca_Siteds_Atencion($asegurado->nro_doc_ident,$fecha_atencion);

