        return view('frontend.atenciones.edit_atencion', compact('farmacia','dato_texto_obs','cita','diagnostico_prestacion_referencia','procedimientos_refencia','referencias' ,'dato_servicio_ref','prestacion', 'prestaciones','diagnostico', 'procedimiento', 'medicamentos', 'id_prestacion', 'fechaServidor', 'receta', 'producto', 'farmacias', 'nivel', 'laboratorio', 'radiologia', 'flag_pendinte_firma','establecimientos','interconsultas','referencia','diagnosticos','procedimientos', 'gestacion', 'flag_laboratorio', 'flag_firmar_laboratorio','datos_oftalmo','ids_adicionales_diagnostico'));
