  public function editar_prestacion(Request $request)
  {
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;
    $id_prestacion = $request->id_prestacion;

    $model_prestacion = new \App\Models\Prestaciones;
    $data_prestacion_modificada = $model_prestacion->existePrestacionModificada($id_prestacion);
    if (count($data_prestacion_modificada) == 0) {
      $model_medico = new Medico();
      $profesional = $model_medico->GetDatosMedicoByDniAndEstablecimiento(Auth::user()->dni, Auth::user()->id_establecimiento);

      $p_diagnostico = "";
      $p_diagnostico .= "{";
      if (isset($request->id_diagnostico)):
        foreach ($request->id_diagnostico as $key => $value) :
          if ($request->id_diagnostico[$key] != "") {
            $p_diagnostico .= "{";
            $p_diagnostico .= $request->id_diagnostico[$key] . ",";
            $p_diagnostico .= (isset($request->id_tipo_diagnostico[$key]) && $request->id_tipo_diagnostico[$key] > 0) ? $request->id_tipo_diagnostico[$key] : "0";
            $p_diagnostico .= "},";
          }
        endforeach;
        if (strlen($p_diagnostico) > 1) $p_diagnostico = substr($p_diagnostico, 0, -1);
      endif;
      $p_diagnostico .= "}";

      $id_modificar_prestacion = $model_prestacion->updatePrestacionDiagnostico($id_prestacion, $p_diagnostico, $profesional->id, $request->motivo_modificacion);

      if ($id_modificar_prestacion > 0) {
        Session::flash('flash_message', 'Prestación modificada');
        return redirect('/ver_prestacion_modificada/' . $id_prestacion);
      } else {
        return redirect('/edit_prestacion/' . $id_prestacion)->withInput()->withErrors(array('Ha ocurrido un error al modificar la prestación.'));
      }
    } else {
      Session::flash('flash_message', '<b>La prestación ya fue modificada anteriormente el '.date('d-m-Y H:i a',strtotime($data_prestacion_modificada[0]->created_at)).'</b>');
      return redirect('/ver_prestacion_modificada/' . $id_prestacion);
    }
  }

  public function ver_prestacion_modificada($id_prestacion)
  {
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $obj_prestacion = Prestaciones::find($id_prestacion);
    // Verificamos que la prestacion este modificada
    if ($obj_prestacion->id_estado_reg == 1 && $obj_prestacion->estado_update == 1) {
      if (Auth::user()->tipo_registro == 1) {
