  public function verificaPendienteAltaEmergenciaHospitalizacionByDni(Request $request){
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;
    //VALIDA SI EL PACIENTE TIENE PENDIENTE DE ALTA EN EMERGENCIA y HOSPITALIZACION
    $pendiente_alta_hospitalizacion = DB::table('hospitalizaciones')
      ->where('dni_beneficiario', $request->dni)
      ->where('estado', 4)
      ->exists();

    $pendiente_alta_emergencia = DB::table('emergencias')
    ->where('dni_beneficiario',$request->dni)
    ->where('estado', 3)
    ->exists();
    $listaPendienteAlta = $this->listaPendienteAlta($request->dni);
    return response()->json(['pendiente_alta_emergencia' => $pendiente_alta_emergencia,'pendiente_alta_hospitalizacion' => $pendiente_alta_hospitalizacion,'lista_pendiente_alta'=>$listaPendienteAlta]);
  }
  public function getDatosPaciente($id_asegurado)
    {
        $data =  DB::select("select 
    asegurados.fecha_nac  as fecha_nacimiento,  
    ts.descripcion_corta as tipo_sangre,
    tb.descripcion as parentesgo,
    to_char(age(TO_DATE(asegurados.fecha_nac , 'DD/MM/YYYY')), 'YY \"A\"')  as edad_corta,
    to_char(age(TO_DATE(asegurados.fecha_nac , 'DD/MM/YYYY')), 'YY \"años\" \"con\" MM \"meses\"  \"y\" DD \"dias\"') 
    as fec_nacim_descrip,
    LTRIM(asegurado_historias.nro_historia) as nro_historia, asegurados.nro_doc_ident,
    asegurados.paterno,asegurados.materno,asegurados.nombre,asegurados.sexo
    FROM asegurados INNER JOIN asegurado_historias ON asegurado_historias.id_asegurado = asegurados.id
    left join tipo_beneficiarios tb on tb.id =asegurados.id_tipo_beneficiario
    left join tipo_sangres ts on asegurados.id_tipo_sangre = ts.id
    WHERE asegurados.id_estado_reg=1 and asegurados.id = :id_asegurado
    ", ['id_asegurado' => $id_asegurado]);
        return $data[0];
    }

  public function listaPendienteAlta($dni){
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    $data = DB::table('hospitalizaciones as h')
    ->join('consultorios as c', 'h.id_servicio_destino', '=', 'c.id')
    ->join('establecimientos as e', 'h.id_establecimiento', '=', 'e.id')
    ->where('h.dni_beneficiario', $dni)
    ->where('h.estado', 4)
    ->select([
        DB::raw("'hospitalizacion' as tipo"), 
        'h.estado',
        'e.nombre as establecimiento_descripcion',
        'c.nombre as servicio_descripcion',
        DB::raw("TO_CHAR(h.fecha_ingreso, 'DD/MM/YYYY') as fecha_registro_ingreso"),
        'h.hora_ingreso as hora_registro_ingreso',
        DB::raw('NULL as hora_egreso_medico') 
    ])
    ->union(
        DB::table('emergencias as em')
            ->join('establecimientos as e', 'e.id', '=', 'em.id_establecimiento')
            ->join('triajes as t', 't.id', '=', 'em.id_triaje')
            ->where('em.dni_beneficiario', $dni)
            ->whereNull('em.fecha_alta_medica')
            ->where('em.estado', 3)
            ->select([
                DB::raw("'emergencia' as tipo"),
                'em.estado',
                'e.nombre as establecimiento_descripcion',
                't.descripcion as servicio_descripcion',
                DB::raw("TO_CHAR(em.fecha_registro_ingreso, 'DD/MM/YYYY') as fecha_registro_ingreso"),
                'em.hora_registro_ingreso',
                'em.hora_egreso_medico'
            ])
    )
    ->orderBy('fecha_registro_ingreso', 'asc')
    ->get();
    return $data;
  }
  function getLastRecipeAseguradoIdAndTypeAttention($id_asegurado, $id_tipo_atencion) {
    $receta = Receta_vale::select('receta_vales.id as id_receta_vale', 'receta_vales.id_farmacia', 'receta_vales.id_user', 'p.id as id_prestacion', 'p.id_tipo_atencion')
      ->join('prestaciones as p', 'receta_vales.id_prestacion', '=', 'p.id')
      ->where('receta_vales.id_asegurado', $id_asegurado)
      ->where('p.id_tipo_atencion', $id_tipo_atencion)
      ->orderBy('receta_vales.id', 'desc')
      ->first();
    if (!isset($receta)) {
      return response()->json([
          "message" => "No se encontró ninguna receta para el asegurado."
      ], 404);
    }
    $producto_receta_model = new Producto_receta();
    $productos = $producto_receta_model->ShowMedicinasById_receta_vale($receta->id_receta_vale);
    if (isset($productos) && count($productos)) {
      $receta["productos"] = $productos;
    }
    return response()->json([
      "message" => "se obtuvo la ultima receta",
      "data" => $receta
    ]);
  }
    function getNewReceta($dni_beneficiario, $id_tipo_atencion) {
      $asegurado = Asegurado::where('nro_doc_ident', $dni_beneficiario)
          ->where('id_estado_reg', 1)
          ->first();

      if (!isset($asegurado)) {
          return response()->json([
              "message" => "No se encontró al asegurado."
          ], 404);
      }

      $receta = Receta_vale::select(
          'receta_vales.id as id_receta_vale',
          'receta_vales.id_farmacia',
          'receta_vales.id_user',
          'p.id as id_prestacion',
          'p.id_tipo_atencion'
      )
          ->join('prestaciones as p', 'receta_vales.id_prestacion', '=', 'p.id')
          ->where('receta_vales.id_asegurado', $asegurado->id)
          ->where('p.id_tipo_atencion', $id_tipo_atencion)
          ->where('p.id_servicio', 106)
          ->orderBy('receta_vales.id', 'desc')
          ->first();

      if (!isset($receta)) {
          return response()->json([
              "message" => "No se encontró ninguna receta para el asegurado."
          ], 404);
      }

      $producto_receta_model = new Producto_receta();
      $productos = $producto_receta_model->ShowMedicinasById_receta_vale($receta->id_receta_vale);

      if (isset($productos) && count($productos)) {
          $receta["productos"] = $productos;
      }

      return response()->json([
          "message" => "se obtuvo la ultima receta",
          "data" => $receta
      ]);
    }

