  function pg_escape_text($text) {
    $text = str_replace('"', '\"', $text);
    return '"' . $text . '"';
  }

  /**
   * Registrar intervención quirúrgica y atenciones adicionales.
   *
   * @param Request $request
   * @param RegistrarCqxIntervencionesHistorialAtencionesUseCase $useCase
   * @return \Illuminate\Http\JsonResponse
   */
  function registrarIntervencionQuirurgicaAtencionAdicional(Request $request, RegistrarCqxIntervencionesHistorialAtencionesUseCase $useCase) 
  {
    try {
      $data = $request->all();
      $result = $useCase->execute($data);

      return response()->json($result, $result['success'] ? 201 : 500);
    } catch (\Exception $e) {
      return response()->json([
        'success' => false,
        'message' => 'Error al registrar la intervención quirúrgica.',
        'error' => $e->getMessage(),
      ], 500);
    }
  }

  public function receta_anular_json(Request $request)
  {
    if (!Auth::check()) :
      return redirect('/auth/login');
    endif;

    DB::beginTransaction();
    $anulacion_valida = false;
    $mensaje_error = "";

    try {
      $receta_id = $request->receta_id;
      $farmacia_id = $request->farmacia_id;
      $receta = Receta_vale::find($receta_id);
      if ($receta->estado == 1):
        throw new \Exception("La Receta ha sido dispensada ya no se puede anular.");
      else:
        $existe_receta_devuelta = DB::table('receta_devueltas')
          ->where('id_receta_vale', $receta_id)
          ->where('id_farmacia', $farmacia_id)->first();

        if ($existe_receta_devuelta == false):
          $date = Carbon::now();
          $fecha = $date->format('d-m-Y');
          $devolver = new \App\Models\Receta_devuelta();
          $devolver->id_receta_vale = $receta_id;
          $devolver->fecha_devolucion = $fecha;
          $devolver->id_farmacia = $farmacia_id;
          $devolver->id_user = Auth::user()->id;
          $devolver->motivo = $request->receta_motivo_anula;
          if (!$devolver->save()):
            throw new \Exception("La Receta ha sido dispensada ya no se puede anular.");
          endif;
          
          $receta->estado = 0; //Receta devuelta o anulada
          if (!$receta->save()):
            throw new \Exception("La Receta no se ha podido anular.");
          endif;
        else:
          throw new \Exception("La Receta ya fue anulada en otra oportunidad, no es posible anularla.");
        endif;
      endif;

      DB::commit();
      $anulacion_valida = true;

    } catch (\Exception $e) {
      DB::rollback();
      Log::error("Anulacion Receta => receta_id: " . $request->receta_id . 
          "\n\nmensaje: " . $e->getMessage() . 
          "\n\ndatos del request: " . json_encode($request->all()) . 
          "\n\nstack trace: " . $e->getTraceAsString()
      );
      $mensaje_error = $e->getMessage();
    } catch (\Throwable $th) {
      DB::rollback();
      Log::critical("Anulacion Receta => receta_id: " . $request->receta_id . 
          "\n\nmensaje: " . $th->getMessage() . 
          "\n\ndatos del request: " . json_encode($request->all()) . 
          "\n\nstack trace: " . $th->getTraceAsString()
      );
      $mensaje_error = $th->getMessage();
    }

    if ($anulacion_valida):
      return response()->json([
        'success' => true,
        'message' => "La Receta ha sido anulada correctamente"
      ]);
    else:
      return response()->json([
        'success' => false,
        'message' => $mensaje_error
      ]);
    endif;
  }

  public function servicioFlagCentroQuirurgico($id_servicio){
      $esQuirurgico = DB::table('consultorios')
      ->where('flag_quirurgico', 1)
      ->where('id', $id_servicio)
      ->exists();
      return response()->json([
          'id_servicio' => $id_servicio,
          'quirurgico' => $esQuirurgico ? 'SI' : 'NO'
      ]);
  }

