  function obtenerRecetaById($id, ObtenerRecetaValeByIdUseCase $useCase)
  {
    try {
      $result = $useCase->execute($id);

      return response()->json([
        "success" => true,
        "message" => "Receta obtenida correctamente.",
        "data" => $result
      ], 200);

    } catch (SigesapolException $e) {
      return response()->json([
        "success" => false,
        "message" => $e->getMessage()
      ], $e->getStatus());
    } catch (Exception $e) {
      return response()->json([
        "success" => false,
        "message" => $e->getMessage() ?: "Error inesperado en el servidor."
      ], 500);
    }
  }

  /**
   * @param Request $request
   * @param ActualizarRecetaValeUseCase $useCase
  */
  function actualizarRecetaVale(Request $request, ActualizarRecetaValeUseCase $useCase)
  {
    try {
      $result = $useCase->execute($request);

      return response()->json([
        "success" => true,
        "message" => "Se actualizo la receta exitosamente.",
        "data" => $result
      ], 200);

    } catch (SigesapolException $e) {
      return response()->json([
        "success" => false,
        "message" => $e->getMessage()
      ], $e->getStatus());
    } catch (Exception $e) {
      return response()->json([
        "success" => false,
        "message" => $e->getMessage() ?: "Error inesperado en el servidor."
      ], 500);
    }
  }
